INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('01/01/2019', 'Dia do Município', 'MUNICIPAL', 'Dia do Municipio de Lindóia do Sul, segundo decreto 55/1990', 'SC', '4209854');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/01/2019', 'Aniversário', 'MUNICIPAL', 'Feriado do aniversário do município, transferido pra esta data, de acordo com o Decreto nº 196/2018', 'PR', '4117008');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/01/2019', 'Dia de Bom Jesus dos Navegantes', 'MUNICIPAL', 'Feriado municipal instituído pelo Artigo 284 da Lei Orgânica do Município de Touros. A data celebra o padroeiro local, Bom Jesus dos Navegantes, e marca o encerramento da maior festividade religiosa da cidade, reconhecida como Patrimônio Cultural e Imaterial do Rio Grande do Norte pela Lei Estadual nº 11.706/2024.', 'RN', '2414407');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/01/2019', 'Dia dos Pescadores e Marisqueiras', 'MUNICIPAL', 'Feriado municipal dedicado aos pescadores e marisqueiras de Salinas da Margarida, reconhecendo a importância vital desta atividade para a economia e cultura local. A celebração integra o calendário oficial de feriados do município, conforme legislação local que institui as datas comemorativas da cidade.', 'BA', '2927309');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/01/2019', 'Emancipação Política de Bacuri', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação política e instalação do município de Bacuri, ocorrida em 2 de janeiro de 1962. A autonomia administrativa foi conquistada por meio da Lei Estadual nº 2.167, de 26 de dezembro de 1961, desmembrando-se do território de Guimarães.', 'MA', '2101301');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/01/2019', 'Emancipação Política de Inajá', 'MUNICIPAL', 'Comemoração oficial do aniversário de emancipação política de Inajá, ocorrida em 2 de janeiro de 1949. A data celebra a independência administrativa do município em relação ao território de Moxotó.', 'PE', '2607000');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/01/2019', 'Emancipação Política de Maravilha', 'MUNICIPAL', 'Feriado municipal em comemoração à emancipação política do município de Maravilha, ocorrida em 2 de janeiro de 1959. A autonomia administrativa foi estabelecida após o desmembramento do território de Santana do Ipanema, conforme os termos da Lei Estadual nº 2.138/1958.', 'AL', '2704609');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/01/2019', 'Festa do Senhor do Bonfim', 'MUNICIPAL', 'Feriado municipal em honra ao Senhor do Bonfim, uma das festividades religiosas mais antigas e tradicionais do Ceará. O dia 2 de janeiro marca o ápice das celebrações no município de Icó, com missas e procissões que atraem romeiros de diversas regiões.', 'CE', '2305407');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/01/2019', 'Instalação do Município de Lagoa Nova', 'MUNICIPAL', 'Feriado municipal que celebra a instalação administrativa e posse do primeiro prefeito de Lagoa Nova em 2 de janeiro de 1963. Embora a Lei Estadual nº 2.777 de 1962 tenha criado o município, a tradição local e o Decreto Municipal nº 001/1981 consagram o dia 2 de janeiro como a data oficial de celebração da autonomia política.', 'RN', '2406502');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('03/01/2019', 'Aniversário de Ananindeua', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação política de Ananindeua. A data celebra a elevação do então distrito à categoria de município em 3 de janeiro de 1944, conforme o Decreto-Lei Estadual nº 4.505. O feriado é formalmente instituído pela Lei Municipal nº 584, de 16 de junho de 1975.', 'PA', '1500800');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('03/01/2019', 'Dia de Santa Genoveva (Padroeira)', 'MUNICIPAL', 'Feriado municipal em honra a Santa Genoveva, padroeira oficial de Irapuru. A cidade é reconhecida por ter um dos primeiros feriados religiosos do calendário anual no Brasil (3 de janeiro), dedicado à liturgia da santa que também é padroeira de Paris. Embora o aniversário da cidade seja em maio, o dia da padroeira é feriado local consolidado.', 'SP', '3521606');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('03/01/2019', 'Emancipação Política de Jardim', 'MUNICIPAL', 'Feriado municipal em celebração à emancipação política de Jardim, ocorrida em 3 de janeiro de 1816. A data marca a instalação da Vila após o desmembramento da antiga jurisdição da Vila Real do Crato. As festividades são de caráter cívico e religioso, incluindo tradicionalmente o hasteamento de pavilhões e missa solene em ação de graças na Igreja Matriz de Santo Antônio, padroeiro da cidade (embora a emancipação seja o feriado civil de janeiro).', 'CE', '2307106');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('04/01/2019', 'Dia do Municipio', 'MUNICIPAL', 'Dia do Aniversário da Cidade de União do Oeste, conforme lei 344, de 15 de outubro de 1997', 'SC', '4218855');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('04/01/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'GO', '5208806');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('04/01/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'PB', '2508307');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('04/01/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'RS', '4317400');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('04/01/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'RS', '4318101');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/01/2019', 'Aniversário de Sanclerlândia', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação política e administrativa do município de Sanclerlândia. O município foi criado pela Lei Estadual nº 4.897, de 13 de novembro de 1963, e formalmente instalado em 1º de janeiro de 1964. Contudo, a legislação municipal e a tradição cívica local consolidaram o dia 05 de janeiro como a data oficial para as comemorações do aniversário da cidade, sendo feriado instituído para celebrar a autonomia da municipalidade.', 'GO', '5219001');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('06/01/2019', 'Aniversário de Alegre', 'MUNICIPAL', 'Feriado municipal comemorativo ao aniversário de fundação do município de Alegre, ocorrido em 06 de janeiro de 1891.', 'ES', '3200201');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('06/01/2019', 'Aniversário de Angra dos Reis', 'MUNICIPAL', 'Feriado municipal em celebração ao aniversário da cidade de Angra dos Reis, fundada em 06 de janeiro de 1502. É um dos feriados cívicos mais antigos e importantes da região Costa Verde, regido pela Lei Municipal nº 260/1960.', 'RJ', '3300100');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('06/01/2019', 'Aniversário de Morro Agudo', 'MUNICIPAL', 'Feriado municipal que comemora o aniversário de emancipação e fundação do município de Morro Agudo, ocorrida em 06 de janeiro de 1895, conforme estabelecido na Lei Orgânica e legislação municipal correlata.', 'SP', '3531902');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('06/01/2019', 'Dia de Reis', 'MUNICIPAL', 'Feriado religioso dedicado aos Santos Reis Magos, marco tradicional no calendário de eventos do município de Cipó.', 'BA', '2907905');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('06/01/2019', 'Dia de Reis', 'MUNICIPAL', 'Feriado municipal instituído em virtude das celebrações religiosas e culturais da Epifania (Dia de Reis), de grande relevância para a comunidade local.', 'BA', '2910750');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('06/01/2019', 'Dia de Reis', 'MUNICIPAL', 'Feriado municipal que celebra a tradição religiosa da Epifania, marcando o encerramento do ciclo natalino no município de Itapuranga.', 'GO', '5211206');
