INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('06/01/2019', 'Dia de Santos Reis', 'MUNICIPAL', 'Feriado municipal instituído pela Lei Municipal nº 032/1989, celebrando a data religiosa de Santos Reis, que fundamenta tradicionais festividades e manifestações de fé no município.', 'PB', '2507101');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('06/01/2019', 'Dia de Santos Reis', 'MUNICIPAL', 'Feriado municipal religioso em homenagem aos Santos Reis, integrando as festividades tradicionais da região que celebram a Epifania do Senhor.', 'PB', '2516409');
