INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('06/01/2019', 'Dia de Santos Reis', 'MUNICIPAL', 'Feriado municipal dedicado à celebração dos Reis Magos, consolidado pela tradição religiosa potiguar e integrado ao calendário oficial de Martins.', 'RN', '2407401');
