INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('06/01/2019', 'Dia de Santos Reis', 'MUNICIPAL', 'Feriado religioso municipal em honra aos Santos Reis Magos, celebrando a tradição cristã da Epifania do Senhor, conforme costume consolidado na legislação municipal e tradição local.', 'SP', '3510906');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('06/01/2019', 'Dia de Santos Reis', 'MUNICIPAL', 'Feriado municipal celebrando a visita dos Reis Magos ao Menino Jesus, preservando as tradições da Folia de Reis e a identidade religiosa de Dolcinópolis.', 'SP', '3514205');
