INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('06/01/2019', 'Dia de Santos Reis', 'MUNICIPAL', 'Feriado municipal em celebração ao Dia de Reis, amparado pela tradição religiosa e legislado para preservar o patrimônio cultural e imaterial das festividades de Folia de Reis na cidade.', 'SP', '3534906');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('06/01/2019', 'Dia de Santos Reis', 'MUNICIPAL', 'Feriado municipal em Santo Antônio da Alegria dedicado à celebração litúrgica dos Santos Reis, peça central do calendário cultural e religioso do município.', 'SP', '3547908');
