INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('06/01/2019', 'Fundação da Cidade e Dia de Santos Reis', 'MUNICIPAL', 'Feriado municipal que comemora simultaneamente a fundação da cidade de Criciúma (06 de janeiro de 1880) e o dia religioso de Santos Reis, conforme Lei Municipal nº 1.933/1983.', 'SC', '4204608');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('07/01/2019', 'Aniversário da Cidade (Emancipação de Peçanha)', 'MUNICIPAL', 'Feriado municipal que celebra o aniversário de Peçanha, conforme estabelecido no Art. 174 da Lei Orgânica do Município (com redação dada pela Emenda de 13/12/2016). A data comemora a instalação administrativa ocorrida em 7 de janeiro de 1881, marcando a autonomia do município no Vale do Rio Doce.', 'MG', '3148608');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('07/01/2019', 'Aniversário de Santa Izabel do Pará', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de fundação e emancipação política do município de Santa Izabel do Pará, ocorrida em 7 de janeiro de 1934, conforme estabelecido pelo Decreto Estadual nº 1.151.', 'PA', '1506500');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('07/01/2019', 'Dia da Instalação do Município de Carangola', 'MUNICIPAL', 'Feriado municipal que comemora a instalação político-administrativa de Carangola, ocorrida em 7 de janeiro de 1882. A data celebra a transição da antiga Freguesia de Santa Luzia para a condição de vila autônoma, sendo reconhecida anualmente como feriado civil pela legislação municipal e ratificada pelo calendário oficial do Tribunal de Justiça de Minas Gerais.', 'MG', '3113305');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('07/01/2019', 'Dia de São Thomaz de Cantuária', 'MUNICIPAL', 'Feriado municipal em celebração a São Thomaz de Cantuária, Padroeiro de Camaçari. A data é oficialmente reconhecida pela legislação municipal, incluindo a Lei nº 283/1993, que consolida os feriados locais em honra às tradições religiosas e à identidade cultural da cidade, mantendo viva a devoção iniciada no século XVIII.', 'BA', '2905701');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('07/01/2019', 'Emancipação Política de Mantenópolis', 'MUNICIPAL', 'Feriado municipal em comemoração à instalação oficial do município de Mantenópolis, ocorrida em 7 de janeiro de 1954. A criação da unidade administrativa foi autorizada pela Lei Estadual nº 779, de 29 de dezembro de 1953, consolidando a autonomia da ''Cidade da Paz'' e marcando o fim das disputas territoriais na região do contestado.', 'ES', '3203304');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('07/01/2019', 'Festa do Padroeiro Bom Jesus dos Pobres Aflitos', 'MUNICIPAL', 'Feriado municipal instituído pela Lei Municipal nº 1.403, de 1986, que estabelece os dias 6 e 7 de janeiro como feriados dedicados às festividades do Padroeiro, Bom Jesus dos Pobres Aflitos. O dia 7 de janeiro marca o encerramento da tradicional festa religiosa, uma das manifestações de fé mais antigas e expressivas do agreste pernambucano.', 'PE', '2613008');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('07/01/2019', 'Independência de Itaparica (Data Magna)', 'MUNICIPAL', 'Feriado municipal considerado a ''Data Magna'' da cidade, celebrando a histórica Batalha de Itaparica de 7 de janeiro de 1823. A celebração homenageia heróis populares como Maria Felipa e a resistência dos itaparicanos que derrotaram as tropas portuguesas, sendo um pilar fundamental para a consolidação da Independência da Bahia e do Brasil.', 'BA', '2916104');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('09/01/2019', 'Aniversário da Emancipação de Embaúba', 'MUNICIPAL', 'Feriado municipal instituído para celebrar a emancipação político-administrativa de Embaúba, ocorrida em 9 de janeiro de 1990 através da Lei Estadual nº 6.645. O feriado foi oficialmente estabelecido pela Lei Municipal nº 163, de 20 de setembro de 1994, comemorando a independência do município em relação a Cajobi.', 'SP', '3514957');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('09/01/2019', 'Aniversário da Emancipação de Iaras', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação político-administrativa de Iaras, formalmente instituída pela Lei Estadual nº 6.645, de 9 de janeiro de 1990. A data foi fixada como feriado local pela Lei Municipal nº 08, de 5 de março de 1993, comemorando a autonomia conquistada pelo município em relação a Águas de Santa Bárbara.', 'SP', '3519253');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('09/01/2019', 'Aniversário de Emancipação de Centralina', 'MUNICIPAL', 'Feriado municipal em celebração ao aniversário de emancipação político-administrativa de Centralina. Embora o município tenha sido criado pela Lei Estadual nº 1.039 em dezembro de 1953, a data de 9 de janeiro de 1954 marca sua instalação oficial e conquista definitiva de autonomia frente a Canápolis, sendo feriado conforme a legislação local.', 'MG', '3115805');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('09/01/2019', 'Dia da Emancipação Política de Itaporanga', 'MUNICIPAL', 'Feriado municipal que comemora a instalação oficial do município em 9 de janeiro de 1865, após seu desmembramento de Piancó conforme a Lei Provincial nº 104 de 1863. A data é a principal celebração cívica da cidade, representando sua autonomia no Vale do Piancó, sendo ratificada pela Lei Municipal nº 925/2016.', 'PB', '2507002');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('09/01/2019', 'Dia da Emancipação de Euclides da Cunha Paulista', 'MUNICIPAL', 'Feriado municipal em homenagem à emancipação política de Euclides da Cunha Paulista, ocorrida em 9 de janeiro de 1990 sob a égide da Lei Estadual nº 6.645. O dia foi fixado como feriado local pela Lei Municipal nº 024, de 30 de abril de 1993.', 'SP', '3515350');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('09/01/2019', 'Dia da Emancipação de São Miguel do Passa Quatro', 'MUNICIPAL', 'Feriado municipal que celebra a criação do município de São Miguel do Passa Quatro, oficializada pela Lei Estadual nº 10.432, de 9 de janeiro de 1988. A data marca o desmembramento do antigo distrito do território de Silvânia, consolidando sua identidade administrativa e política no estado de Goiás.', 'GO', '5220264');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/01/2019', 'Aniversário de Aliança do Tocantins', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação política de Aliança do Tocantins, ocorrida em 10 de janeiro de 1988. A data marca a autonomia do antigo distrito, que se desmembrou de Gurupi.', 'TO', '1700350');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/01/2019', 'Aniversário de Matutina', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de fundação e emancipação de Matutina. A data é oficialmente reconhecida pelo calendário de feriados do município (ex: Decreto Municipal nº 008/2021), celebrando a instalação da cidade.', 'MG', '3141207');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/01/2019', 'Aniversário de Serra Dourada', 'MUNICIPAL', 'Comemoração da emancipação política do município de Serra Dourada, ocorrida em 10 de janeiro de 1962, data em que a cidade obteve sua autonomia administrativa ao desmembrar-se do município de Santana.', 'BA', '2930303');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/01/2019', 'Dia de São Gonçalo do Amarante', 'MUNICIPAL', 'Celebração do dia do padroeiro do município de Caém. O feriado é dedicado a homenagens religiosas e festividades populares em honra a São Gonçalo do Amarante.', 'BA', '2905107');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/01/2019', 'Dia de São Gonçalo do Amarante', 'MUNICIPAL', 'Feriado municipal em honra ao padroeiro São Gonçalo do Amarante. A festividade é pilar da identidade religiosa local, atraindo devotos e mantendo viva a tradição que nomeia a cidade.', 'BA', '2929305');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/01/2019', 'Dia de São Gonçalo do Amarante', 'MUNICIPAL', 'Feriado religioso em comemoração ao padroeiro São Gonçalo do Amarante. A devoção remonta ao antigo nome do povoado, São Gonçalo do Brejo das Almas, consolidando a importância histórica da data para a comunidade.', 'MG', '3126703');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/01/2019', 'Dia de São Gonçalo do Amarante', 'MUNICIPAL', 'Feriado municipal dedicado ao padroeiro da cidade, São Gonçalo do Amarante. A data é celebrada anualmente com ritos religiosos e festejos que mobilizam a população local.', 'MG', '3161809');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/01/2019', 'Dia de São Gonçalo do Amarante', 'MUNICIPAL', 'Feriado religioso em honra a São Gonçalo do Amarante, santo padroeiro de São Gonçalo do Sapucaí. A celebração é uma das mais tradicionais da região, fundamentada na devoção católica que deu origem ao nome do município.', 'MG', '3162005');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/01/2019', 'Dia de São Gonçalo do Amarante', 'MUNICIPAL', 'Celebração litúrgica em honra a São Gonçalo do Amarante, padroeiro de Virgolândia. O feriado está consolidado no calendário municipal como dia de guarda e tradição religiosa.', 'MG', '3171907');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/01/2019', 'Dia de São Gonçalo do Amarante', 'MUNICIPAL', 'Feriado municipal dedicado ao padroeiro São Gonçalo do Amarante. A festividade é o ápice do Ciclo de São Gonçalo em Itapissuma, incluindo a tradicional ''Levada do Santo'', tradição iniciada em 1861 e reconhecida como patrimônio cultural local.', 'PE', '2607752');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/01/2019', 'Dia de São Gonçalo do Amarante', 'MUNICIPAL', 'Feriado municipal em homenagem ao padroeiro São Gonçalo do Amarante. A data é celebrada com festividades religiosas que fazem parte da herança cultural de Regeneração.', 'PI', '2208809');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/01/2019', 'Dia de São Gonçalo do Amarante', 'MUNICIPAL', 'Feriado municipal em honra ao padroeiro da cidade, São Gonçalo do Amarante, conforme estabelecido pela Lei Municipal nº 434, de 20 de março de 2012.', 'RJ', '3304904');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/01/2019', 'Emancipação Política de Jaguaribara', 'MUNICIPAL', 'Feriado municipal em celebração à emancipação política de Jaguaribara, oficializada pela Lei Estadual nº 3.553, de 10 de janeiro de 1957.', 'CE', '2306801');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('12/01/2019', 'Aniversário de Belém (Ponto Facultativo)', 'MUNICIPAL', 'Celebração solene da fundação da cidade de Belém, ocorrida em 12 de janeiro de 1616 pelo capitão-mor Francisco Caldeira Castelo Branco com a fundação do Forte do Presépio. Embora seja a data magna da capital paraense, a Lei Municipal nº 6.306, de 01 de março de 1967, não a instituiu originalmente como feriado civil, sendo tradicionalmente decretada pela Prefeitura como ponto facultativo para os órgãos da administração pública. Projetos de lei recentes (como o PL 1867/2021) buscaram oficializá-la como feriado, mas a data permanece predominantemente como um dia de celebração histórica com regime de ponto facultativo.', 'PA', '1501402');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('12/01/2019', 'Aniversário de Iporanga', 'MUNICIPAL', 'Comemoração do aniversário de fundação e emancipação político-administrativa do município de Iporanga, ocorrida historicamente em 12 de janeiro. A data celebra a autonomia do município e sua relevância histórica no Vale do Ribeira, sendo oficialmente reconhecida como feriado municipal em conformidade com a Lei Orgânica e decretos anuais (como o Decreto Municipal nº 1.411/2025).', 'SP', '3521200');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('13/01/2019', 'Aniversário de Emancipação Política de Tejuçuoca', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação política de Tejuçuoca. O município foi criado pela Lei Estadual nº 11.411, de 1º de julho de 1987 (com nova redação dada pela Lei nº 11.414, de 28 de dezembro de 1987), desmembrando-se do território de Itapajé. A data de 13 de janeiro é o marco oficial das festividades de aniversário e autonomia administrativa, sendo reiterada anualmente por decretos municipais, como o Decreto nº 01/2026, que oficializa o feriado. A celebração valoriza a história da ''Capital do Bode'' e sua trajetória de desenvolvimento no norte cearense.', 'CE', '2313351');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('14/01/2019', 'Aniversário de Bom Retiro', 'MUNICIPAL', 'Feriado municipal que celebra a instalação oficial do município de Bom Retiro, ocorrida em 14 de janeiro de 1923. A data é formalmente estabelecida pela Lei Municipal nº 477, de 17 de janeiro de 1977, sendo tradicionalmente comemorada com eventos cívicos e culturais.', 'SC', '4202602');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('14/01/2019', 'Aniversário de Miguelópolis', 'MUNICIPAL', 'Feriado municipal dedicado às celebrações do aniversário da cidade de Miguelópolis. A data é reconhecida pelo calendário administrativo local, conforme ratificado pelo Decreto Municipal nº 7.501/2026, comemorando a trajetória histórica e o desenvolvimento do município paulista.', 'SP', '3529708');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('14/01/2019', 'Aniversário de Paço do Lumiar', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação política e administrativa do município de Paço do Lumiar. A data celebra a autonomia conquistada em 14 de janeiro de 1959, sendo um marco histórico para a identidade e o desenvolvimento da cidade no estado do Maranhão.', 'MA', '2107506');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('14/01/2019', 'Dia da Emancipação Política de Cruz', 'MUNICIPAL', 'Feriado municipal em comemoração à emancipação política de Cruz, ocorrida em 14 de janeiro de 1985 através da Lei Estadual nº 11.004. A data é oficialmente protegida pela Lei Municipal nº 020/1987, celebrando o marco histórico em que a localidade obteve sua autonomia administrativa ao desmembrar-se do município de Acaraú.', 'CE', '2304251');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('14/01/2019', 'Dia do Imigrante (Aniversário de Mucajaí)', 'MUNICIPAL', 'Feriado municipal que celebra o Dia do Imigrante e o aniversário de fundação do município de Mucajaí. A data presta homenagem aos pioneiros e colonos que estabeleceram o Núcleo Agrícola de Mucajaí a partir de 1951. O feriado é confirmado anualmente pelo calendário oficial do Tribunal de Justiça do Estado de Roraima (TJRR) e por decretos municipais de gestão administrativa.', 'RR', '1400308');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('14/01/2019', 'Festa do Padroeiro Bom Jesus dos Aflitos', 'MUNICIPAL', 'Feriado religioso municipal em honra ao Senhor Bom Jesus dos Aflitos, padroeiro da cidade de Exu. A celebração é reconhecida pela Lei Municipal nº 1.226/2014 e representa o encerramento da tradicional festa religiosa que mobiliza a comunidade local em atos de fé e tradição cultural, sendo o principal evento do calendário litúrgico do município.', 'PE', '2605301');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/01/2019', 'Aniversário de Palmeiras', 'MUNICIPAL', 'Feriado municipal comemorativo da emancipação política de Palmeiras, ocorrida em 15 de janeiro de 1891. A celebração destaca a importância histórica do município no contexto da Chapada Diamantina e sua autonomia administrativa, conforme previsto na Lei Orgânica Municipal.', 'BA', '2923506');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/01/2019', 'Aniversário de Unaí', 'MUNICIPAL', 'Comemoração do aniversário de emancipação política e administrativa do município de Unaí, ocorrida em 15 de janeiro de 1944. O feriado é ratificado pela Lei Municipal nº 2.760/2011.', 'MG', '3170404');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/01/2019', 'Aniversário do Município', 'MUNICIPAL', 'Feriado municipal que comemora a conquista da autonomia política de Lima Campos em 15 de janeiro de 1962. A data, estabelecida pela Lei nº 225/1984, celebra a história de desmembramento do território e o desenvolvimento da soberania local, sendo a principal efeméride civil do calendário municipal.', 'MA', '2106003');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/01/2019', 'Dia de Santo Amaro', 'MUNICIPAL', 'Feriado municipal de natureza religiosa em homenagem a Santo Amaro, padroeiro de Maribondo. Estabelecido em conformidade com a Lei Orgânica Municipal e os preceitos da Lei Federal nº 9.093/1995, o dia é marcado por tradicionais procissões e eventos que compõem o calendário oficial da prefeitura.', 'AL', '2704807');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/01/2019', 'Dia de Santo Amaro', 'MUNICIPAL', 'Feriado municipal instituído pela Lei Municipal nº 1.247/2015 em homenagem a Santo Amaro, padroeiro de Jaboatão dos Guararapes. A legislação municipal reconhece a data como feriado religioso oficial, respeitando o limite máximo de quatro feriados anuais facultados aos municípios pela Lei Federal nº 9.093/1995.', 'PE', '2607901');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/01/2019', 'Dia de Santo Amaro', 'MUNICIPAL', 'Feriado municipal dedicado a Santo Amaro, padroeiro de Sirinhaém. A celebração é amparada pela Lei Federal nº 9.093/1995 como feriado religioso de tradição local, representando uma das manifestações de fé mais antigas do litoral sul pernambucano, integrando o patrimônio imaterial da cidade.', 'PE', '2614204');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/01/2019', 'Dia de Santo Amaro', 'MUNICIPAL', 'Feriado municipal em honra ao padroeiro Santo Amaro. A data marca o encerramento da secular ''Festa de Janeiro'', tradição cultural e religiosa de Taquaritinga do Norte, sendo reconhecida legalmente como feriado de tradição local nos termos da legislação federal vigente.', 'PE', '2615003');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/01/2019', 'Dia de Santo Amaro', 'MUNICIPAL', 'Feriado municipal em homenagem a Santo Amaro, padroeiro da Baixada Campista, conforme a Lei Municipal nº 8.441 de 15/05/2013.', 'RJ', '3301009');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/01/2019', 'Dia de Santo Amaro', 'MUNICIPAL', 'Feriado religioso municipal em celebração a Santo Amaro, padroeiro de Paraíba do Sul, instituído pela Lei Municipal nº 447 de 1967. A festividade é protegida pela legislação federal (Lei nº 9.093/95) como um dos feriados religiosos de tradição local, sendo um marco central do calendário litúrgico e cultural da cidade.', 'RJ', '3303708');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/01/2019', 'Dia de Santo Amaro', 'MUNICIPAL', 'Feriado municipal instituído pela Lei nº 1.797 de 11 de novembro de 2013, em homenagem a Santo Amaro, padroeiro da comunidade local em General Câmara.', 'RS', '4308805');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/01/2019', 'Dia de Santo Amaro', 'MUNICIPAL', 'Feriado municipal dedicado ao padroeiro da cidade, Santo Amaro da Imperatriz. Estabelecido pela Lei Municipal nº 124/1971 e em conformidade com o Art. 2º da Lei Federal nº 9.093/1995, o feriado é o marco das festividades religiosas que reúnem a comunidade local em torno de sua história e fé.', 'SC', '4215703');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/01/2019', 'Dia de Santo Amaro', 'MUNICIPAL', 'Feriado municipal em honra a Santo Amaro, padroeiro da cidade do Guarujá, conforme estabelecido pela Lei Municipal nº 315 de 1967. A data é reconhecida como feriado religioso de acordo com o Artigo 2º da Lei Federal nº 9.093/1995, celebrando a tradição histórica e a devoção religiosa que fundamentam a identidade local.', 'SP', '3518701');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/01/2019', 'Dia de Santo Amaro de Ipitanga', 'MUNICIPAL', 'Celebração do padroeiro de Lauro de Freitas, Santo Amaro de Ipitanga. A data também celebra o aniversário da Igreja Matriz, marco histórico local, conforme o calendário oficial de feriados do município.', 'BA', '2919207');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/01/2019', 'Dia do Padroeiro Santo Amaro', 'MUNICIPAL', 'Feriado religioso municipal em honra a Santo Amaro, padroeiro que empresta o nome ao município. A data é o ápice das festividades culturais e religiosas locais, fundamentada legalmente pelo Artigo 2º da Lei Federal nº 9.093/1995, que permite aos municípios a instituição de feriados religiosos segundo o costume local.', 'BA', '2928604');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/01/2019', 'Festa de Santo Amaro (Padroeiro)', 'MUNICIPAL', 'Feriado municipal em celebração ao padroeiro Santo Amaro das Brotas. Além da lei municipal de feriados, a festividade possui reconhecimento especial como Bem de Interesse Cultural do Estado de Sergipe (Lei Estadual nº 9.401/2024), evidenciando sua relevância histórica e patrimonial para o estado.', 'SE', '2806602');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('16/01/2019', 'Aniversário de Castelândia', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação política e administrativa de Castelândia, no estado de Goiás. O município foi oficialmente criado pela Lei Estadual nº 11.400, de 16 de janeiro de 1991, data em que se celebra a sua autonomia territorial após o desmembramento das cidades de Rio Verde e Quirinópolis.', 'GO', '5205059');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('17/01/2019', 'Aniversário de Emancipação Política de Arame', 'MUNICIPAL', 'Feriado municipal em comemoração à criação do município de Arame. Embora a Lei Estadual nº 4.867 tenha sido assinada em 12 de janeiro de 1988, a festividade oficial e o feriado de emancipação são celebrados em 17 de janeiro, data que consolidou a instalação administrativa e o reconhecimento da vontade popular expressa em plebiscito. É o dia de maior relevância para a história política do município no Maranhão.', 'MA', '2100956');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('17/01/2019', 'Aniversário de Emancipação Política de Itiúba', 'MUNICIPAL', 'Feriado municipal que celebra a autonomia administrativa do município de Itiúba. A data de 17 de janeiro faz referência ao Decreto Estadual nº 9.322, de 17 de janeiro de 1935, que elevou a localidade à categoria de município, desmembrando-o do território de Queimadas. Trata-se da data cívica mais importante do município, feriado instituído por lei municipal em respeito à memória da emancipação política local.', 'BA', '2917003');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('17/01/2019', 'Dia de Santo Antão Abade (Padroeiro)', 'MUNICIPAL', 'Feriado municipal em celebração a Santo Antão Abade, padroeiro histórico de Vitória de Santo Antão. A festividade é uma das tradições religiosas mais antigas de Pernambuco, fundamentada na ocupação da região no século XVII. O feriado é estabelecido em conformidade com a Lei Federal nº 9.093/1995 e ratificado pela Lei Orgânica Municipal, sendo a data principal do calendário litúrgico e civil da cidade, marcada por celebrações na Matriz de Santo Antão.', 'PE', '2616407');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('17/01/2019', 'Festa do Padroeiro Senhor do Bonfim', 'MUNICIPAL', 'Feriado municipal dedicado ao Senhor do Bonfim, padroeiro que dá nome à cidade. Diferente da celebração móvel em Salvador, o feriado em Senhor do Bonfim é fixado em 17 de janeiro pela Lei Municipal nº 1.411/2017. A data celebra a tradição iniciada no século XVIII com a fundação da capela que deu origem ao núcleo urbano, sendo um marco de identidade cultural e religiosa para a população bonfinense.', 'BA', '2930105');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('18/01/2019', 'Aniversário de Herval', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação político-administrativa do município de Herval, ocorrida historicamente em 18 de janeiro de 1881. A data comemora a autonomia da cidade e é estabelecida como feriado oficial através da Lei Municipal nº 131, que consolida os feriados locais e o calendário comemorativo municipal.', 'RS', '4307104');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('18/01/2019', 'Dia de Nossa Senhora dos Impossíveis', 'MUNICIPAL', 'Feriado municipal religioso em honra à Padroeira de Pombos, Nossa Senhora dos Impossíveis. A festividade é tradicional no município e está oficialmente prevista no Art. 100 da Lei Orgânica Municipal, sendo ratificada anualmente por decretos municipais que regulamentam o fechamento do comércio e repartições públicas.', 'PE', '2611309');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('18/01/2019', 'Emancipação de São Francisco de Itabapoana', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação político-administrativa de São Francisco de Itabapoana. A autonomia do município foi conquistada em 18 de janeiro de 1995, por meio da Lei Estadual nº 2.379/1995. O feriado municipal foi instituído e ratificado pela Lei Municipal nº 06, de 10 de março de 1997, sendo a principal data cívica do calendário local.', 'RJ', '3304755');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('19/01/2019', 'Aniversário da Cidade de Tiradentes', 'MUNICIPAL', 'Feriado municipal em celebração ao aniversário de fundação da cidade. A data comemora a elevação do antigo Arraial de Santo Antônio do Rio das Mortes à categoria de Vila de São José, ocorrida em 19 de janeiro de 1718 por ato de D. Pedro de Almeida, o Conde de Assumar. O feriado é amparado pela tradição histórica local e por dispositivos da Lei Orgânica Municipal, representando o marco da autonomia política e administrativa do núcleo urbano que viria a ser Tiradentes.', 'MG', '3168804');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('20/01/2019', 'Dia de São Sebastião', 'MUNICIPAL', 'Feriado municipal em celebração a São Sebastião, padroeiro de Limoeiro de Anadia, em conformidade com a tradição religiosa local e dispositivos da Lei Orgânica do Município.', 'AL', '2704203');
