INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('20/01/2019', 'São Sebastião', 'MUNICIPAL', 'Dia de São Sebastião, padroeiro da cidade, conforme lei 676 de 19 de fevereiro de 2001', 'MG', '3168101');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('20/01/2019', 'São Sebastião', 'MUNICIPAL', 'Dia de São Sebastião', 'PB', '2508554');
