INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('20/01/2019', 'São Sebastião', 'MUNICIPAL', 'Comemorativo ao dia de São Sebastião, padroeiro da Paróquia de São Sebastião e Nossa Senhora das Dores, sede matriz do Município', 'RS', '4300661');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('20/01/2019', 'São Sebastião', 'MUNICIPAL', 'Dia de São Sebastião', 'SC', '4202073');
