INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('20/01/2019', 'São Sebastião', 'MUNICIPAL', 'Dia de São Sebastião, padroeiro da Cidade. Lei nº 262/80', 'SP', '3524006');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('20/01/2019', 'São Sebastião', 'MUNICIPAL', 'Dia de São Sebastião, padroeiro da Cidade, conforme lei Nº 03, de 15 de abril de 1983', 'SP', '3536802');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('20/01/2019', 'São Sebastião', 'MUNICIPAL', 'Dia de São Sebastião, padroeiro da cidade, conforme Lei 11919/09 de 10/03/2009', 'SP', '3543402');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('21/01/2019', 'Aniversário de Goiatuba', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação política e administrativa do município de Goiatuba, ocorrida em 21 de janeiro de 1931. A data é oficializada pela Lei Municipal nº 2.106/2003, conforme registros do Tribunal de Justiça de Goiás.', 'GO', '5209101');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('21/01/2019', 'Aniversário de Poconé', 'MUNICIPAL', 'Feriado municipal que celebra a fundação da cidade de Poconé, Mato Grosso, ocorrida em 21 de janeiro de 1781. O feriado é instituído por lei municipal para comemorar a história do município, conhecido como a ''Cidade Rosa'' e portão de entrada para o Pantanal.', 'MT', '5106505');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('21/01/2019', 'Dia da Emancipação de Sulina', 'MUNICIPAL', 'Feriado municipal em celebração à data de criação do município de Sulina, estabelecido pela Lei Municipal nº 135/1995. A emancipação política ocorreu formalmente por meio da Lei Estadual nº 8.445, de 21 de janeiro de 1987.', 'PR', '4126652');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('21/01/2019', 'Dia de Santa Inês (Padroeira)', 'MUNICIPAL', 'Feriado municipal em celebração à Santa Inês, padroeira da cidade. A data é feriado oficial no município da Bahia, integrando o calendário religioso e cultural local, respeitando o limite de feriados religiosos estabelecidos pela legislação federal.', 'BA', '2927903');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('21/01/2019', 'Dia de Santa Inês (Padroeira)', 'MUNICIPAL', 'Feriado municipal religioso em honra a Santa Inês, padroeira do município. A celebração é a principal festividade religiosa da cidade, culminando em 21 de janeiro com procissões e missas solenes, sendo ratificada pelas leis municipais que definem os feriados religiosos locais, em conformidade com a Lei Federal nº 9.093/1995.', 'MA', '2109908');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('21/01/2019', 'Dia de Santa Inês (Padroeira)', 'MUNICIPAL', 'Feriado municipal religioso em homenagem à Santa Inês, padroeira do município de Santa Inês, no Paraná. A data de 21 de janeiro é reservada para as celebrações oficiais e litúrgicas da padroeira, conforme definido por decreto ou lei municipal.', 'PR', '4123600');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('21/01/2019', 'Dia do Padroeiro (Senhor dos Passos)', 'MUNICIPAL', 'Feriado municipal instituído originalmente pela Lei Municipal nº 08 de 1937 para celebrar o centenário da Paróquia de Maruim. Atualmente, a data é observada como o dia do Padroeiro do município, Senhor dos Passos, conforme ratificado pelo Decreto Municipal nº 090/2023.', 'SE', '2804003');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/01/2019', 'Aniversário da Emancipação Política', 'MUNICIPAL', 'Comemoração da emancipação política e administrativa do município de Icapuí, que se desmembrou de Aracati em 22 de janeiro de 1984. O feriado é regulamentado pela Lei Municipal nº 864/2021 e encontra amparo histórico na Lei Estadual nº 10.913/1984.', 'CE', '2305357');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/01/2019', 'Aniversário da Fundação de São Vicente', 'MUNICIPAL', 'Aniversário da Fundação de São Vicente, conforme Lei Municipal 1.332/67', 'SP', '3551009');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/01/2019', 'Aniversário de Nova Prata do Iguaçu', 'MUNICIPAL', 'Feriado municipal em celebração ao aniversário de emancipação política de Nova Prata do Iguaçu, ocorrida em 22 de janeiro de 1982. A data é feriado oficial conforme a legislação municipal e reconhecida nos calendários judiciários e institucionais do Paraná.', 'PR', '4117255');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/01/2019', 'Aniversário de Quirinópolis', 'MUNICIPAL', 'Celebração do Aniversário de Quirinópolis, em memória à sua fundação ocorrida em 22 de janeiro de 1944. O feriado municipal é amparado pela Lei Municipal nº 1.196/1983 e reiterado anualmente pelo calendário oficial do Poder Executivo e Judiciário Estadual.', 'GO', '5218508');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/01/2019', 'Dia da Emancipação Política de Tamboril', 'MUNICIPAL', 'Feriado municipal em comemoração ao Dia da Emancipação Política de Tamboril. A data celebra a autonomia administrativa do município, sendo oficializada por decretos anuais, como o Decreto nº 192/2026, que regulamentam o calendário de feriados locais.', 'CE', '2313203');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/01/2019', 'Dia de São Anastácio (Padroeiro)', 'MUNICIPAL', 'Comemoração do Dia de São Anastácio, padroeiro do município, estabelecido conforme a Lei Municipal nº 878, de 16 de dezembro de 1977. A data celebra o mártir persa escolhido como protetor da paróquia em 1929 e oficialmente da cidade pela lei de 1977.', 'SP', '3547700');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/01/2019', 'Dia de São Vicente Pallotti (Padroeiro)', 'MUNICIPAL', 'Feriado municipal dedicado ao padroeiro de Palotina, São Vicente Pallotti. A data homenageia o sacerdote italiano fundador da Sociedade do Apostolado Católico (Palotinos), cuja influência é central na história e colonização do município.', 'PR', '4117909');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('23/01/2019', 'Aniversário da Cidade', 'MUNICIPAL', 'Celebração do aniversário de fundação de Mazagão, ocorrida em 23 de janeiro de 1770, quando colonos vindos da possessão portuguesa no Marrocos se estabeleceram na região. É uma data histórica fundamental para a identidade mazaganense.', 'AP', '1600402');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('23/01/2019', 'Aniversário do Município', 'MUNICIPAL', 'Feriado municipal em celebração à fundação de Paragominas, ocorrida em 23 de janeiro de 1965. A data homenageia os pioneiros e marca o desenvolvimento desta importante cidade do sudeste paraense.', 'PA', '1505502');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('23/01/2019', 'Aniversário do Município', 'MUNICIPAL', 'Comemoração da emancipação político-administrativa do município de Barão de Cotegipe, ocorrida em 23 de janeiro de 1959. O feriado é regido pela legislação municipal (Lei nº 2.455/2021) e celebra a história e o progresso da cidade.', 'RS', '4301701');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('23/01/2019', 'Aniversário do Município', 'MUNICIPAL', 'Feriado municipal em Major Vieira que celebra a criação e emancipação política da cidade, ocorrida em 23 de janeiro de 1961. Data oficializada pela Lei Orgânica e decretos municipais vigentes.', 'SC', '4210308');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('23/01/2019', 'Aniversário do Município', 'MUNICIPAL', 'Comemoração da emancipação política de Canhoba, oficializada em 23 de janeiro de 1937. O feriado municipal recorda a história da formação administrativa do município e sua autonomia estadual.', 'SE', '2801108');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/01/2019', 'Aniversário de Portel', 'MUNICIPAL', 'Celebração do aniversário de fundação e emancipação política de Portel, um dos municípios mais antigos do Pará, fundado em 24 de janeiro de 1758. A data é reconhecida como feriado municipal em decretos anuais da prefeitura.', 'PA', '1505809');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/01/2019', 'Dia da Adesão do Piauí à Independência', 'MUNICIPAL', 'Celebração histórica da data em que a cidade de Oeiras, então capital da província, proclamou sua adesão formal à Independência do Brasil em 24 de janeiro de 1823, rompendo definitivamente com a Coroa Portuguesa.', 'PI', '2207009');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/01/2019', 'Dia de Nossa Senhora da Paz (Padroeira)', 'MUNICIPAL', 'Feriado religioso municipal em homenagem à Padroeira de Seberi, Nossa Senhora da Paz, conforme estabelecido pela Lei Municipal nº 4.720, de 22 de dezembro de 2020.', 'RS', '4320206');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/01/2019', 'Dia de Nossa Senhora da Paz (Padroeira)', 'MUNICIPAL', 'Feriado religioso em honra a Nossa Senhora da Paz, Padroeira do Município de Balneário Piçarras. A data é observada anualmente conforme o calendário oficial de feriados definido pela administração municipal.', 'SC', '4212809');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/01/2019', 'Dia de São Francisco de Sales (Padroeiro)', 'MUNICIPAL', 'Feriado municipal em celebração ao Santo Padroeiro que dá nome ao município. A festividade religiosa é observada anualmente em 24 de janeiro, data litúrgica de São Francisco de Sales.', 'MG', '3161304');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/01/2019', 'Dia de São Francisco de Sales (Padroeiro)', 'MUNICIPAL', 'Feriado em honra ao Padroeiro de Mariópolis, São Francisco de Sales. A data é marcada por celebrações religiosas e integra-se à tradicional Festa da Uva, principal evento cultural e econômico do município.', 'PR', '4115309');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/01/2019', 'Dia do Município de Carazinho', 'MUNICIPAL', 'Celebração da emancipação político-administrativa do município de Carazinho, ocorrida em 24 de janeiro de 1931. O feriado é ratificado pelas Leis Municipais nº 3.971/1990 e 4.873/1995.', 'RS', '4304705');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/01/2019', 'Instalação do Município de Porto Velho', 'MUNICIPAL', 'Comemoração da instalação oficial do município de Porto Velho, ocorrida em 24 de janeiro de 1915. O feriado foi instituído pela Lei Municipal nº 190, de 14 de outubro de 1980, que também consagra a data ao culto de São Francisco de Sales.', 'RO', '1100205');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/01/2019', 'Aniversário da Cidade de São Paulo', 'MUNICIPAL', 'Feriado municipal que celebra a fundação da cidade de São Paulo em 1554, marcada pela celebração da primeira missa no Colégio dos Jesuítas (Pátio do Colégio). Instituído pela Lei Municipal nº 14.485/2007.', 'SP', '3550308');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/01/2019', 'Aniversário de Balsa Nova', 'MUNICIPAL', 'Comemoração da emancipação política do município de Balsa Nova, desmembrado de Campo Largo em 25 de janeiro de 1961.', 'PR', '4102307');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/01/2019', 'Aniversário de Banabuiú', 'MUNICIPAL', 'Feriado municipal em comemoração à emancipação política de Banabuiú, estabelecida pela Lei Estadual nº 11.427 de 25 de janeiro de 1988.', 'CE', '2301851');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/01/2019', 'Aniversário de Britânia', 'MUNICIPAL', 'Comemoração da emancipação política do município de Britânia, ocorrida em 25 de janeiro de 1964.', 'GO', '5203807');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/01/2019', 'Aniversário de Buri', 'MUNICIPAL', 'Comemoração da emancipação política do município de Buri, ocorrida em 25 de janeiro de 1922, quando foi elevado à categoria de município.', 'SP', '3508009');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/01/2019', 'Aniversário de Cuité', 'MUNICIPAL', 'Feriado municipal que marca a emancipação política de Cuité em 25 de janeiro de 1937, tornando-se sede administrativa autônoma no Curimataú paraibano.', 'PB', '2505105');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/01/2019', 'Aniversário de Estrela d''Oeste', 'MUNICIPAL', 'Feriado municipal que celebra a fundação e o aniversário da cidade. A data é tradicionalmente comemorada no dia 25 de janeiro para coincidir com o aniversário da capital paulista.', 'SP', '3515202');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/01/2019', 'Aniversário de Guaporema', 'MUNICIPAL', 'Celebração do aniversário de emancipação política do município de Guaporema, conforme estabelecido na Lei Orgânica e decretos municipais.', 'PR', '4109104');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/01/2019', 'Aniversário de Iguatu', 'MUNICIPAL', 'Comemora o aniversário de emancipação política do município de Iguatu, desmembrado de Icó em 25 de janeiro de 1853.', 'CE', '2305506');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/01/2019', 'Aniversário de Lagoa Vermelha', 'MUNICIPAL', 'Data dedicada à comemoração da fundação do município, estabelecida historicamente em 25 de janeiro de 1845.', 'RS', '4311304');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/01/2019', 'Aniversário de Paraisópolis', 'MUNICIPAL', 'Comemoração oficial do aniversário de emancipação político-administrativa do município, celebrando a data de sua fundação histórica em 25 de janeiro de 1873.', 'MG', '3147303');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/01/2019', 'Aniversário de Santa Inês', 'MUNICIPAL', 'Feriado em alusão à criação do município de Santa Inês pela Lei Estadual nº 4.338 de 25 de janeiro de 1961.', 'PR', '4123600');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/01/2019', 'Aniversário de Vera Cruz', 'MUNICIPAL', 'Comemoração da emancipação político-administrativa do município, ocorrida em 25 de janeiro de 1935, conforme o Decreto-Lei Estadual nº 6.855 de 10 de dezembro de 1934.', 'SP', '3556602');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/01/2019', 'Dia de São Paulo', 'MUNICIPAL', 'Feriado religioso dedicado ao padroeiro do município, São Paulo, conforme a Lei Municipal nº 071 de 11 de abril de 1994.', 'SC', '4204152');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/01/2019', 'Dia de São Paulo Apóstolo', 'MUNICIPAL', 'Celebração religiosa em honra a São Paulo Apóstolo, padroeiro municipal. Data baseada em tradição religiosa consolidada na legislação local.', 'BA', '2904803');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/01/2019', 'Dia de São Paulo Apóstolo', 'MUNICIPAL', 'Feriado religioso em honra ao padroeiro municipal, São Paulo Apóstolo. A data celebra a conversão do apóstolo, patrono da cidade.', 'MS', '5004700');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/01/2019', 'Dia de São Paulo Apóstolo', 'MUNICIPAL', 'Feriado religioso em honra à Conversão de São Paulo, padroeiro da cidade, instituído pela Lei Municipal nº 80 de 27 de agosto de 1976.', 'RN', '2412609');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/01/2019', 'Aniversário de Fazenda Rio Grande', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação político-administrativa do município, ocorrida em 26 de janeiro de 1990 através da Lei Estadual nº 9.213. A data é confirmada pela Portaria nº 001/2026 da Prefeitura Municipal, marcando os 36 anos de autonomia da cidade.', 'PR', '4107652');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/01/2019', 'Aniversário de Itacaré', 'MUNICIPAL', 'Celebração do aniversário de emancipação política de Itacaré. A localidade foi elevada à categoria de município em 26 de janeiro de 1732 por ordem da Condessa do Resende, Dona Maria Athaíde e Castro. O feriado é regulamentado pelo Decreto Municipal nº 295/2026.', 'BA', '2914901');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/01/2019', 'Aniversário de Nova Venécia', 'MUNICIPAL', 'Comemoração da emancipação e instalação do município de Nova Venécia, ocorrida em 26 de janeiro de 1954. O feriado foi instituído originalmente pela Lei Municipal nº 48/1955 e é tradicionalmente celebrado como o Dia do Município.', 'ES', '3203908');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/01/2019', 'Aniversário de Santos', 'MUNICIPAL', 'Comemoração oficial da fundação da Vila de Santos em 26 de janeiro de 1546 por Brás Cubas. O feriado municipal é ratificado anualmente pelo calendário oficial do município, conforme estabelecido no Decreto Municipal nº 11.111/2025 para o exercício de 2026.', 'SP', '3548500');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/01/2019', 'Emancipação Política de Santo Antônio do Pinhal', 'MUNICIPAL', 'Feriado municipal instituído pela Lei Ordinária nº 908/2004, em comemoração à emancipação política do município de Santo Antônio do Pinhal, celebrada anualmente no dia 26 de janeiro.', 'SP', '3548203');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('27/01/2019', 'Aniversário de Pedro Leopoldo', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação política e administrativa do município de Pedro Leopoldo. A cidade foi oficialmente instalada em 27 de janeiro de 1924, após o desmembramento do território de Santa Luzia, conforme previsto na Lei Estadual nº 843, de 7 de setembro de 1923. A celebração da data como feriado local é ratificada pela Lei Municipal nº 2.756/2004 e faz parte do calendário oficial da prefeitura, coincidindo tradicionalmente com manifestações culturais como o ''Boi da Manta''.', 'MG', '3149309');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/01/2019', 'Aniversário de Apucarana', 'MUNICIPAL', 'Feriado municipal em celebração à emancipação político-administrativa de Apucarana, ocorrida em 28 de janeiro de 1944. A data é oficialmente instituída pela Lei Municipal nº 001/1954.', 'PR', '4101408');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/01/2019', 'Aniversário de Giruá', 'MUNICIPAL', 'Feriado municipal em celebração à emancipação político-administrativa de Giruá, ocorrida em 28 de janeiro de 1955.', 'RS', '4309001');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/01/2019', 'Aniversário de Pitanga', 'MUNICIPAL', 'Celebração do aniversário do município de Pitanga, em memória à sua instalação oficial ocorrida em 28 de janeiro de 1947.', 'PR', '4119608');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/01/2019', 'Aniversário de Rolândia', 'MUNICIPAL', 'Feriado em comemoração à instalação do município de Rolândia em 28 de janeiro de 1944. A celebração é amparada pela Lei Municipal nº 02/1948.', 'PR', '4122404');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/01/2019', 'Aniversário de Santo Antônio do Leste', 'MUNICIPAL', 'Comemoração do aniversário do município, criado oficialmente em 28 de janeiro de 1998 através da Lei Estadual nº 6.983.', 'MT', '5107792');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/01/2019', 'Aniversário de Santo Cristo', 'MUNICIPAL', 'Comemoração da emancipação política do município de Santo Cristo, ocorrida em 28 de janeiro de 1955, conforme a Lei Estadual nº 2.525.', 'RS', '4317905');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/01/2019', 'Dia de São Gonçalo (Padroeiro)', 'MUNICIPAL', 'Feriado municipal em homenagem a São Gonçalo, padroeiro de São Francisco do Conde. A data é ratificada pela Lei Municipal nº 415, de 14 de março de 1975, refletindo a tradição religiosa local.', 'BA', '2929206');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/01/2019', 'Dia de São Gonçalo de Canabrava', 'MUNICIPAL', 'Feriado municipal que celebra os festejos de São Gonçalo de Canabrava, uma das tradições religiosas mais importantes da região, fundamentada na Lei Orgânica Municipal e em decretos anuais de feriados.', 'BA', '2919504');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/01/2019', 'Dia de São Gonçalo do Amarante (Padroeiro)', 'MUNICIPAL', 'Celebração em honra ao padroeiro municipal. A festa de São Gonçalo em Ibituruna é reconhecida como Patrimônio Cultural Imaterial do município e do estado de Minas Gerais.', 'MG', '3130002');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/01/2019', 'Dia de São Gonçalo do Amarante (Padroeiro)', 'MUNICIPAL', 'Feriado religioso em honra a São Gonçalo do Amarante, padroeiro do município. A celebração é protegida pela Lei Municipal nº 228, de 08 de setembro de 1978.', 'RN', '2412005');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/01/2019', 'Dia de São Tomás de Aquino (Padroeiro)', 'MUNICIPAL', 'Feriado religioso em homenagem ao padroeiro da cidade, cuja festa litúrgica é celebrada em 28 de janeiro pela Igreja Católica.', 'MG', '3165107');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/01/2019', 'Emancipação Política de Iramaia', 'MUNICIPAL', 'Feriado que celebra o aniversário de emancipação de Iramaia, desmembrada de Barra da Estiva em 28 de janeiro de 1960, conforme estabelecido pela Lei Estadual nº 1.253.', 'BA', '2914307');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/01/2019', 'Emancipação Política de Mirandiba', 'MUNICIPAL', 'Feriado que comemora a autonomia do município de Mirandiba, ocorrida em 28 de janeiro de 1958, consolidando sua emancipação política.', 'PE', '2609303');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/01/2019', 'Emancipação Política de Puxinanã', 'MUNICIPAL', 'Feriado municipal alusivo ao aniversário da cidade, emancipada politicamente em 28 de janeiro de 1959 através da Lei Estadual nº 2.052.', 'PB', '2512408');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/01/2019', 'Emancipação de Castanhal', 'MUNICIPAL', 'Comemoração da elevação de Castanhal à categoria de cidade, ocorrida em 28 de janeiro de 1932, conforme o Decreto Estadual nº 600. Trata-se da data magna municipal que celebra sua autonomia e desenvolvimento.', 'PA', '1502400');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('29/01/2019', 'Aniversário de Benjamin Constant', 'MUNICIPAL', 'Feriado municipal dedicado à comemoração do aniversário de Benjamin Constant. A data marca a emancipação política e a elevação da localidade à categoria de cidade em 29 de janeiro de 1898. A celebração é uma das mais importantes do calendário local, sendo oficialmente reconhecida pela prefeitura e pela Associação Amazonense de Municípios como feriado civil.', 'AM', '1300607');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('29/01/2019', 'Aniversário de Piraquara', 'MUNICIPAL', '', 'PR', '4119509');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('30/01/2019', 'Aniversário de Governador Valadares', 'MUNICIPAL', 'Feriado municipal que celebra o aniversário de emancipação político-administrativa do município de Governador Valadares, ocorrida em 30 de janeiro de 1938. A data comemora o momento em que o antigo distrito de Figueira obteve sua autonomia em relação ao município de Peçanha. O feriado é anualmente ratificado pelo calendário oficial de feriados e pontos facultativos do Poder Executivo Municipal, como visto no Decreto nº 12.176/2025, fundamentado na relevância histórica e política da data para a comunidade local.', 'MG', '3127701');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('31/01/2019', 'Aniversário de Barbosa', 'MUNICIPAL', 'Feriado municipal que celebra a fundação da cidade de Barbosa, ocorrida em 31 de janeiro de 1960. A data homenageia a história do município e seus fundadores, Joaquim Barbosa de Carvalho e Dona Ricardina.', 'SP', '3505104');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('31/01/2019', 'Aniversário de Campo Bom', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação político-administrativa de Campo Bom, ocorrida em 31 de janeiro de 1959, após o desmembramento do município de São Leopoldo. A data é o principal marco histórico da autonomia da cidade.', 'RS', '4303905');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('31/01/2019', 'Aniversário de Nhamundá', 'MUNICIPAL', 'Celebração do aniversário do município de Nhamundá. A data de 31 de janeiro foi incluída no Calendário Oficial de Eventos do Estado do Amazonas por meio da Lei nº 6.958, de 1º de julho de 2024, em reconhecimento à fundação da cidade em 1956.', 'AM', '1303007');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('31/01/2019', 'Aniversário de Tarumirim', 'MUNICIPAL', 'Comemoração da emancipação político-administrativa do município de Tarumirim. O feriado é regido pela Lei Municipal nº 390/CMT/2011, que em seu Artigo 1º, inciso II, define o dia 31 de janeiro como o ''Dia do Aniversário da Cidade''.', 'MG', '3168408');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('31/01/2019', 'Aniversário de Água Comprida', 'MUNICIPAL', 'Feriado municipal que celebra o aniversário de emancipação da cidade. A data foi estabelecida legalmente pela Lei Municipal nº 306/1989 (que sucedeu a Lei 269/1986), sendo consagrada à comemoração da história e autonomia da localidade.', 'MG', '3100708');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('31/01/2019', 'Dia do Senhor do Bonfim', 'MUNICIPAL', 'Feriado municipal religioso dedicado ao Senhor do Bonfim, padroeiro da cidade de Ibititá. A data é oficialmente decretada como feriado pelo Decreto Municipal nº 004, de 25 de janeiro de 2011, em virtude dos festejos religiosos tradicionais.', 'BA', '2913101');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('31/01/2019', 'Emancipação Política de Jiquiriçá', 'MUNICIPAL', 'Feriado que comemora a emancipação política de Jiquiriçá. A autonomia do município foi restaurada em 31 de janeiro de 1891, através de ato estadual que restabeleceu sua independência administrativa em relação a São Vicente Férrer d’Areia.', 'BA', '2918209');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('31/01/2019', 'Instalação do Município de Tavares', 'MUNICIPAL', 'Feriado municipal em celebração à instalação oficial da administração de Tavares. Embora a data de emancipação seja celebrada em maio, o dia 31 de janeiro é reconhecido como feriado alusivo à instalação dos poderes municipais após o desmembramento de Mostardas.', 'RS', '4321352');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('01/02/2019', 'Aniversário de Emancipação de Missal', 'MUNICIPAL', 'Feriado municipal em celebração à emancipação político-administrativa de Missal, no Paraná. O município foi criado pela Lei Estadual nº 7.566/1981 e teve sua instalação oficial em 1º de fevereiro de 1983, data em que tomou posse o primeiro prefeito e a primeira legislatura da Câmara Municipal após o desmembramento de Medianeira.', 'PR', '4116059');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('01/02/2019', 'Aniversário de Nova Crixás', 'MUNICIPAL', 'Feriado municipal que celebra o aniversário de emancipação de Nova Crixás, Goiás. A data comemora a instalação oficial do município ocorrida em 1º de fevereiro de 1983, consolidando a autonomia política estabelecida pela Lei Estadual nº 8.847/1980 e ratificada pela Lei Orgânica Municipal.', 'GO', '5214838');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('01/02/2019', 'Aniversário de Nova Prata do Iguaçu', 'MUNICIPAL', 'Feriado municipal que celebra o aniversário de emancipação de Nova Prata do Iguaçu, Paraná. O município foi criado pela Lei Estadual nº 7.661/1982 e instalado oficialmente em 1º de fevereiro de 1983, data que marca o desmembramento definitivo do território do município de Salto do Lontra.', 'PR', '4117255');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('01/02/2019', 'Aniversário de Tabatinga', 'MUNICIPAL', 'Feriado municipal em celebração ao aniversário de Tabatinga, no Amazonas. A data marca a instalação oficial da estrutura administrativa e a autonomia política do município ocorrida em 1º de fevereiro de 1983, após sua criação pela Lei Estadual nº 1.511/1981. A data consta no Calendário Oficial do Estado conforme a Lei nº 7.989/2025.', 'AM', '1304062');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('01/02/2019', 'Dia da Instalação do Município de Costa Marques', 'MUNICIPAL', 'Feriado municipal em comemoração à instalação do município de Costa Marques, em Rondônia, ocorrida solenemente em 1º de fevereiro de 1983. A data foi instituída como feriado oficial pela Lei Municipal nº 26/1985, celebrando a posse definitiva dos poderes Executivo e Legislativo após a criação do ente federado pela Lei Federal nº 6.921/1981.', 'RO', '1100080');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('01/02/2019', 'Dia da Instalação do Município de Indiara', 'MUNICIPAL', 'Feriado municipal que celebra a instalação oficial do município de Indiara, Goiás, ocorrida em 1º de fevereiro de 1983. A emancipação política foi estabelecida pela Lei Estadual nº 9.183/1982, desmembrando o território de Edéia, Jandaia e Palmeiras de Goiás para a formação da nova unidade administrativa.', 'GO', '5209952');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('01/02/2019', 'Emancipação Política de Atalaia', 'MUNICIPAL', 'Feriado municipal em comemoração à emancipação político-administrativa de Atalaia, Alagoas. A data recorda o dia 1º de fevereiro de 1764, quando a localidade foi elevada à categoria de Vila de Atalaia, tornando-se o quarto núcleo de povoamento do estado e cidade-mãe de diversos municípios da região da Mata Alagoana.', 'AL', '2700409');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/02/2019', 'Dia da Padroeira e Aniversário de Indaiatuba', 'MUNICIPAL', 'Feriado municipal em celebração à Nossa Senhora da Candelária, padroeira da cidade, e ao aniversário de fundação de Indaiatuba. Data fixada pela Lei Municipal nº 8.241/2024 e tradição histórica local.', 'SP', '3520509');
