INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/02/2019', 'Nossa Senhora dos Navegantes', 'MUNICIPAL', 'Feriado municipal em Ouro dedicado à celebração de Nossa Senhora dos Navegantes.', 'SC', '4211801');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/02/2019', 'Nossa Sra da Candelária', 'MUNICIPAL', 'Consagrado a Nossa Senhora da Candelária, padroeira de Corumbá', 'MS', '5003207');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/02/2019', 'Nossa Sra. da Candelária e Aniversário de Itu', 'MUNICIPAL', 'Feriado em comemoração ao 416º aniversário de fundação de Itu (1610) e em honra à sua padroeira, Nossa Senhora da Candelária. É a data magna da Estância Turística de Itu.', 'SP', '3523909');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/02/2019', 'Nossa Sra. dos Navegantes', 'MUNICIPAL', 'Dia de Nossa Senhora dos Navegantes', 'SC', '4209409');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/02/2019', 'Padroeira', 'MUNICIPAL', 'Nossa Senhora da Piedade, padroeira de Campo Largo', 'PR', '4104204');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/02/2019', 'Senhor do Bom Jesus do Bonfim', 'MUNICIPAL', 'Feriado municipal em Viçosa dedicado à celebração do Senhor do Bom Jesus do Bonfim.', 'AL', '2709400');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('03/02/2019', 'Aniversário de Guapé', 'MUNICIPAL', 'Feriado municipal em celebração à instalação do município de Guapé, ocorrida em 03 de fevereiro de 1924. A data marca a autonomia administrativa definitiva da cidade.', 'MG', '3128105');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('03/02/2019', 'Aniversário de Saboeiro', 'MUNICIPAL', 'Feriado municipal em comemoração à emancipação política de Saboeiro, ocorrida em 03 de fevereiro de 1823. A data celebra a fundação da vila e a história do município no Sertão dos Inhamuns.', 'CE', '2311900');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('03/02/2019', 'Dia de São Brás', 'MUNICIPAL', 'Feriado municipal em celebração ao dia de São Brás, data de forte tradição religiosa que antecede as comemorações da emancipação política do município (04 de fevereiro).', 'BA', '2931202');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('03/02/2019', 'Dia de São Brás', 'MUNICIPAL', 'Feriado municipal em honra a São Brás, conforme estabelecido pela Lei Municipal nº 636 de 31 de janeiro de 1989. É uma data de grande relevância cultural e religiosa para a comunidade de Ouricuri.', 'PE', '2609907');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('03/02/2019', 'Dia de São Brás (Padroeiro)', 'MUNICIPAL', 'Feriado municipal dedicado ao padroeiro da cidade, São Brás. A data é oficializada por decreto (ex: Decreto nº 3.632/2026), sendo o principal feriado religioso do município.', 'MG', '3160900');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('03/02/2019', 'Dia de São Brás (Padroeiro)', 'MUNICIPAL', 'Feriado municipal em celebração a São Brás, padroeiro do município de Paraí. A data é fixada pela Lei Municipal nº 751/1991 e marca as principais festividades da paróquia local.', 'RS', '4314001');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('03/02/2019', 'Festa de São Sebastião', 'MUNICIPAL', 'Feriado municipal estabelecido em virtude das celebrações da tradicional Festa de São Sebastião. Em 2026, a prefeitura decretou feriado nos dias 02 e 03 de fevereiro para as comemorações do centenário da festividade.', 'PE', '2602209');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('04/02/2019', 'Aniversário de Dois Córregos', 'MUNICIPAL', 'Feriado municipal que comemora a fundação da cidade de Dois Córregos, em São Paulo, ocorrida em 4 de fevereiro de 1856. Reconhecida como a ''Capital Nacional da Macadâmia'' e ''Capital Estadual da Poesia'', o município celebra a data com eventos cívicos, a Prova Pedestre e a tradicional ''Festa das Nações'', que reúne as entidades locais.', 'SP', '3514106');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('04/02/2019', 'Aniversário de Macapá', 'MUNICIPAL', '', 'AP', '1600303');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('04/02/2019', 'Aniversário de Presidente Castello Branco', 'MUNICIPAL', 'Celebração da emancipação político-administrativa do município de Presidente Castello Branco, Santa Catarina. A data remete à instalação oficial do município, ocorrida em 4 de fevereiro de 1964. O município foi criado pela Lei Estadual nº 931, de 11 de novembro de 1963, com território desmembrado do município de Ouro (que, por sua vez, havia sido desmembrado de Capinzal em 1962). As festividades costumam incluir eventos cívicos e a tradicional Festa da Gruta de Nossa Senhora de Lourdes.', 'SC', '4213906');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('04/02/2019', 'Dia de São José de Leonissa', 'MUNICIPAL', 'Feriado municipal em homenagem ao padroeiro de Itaocara, São José de Leonissa. Trata-se da única paróquia no Brasil dedicada a este santo, cuja festa é celebrada anualmente em 4 de fevereiro, data de sua morte em 1612. A celebração é reconhecida como Patrimônio Cultural Imaterial do município pela Lei Ordinária nº 1237/2021.', 'RJ', '3302106');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('04/02/2019', 'Emancipação Política de Taperoá', 'MUNICIPAL', 'Feriado municipal em celebração à emancipação político-administrativa do município de Taperoá, na Bahia, ocorrida em 4 de fevereiro de 1890. A data é oficialmente reconhecida pelo calendário do Tribunal de Justiça do Estado da Bahia (TJBA). É importante distinguir esta celebração do aniversário de fundação da cidade, que ocorre em 29 de maio (data que não é feriado municipal). As comemorações de fevereiro tradicionalmente ocorrem após a festa de São Brás (03/02), padroeiro local.', 'BA', '2931202');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/02/2019', 'Aniversário de Alvinópolis', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação política de Alvinópolis, ocorrida em 5 de fevereiro de 1891, data em que foi elevada à categoria de vila e desmembrada de Mariana.', 'MG', '3102308');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/02/2019', 'Aniversário de Amontada', 'MUNICIPAL', 'Feriado municipal em comemoração à emancipação política de Amontada, oficializada pela Lei Estadual nº 11.010 em 5 de fevereiro de 1985, quando o município se desmembrou de Itapipoca.', 'CE', '2300754');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/02/2019', 'Aniversário de Arenápolis', 'MUNICIPAL', 'Feriado municipal em celebração à instalação oficial do município de Arenápolis, ocorrida em 5 de fevereiro de 1954. O município foi criado pela Lei Estadual nº 704/1953, sendo desmembrado de Barra do Bugres.', 'MT', '5101308');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/02/2019', 'Aniversário de Colombo', 'MUNICIPAL', 'Aniversário da emancipação e instalação do município, conforme a Lei Orgânica Municipal de Colombo', 'PR', '4105805');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/02/2019', 'Aniversário de Itarema', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação política de Itarema, ocorrida em 5 de fevereiro de 1985 por meio da Lei Estadual nº 11.008, marcando sua autonomia administrativa em relação ao município de Acaraú.', 'CE', '2306553');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/02/2019', 'Aniversário de Nortelândia', 'MUNICIPAL', 'Feriado municipal que celebra a instalação do município de Nortelândia em 5 de fevereiro de 1954, data que marca sua autonomia administrativa.', 'MT', '5106000');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/02/2019', 'Aniversário de Umirim', 'MUNICIPAL', 'Celebração do aniversário de emancipação política do município de Umirim, oficializada pela Lei Estadual nº 11.006 em 5 de fevereiro de 1985.', 'CE', '2313757');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/02/2019', 'Dia da Emancipação Política de Varjota', 'MUNICIPAL', 'Feriado municipal que celebra a conquista da autonomia política de Varjota em 5 de fevereiro de 1985, através da Lei Estadual nº 11.007, após desmembramento de Reriutaba. A data é ratificada pela Lei Municipal nº 720/2021.', 'CE', '2313955');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/02/2019', 'Dia de Santa Águeda (Padroeira)', 'MUNICIPAL', 'Feriado municipal religioso em honra a Santa Águeda, padroeira de Pesqueira e da Catedral Diocesana. A festividade é protegida pela tradição local e fundamentada legalmente pela Lei Municipal nº 356/1967.', 'PE', '2610905');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('06/02/2019', 'Aniversário de Araruama', 'MUNICIPAL', 'Feriado municipal que celebra o aniversário de emancipação político-administrativa de Araruama. A data comemora o dia 6 de fevereiro de 1859, marco da elevação da localidade à categoria de vila e sua consequente autonomia em relação a Cabo Frio. A celebração é ratificada pela legislação municipal e pela Lei Orgânica do Município, sendo uma das datas mais importantes da Região dos Lagos.', 'RJ', '3300209');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('06/02/2019', 'Emancipação Política de Umbaúba', 'MUNICIPAL', 'Feriado municipal em celebração à emancipação político-administrativa de Umbaúba, ocorrida em 6 de fevereiro de 1954 por meio da Lei Estadual nº 554. A data marca o desmembramento oficial do território em relação ao município de Arauá, consolidando a autonomia do município no sul sergipano. A comemoração é prevista na Lei Orgânica Municipal e no calendário oficial de feriados da prefeitura.', 'SE', '2807600');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('06/02/2019', 'Feriado a Confirmar (Cidade Incorreta)', 'MUNICIPAL', 'Esta data (06/02) refere-se ao feriado de emancipação política de Umbaúba, mas não consta como feriado oficial para Japoatã. De acordo com a Lei Municipal nº 273/2005 de Japoatã, as datas magnas do município ocorrem em novembro: o Dia da Emancipação Política (23 de novembro) e o dia da Padroeira, Nossa Senhora do Desterro (25 de novembro).', 'SE', '2803401');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('07/02/2019', 'Dia da Batalha do Reduto (Data Comemorativa)', 'MUNICIPAL', 'Data de grande relevância histórica que rememora a Batalha do Reduto, ocorrida em 7 de fevereiro de 1832 no contexto da Guerra dos Cabanos (Cabanada). Embora a data seja instituída no Calendário Oficial de Eventos do Estado de Pernambuco pela Lei nº 13.872/2009 e celebrada civicamento no município pela bravura e resistência no Forte de Rio Formoso, ela não é classificada como feriado civil (folga) pela Lei Municipal nº 1.439/2011, tratando-se, portanto, de uma data comemorativa oficial.', 'PE', '2611903');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('07/02/2019', 'Emancipação Política de Propriá', 'MUNICIPAL', 'Feriado municipal que celebra a autonomia administrativa de Propriá, conquistada em 7 de fevereiro de 1802. Originalmente um povoado conhecido como Urubu-de-Baixo, a localidade foi elevada à categoria de Vila por meio de um Alvará Régio, desmembrando-se da jurisdição de Vila-Nova do São Francisco (atual Neópolis). A data marca a consolidação da cidade como um dos principais centros comerciais e culturais da região do Baixo São Francisco sergipano, sendo carinhosamente chamada de ''Princesinha do São Francisco''.', 'SE', '2805703');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('08/02/2019', 'Aniversário de Água Clara', 'MUNICIPAL', 'Feriado municipal em celebração ao aniversário de emancipação político-administrativa de Água Clara. Embora o município tenha sido criado pela Lei Estadual nº 676, de 11 de dezembro de 1953, sua instalação oficial e efetiva ocorreu em 8 de fevereiro de 1954, data em que se comemora anualmente sua fundação.', 'MS', '5000203');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('09/02/2019', 'Aniversário do Cerco da Lapa', 'MUNICIPAL', 'Feriado municipal fundamentado nas Leis Municipais nº 1.558/2001 e nº 2.530/2010. A data celebra a histórica resistência da "Cidade Heroica" durante a Revolução Federalista de 1894, quando forças republicanas (conhecidas como pica-paus), sob o comando do General Gomes Carneiro, detiveram por 26 dias o avanço das tropas federalistas (maragatos). O sacrifício dos lapaenses foi vital para a reorganização das forças legalistas e a consolidação da República no Brasil.', 'PR', '4113205');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('09/02/2019', 'Dia dos Mártires de Piancó', 'MUNICIPAL', 'Feriado municipal estabelecido pela Lei nº 963, de 19 de maio de 2003. A data homenageia a memória do Padre Aristides Ferreira da Cruz e de seus companheiros, que em 9 de fevereiro de 1926 resistiram à invasão da Coluna Prestes no município. O episódio, marcado pelo sacrifício dos defensores locais contra as tropas revolucionárias, é um dos eventos históricos mais significativos do sertão paraibano. No ano de 2026, a celebração assume especial relevância ao marcar o centenário do episódio histórico.', 'PB', '2511301');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/02/2019', 'Aniversário de São Raimundo das Mangabeiras', 'MUNICIPAL', 'Feriado municipal em comemoração à emancipação política e administrativa de São Raimundo das Mangabeiras, no Maranhão. O município foi criado pela Lei Estadual nº 272, de 31 de dezembro de 1948, e oficialmente instalado em 10 de fevereiro de 1949, data em que se desmembrou do território de Loreto. A celebração é um marco da autonomia conquistada pelos pioneiros da região.', 'MA', '2111607');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/02/2019', 'Aniversário de Tiros', 'MUNICIPAL', 'Feriado municipal que celebra o aniversário de emancipação político-administrativa de Tiros, em Minas Gerais. A cidade foi oficialmente instalada em 10 de fevereiro de 1924, consolidando sua autonomia em relação ao município de São Gotardo. A data é celebrada anualmente com eventos cívicos e culturais que resgatam a história da colonização local.', 'MG', '3168903');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/02/2019', 'Feriado a Confirmar (Cidade Incorreta)', 'MUNICIPAL', 'Esta data (10/02) não consta como feriado oficial para o município de Rurópolis (PA). O aniversário de fundação e feriado municipal de Rurópolis é oficialmente celebrado em 12 de fevereiro, em memória à sua inauguração em 1974 como a primeira cidade planejada às margens da rodovia Transamazônica. A presença desta data em bases genéricas decorre de feriados homônimos em outros municípios, como Tiros (MG) e São Raimundo das Mangabeiras (MA).', 'PA', '1506195');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/02/2019', 'Aniversário de Aldeias Altas', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação política de Aldeias Altas, fundada em 11 de fevereiro de 1962.', 'MA', '2100303');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/02/2019', 'Aniversário de Antônio Prado', 'MUNICIPAL', 'Feriado municipal que celebra o aniversário de emancipação política do município de Antônio Prado, ocorrida em 11 de fevereiro de 1899.', 'RS', '4300802');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/02/2019', 'Aniversário de Araucária', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação política de Araucária, ocorrida em 11 de fevereiro de 1890.', 'PR', '4101804');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/02/2019', 'Aniversário de Paranacity', 'MUNICIPAL', 'Feriado municipal celebrando o aniversário de fundação de Paranacity, ocorrida em 11 de fevereiro de 1954.', 'PR', '4118105');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/02/2019', 'Aniversário de Rafard', 'MUNICIPAL', 'Feriado municipal em comemoração à fundação e autonomia política do município de Rafard.', 'SP', '3542107');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/02/2019', 'Aniversário de Relvado', 'MUNICIPAL', 'Feriado municipal celebrando o aniversário de emancipação política de Relvado, ocorrida em 11 de fevereiro de 1988.', 'RS', '4315453');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/02/2019', 'Aniversário de São Gonçalo do Rio Abaixo', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação política de São Gonçalo do Rio Abaixo, celebrada em 11 de fevereiro. A data marca a autonomia do município, ocorrida oficialmente em 1962.', 'MG', '3161908');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/02/2019', 'Feriado a Confirmar (Data Incorreta)', 'MUNICIPAL', 'A data de 11/02 não consta na lista oficial de feriados municipais de Major Gercino (Lei nº 756/1961), que celebra seu padroeiro em 06/08 e a emancipação em 28/12.', 'SC', '4210209');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/02/2019', 'Homenagem ao Fundador Francisco de Assis Leite', 'MUNICIPAL', 'Feriado municipal em Cedro conforme o Art. 237 da Lei Orgânica do Município, em homenagem ao fundador Francisco de Assis Leite.', 'PE', '2604304');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/02/2019', 'Nossa Senhora Rainha do Sertão', 'MUNICIPAL', 'Feriado municipal em Quixadá em celebração à Nossa Senhora Imaculada Rainha do Sertão, padroeira do município, instituído pela Lei Municipal nº 1.960/2000.', 'CE', '2311306');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/02/2019', 'Nossa Senhora de Lourdes', 'MUNICIPAL', 'Feriado municipal em homenagem à Nossa Senhora de Lourdes, padroeira de Coaraci, conforme o Decreto Municipal nº 8.304/2026.', 'BA', '2908002');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/02/2019', 'Nossa Senhora de Lourdes', 'MUNICIPAL', 'Feriado municipal em honra à Nossa Senhora de Lourdes, padroeira de Ipecaetá, conforme tradição oficial.', 'BA', '2913804');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/02/2019', 'Nossa Senhora de Lourdes', 'MUNICIPAL', 'Feriado municipal em Afonso Cláudio instituído pela Lei Municipal nº 1.227/1990 em honra à padroeira Nossa Senhora de Lourdes.', 'ES', '3200102');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/02/2019', 'Nossa Senhora de Lourdes', 'MUNICIPAL', 'Feriado municipal em celebração à Nossa Senhora de Lourdes, padroeira do município de Conquista, conforme tradição religiosa local e registros da Comarca.', 'MG', '3118205');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/02/2019', 'Nossa Senhora de Lourdes', 'MUNICIPAL', 'Feriado municipal dedicado à Nossa Senhora de Lourdes, padroeira de Maria da Fé, estabelecido pelo Decreto Municipal nº 4.849/2026.', 'MG', '3139904');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/02/2019', 'Nossa Senhora de Lourdes', 'MUNICIPAL', 'Feriado municipal em Vespasiano em celebração à Nossa Senhora de Lourdes, padroeira do município.', 'MG', '3171204');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/02/2019', 'Nossa Senhora de Lourdes', 'MUNICIPAL', 'Feriado municipal em Anastácio celebrando o Dia de Nossa Senhora de Lourdes, padroeira da cidade, conforme legislação municipal vigente.', 'MS', '5000708');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/02/2019', 'Nossa Senhora de Lourdes', 'MUNICIPAL', 'Feriado municipal em Apucarana em honra à sua padroeira, Nossa Senhora de Lourdes, conforme estabelecido pelo calendário oficial do município.', 'PR', '4101408');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/02/2019', 'Nossa Senhora de Lourdes', 'MUNICIPAL', 'Feriado municipal em honra à Nossa Senhora de Lourdes, padroeira de Planalto (PR), conforme calendário administrativo municipal.', 'PR', '4119806');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/02/2019', 'Nossa Senhora de Lourdes', 'MUNICIPAL', 'Feriado municipal em celebração à padroeira Nossa Senhora de Lourdes em Tupãssi, conforme o calendário municipal oficial.', 'PR', '4127957');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/02/2019', 'Nossa Senhora de Lourdes', 'MUNICIPAL', 'Feriado municipal em Ipanguaçu em celebração à padroeira Nossa Senhora de Lourdes, conforme tradição e leis locais.', 'RN', '2404705');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/02/2019', 'Nossa Senhora de Lourdes', 'MUNICIPAL', 'Feriado municipal em Cacique Doble em honra à padroeira Nossa Senhora de Lourdes, conforme Decreto Municipal nº 1.114/2026.', 'RS', '4303202');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/02/2019', 'Nossa Senhora de Lourdes', 'MUNICIPAL', 'Feriado municipal em Capão da Canoa em homenagem à sua padroeira, Nossa Senhora de Lourdes.', 'RS', '4304630');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/02/2019', 'Nossa Senhora de Lourdes', 'MUNICIPAL', 'Feriado municipal em Nova Alvorada celebrando a padroeira Nossa Senhora de Lourdes.', 'RS', '4312757');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/02/2019', 'Nossa Senhora de Lourdes', 'MUNICIPAL', 'Feriado municipal em Veranópolis em honra à padroeira Nossa Senhora de Lourdes. A celebração é marcada pela tradicional romaria à Gruta de Nossa Senhora de Lourdes, um dos principais pontos de devoção religiosa e turística da Serra Gaúcha.', 'RS', '4322806');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/02/2019', 'Nossa Senhora de Lourdes', 'MUNICIPAL', 'Feriado municipal em Angelina em celebração à sua padroeira, Nossa Senhora de Lourdes. A data é de grande relevância para o município, que abriga o Santuário Nossa Senhora de Angelina e uma famosa gruta dedicada à santa, atraindo peregrinos de todo o estado.', 'SC', '4200903');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/02/2019', 'Nossa Senhora de Lourdes', 'MUNICIPAL', 'Feriado municipal em Nossa Senhora de Lourdes (SE) em celebração à sua padroeira, conforme o Decreto Municipal nº 05/2026.', 'SE', '2804706');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/02/2019', 'Nossa Senhora de Lourdes', 'MUNICIPAL', 'Feriado municipal em Pirambu dedicado à padroeira Nossa Senhora de Lourdes, conforme o calendário do Ministério Público de Sergipe.', 'SE', '2805307');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/02/2019', 'Nossa Senhora de Lourdes', 'MUNICIPAL', 'Feriado municipal em Águas da Prata em celebração à Nossa Senhora de Lourdes, padroeira da cidade, conforme legislação municipal.', 'SP', '3500402');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/02/2019', 'Nossa Senhora de Lourdes', 'MUNICIPAL', 'Feriado municipal em Ibirarema dedicado à celebração de sua padroeira, Nossa Senhora de Lourdes.', 'SP', '3519501');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/02/2019', 'Nossa Senhora de Lourdes', 'MUNICIPAL', 'Feriado municipal em Igaraçu do Tietê em honra à sua padroeira, Nossa Senhora de Lourdes.', 'SP', '3520004');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('12/02/2019', 'Aniversário de Faxinal do Soturno', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação político-administrativa de Faxinal do Soturno, no Rio Grande do Sul. O município foi oficialmente criado pela Lei Estadual nº 3.711, de 12 de fevereiro de 1959, após o desmembramento de Cachoeira do Sul. A celebração é marcada por eventos na Praça Vicente Pallotti, incluindo feiras de agroindústria, artesanato e apresentações artísticas que valorizam a identidade local e a inserção da cidade no Geoparque Quarta Colônia.', 'RS', '4308003');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('12/02/2019', 'Aniversário de Guiricema', 'MUNICIPAL', 'Feriado municipal que celebra o aniversário de emancipação político-administrativa de Guiricema, em Minas Gerais. O município conquistou sua autonomia em 12 de fevereiro de 1939, desmembrando-se de Visconde do Rio Branco. A data é celebrada anualmente com atos cívicos e festividades na região da Zona da Mata mineira, marcando a história de desenvolvimento e a identidade do povo guiricemense.', 'MG', '3129004');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('12/02/2019', 'Aniversário de Rurópolis', 'MUNICIPAL', 'Feriado municipal em comemoração à fundação de Rurópolis, no Pará, estabelecido formalmente pela Lei Municipal nº 64/92. Inaugurada em 12 de fevereiro de 1974 durante o projeto de colonização da Amazônia, Rurópolis detém o título histórico de primeira cidade planejada e construída às margens da Rodovia Transamazônica (BR-230). A data é celebrada com o tradicional hasteamento das bandeiras na Praça Cívica e homenagens aos pioneiros.', 'PA', '1506195');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('12/02/2019', 'Dia do Município (Aniversário de Taió)', 'MUNICIPAL', 'Feriado municipal em celebração à emancipação político-administrativa e instalação do município de Taió, em Santa Catarina. A data comemora a autonomia conquistada em 12 de fevereiro de 1949 e é oficialmente reconhecida no calendário de feriados (ex: Decreto nº 7.683/2022). As festividades incluem sessões solenes na Câmara de Vereadores para outorga de títulos honoríficos e eventos culturais voltados à comunidade taioense.', 'SC', '4217808');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('12/02/2019', 'Feriado a Confirmar (Data não corroborada)', 'MUNICIPAL', 'Não foram encontradas evidências legais ou históricas que confirmem o dia 12 de fevereiro como feriado municipal em Mulungu (PB). As principais datas comemorativas do município referem-se à sua fundação em 27 de setembro de 1959 e à sua emancipação em 26 de dezembro de 1958. Recomenda-se cautela, pois a presença desta data em bases de dados pode ser fruto de inconsistência ou confusão com outros municípios de nome homônimo.', 'PB', '2509800');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('13/02/2019', 'Aniversário de Alto Paraíso', 'MUNICIPAL', 'Celebração do aniversário de emancipação política de Alto Paraíso, criado por meio da Lei Estadual nº 375, de 13 de fevereiro de 1992. O território do município foi desmembrado de Ariquemes.', 'RO', '1100403');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('13/02/2019', 'Aniversário de Aquiraz', 'MUNICIPAL', 'Feriado municipal em celebração ao ''Dia do Município'' de Aquiraz, instituído em memória de sua fundação como vila em 13 de fevereiro de 1699. Aquiraz detém o título histórico de primeira capital do estado do Ceará.', 'CE', '2301000');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('13/02/2019', 'Aniversário de Cacaulândia', 'MUNICIPAL', 'Comemoração oficial do aniversário de criação de Cacaulândia, estabelecido pela Lei Estadual nº 374, de 13 de fevereiro de 1992. O município foi criado a partir de terras desmembradas de Ariquemes.', 'RO', '1100601');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('13/02/2019', 'Aniversário de Corumbiara', 'MUNICIPAL', 'Celebração do aniversário de criação de Corumbiara, instituída pela Lei Estadual nº 377, de 13 de fevereiro de 1992. O município teve seu território desmembrado de Colorado do Oeste.', 'RO', '1100072');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('13/02/2019', 'Aniversário de Ministro Andreazza', 'MUNICIPAL', 'Feriado municipal que celebra a criação de Ministro Andreazza, oficializada pela Lei Estadual nº 372, de 13 de fevereiro de 1992. O município foi desmembrado do território de Cacoal.', 'RO', '1101203');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('13/02/2019', 'Aniversário de Mirante da Serra', 'MUNICIPAL', 'Comemoração oficial do aniversário de criação de Mirante da Serra, estabelecido pela Lei Estadual nº 376, de 13 de fevereiro de 1992. O município foi criado a partir de áreas desmembradas de Ouro Preto do Oeste.', 'RO', '1101302');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('13/02/2019', 'Aniversário de Novo Horizonte do Oeste', 'MUNICIPAL', 'Feriado municipal em comemoração à criação de Novo Horizonte do Oeste, instituída pela Lei Estadual nº 365, de 13 de fevereiro de 1992. O novo ente federativo foi desmembrado do município de Rolim de Moura.', 'RO', '1100502');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('13/02/2019', 'Aniversário de Seringueiras', 'MUNICIPAL', 'Feriado municipal que celebra a criação do município de Seringueiras, oficializada pela Lei Estadual nº 371, de 13 de fevereiro de 1992. A cidade originou-se do desmembramento do território de São Miguel do Guaporé.', 'RO', '1101500');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('13/02/2019', 'Aniversário de Urupá', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de criação de Urupá, estabelecido pela Lei Estadual nº 368, de 13 de fevereiro de 1992. O município foi oficialmente criado a partir do desmembramento de áreas de Alvorada d''Oeste.', 'RO', '1101708');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('14/02/2019', 'Aniversário de Caeté', 'MUNICIPAL', 'Feriado municipal em comemoração à fundação da Vila Nova da Rainha em 14 de fevereiro de 1714, núcleo original da atual cidade de Caeté. A data destaca a relevância histórica do município como um dos centros pioneiros do Ciclo do Ouro em Minas Gerais e sede do Santuário de Nossa Senhora da Piedade.', 'MG', '3110004');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('14/02/2019', 'Aniversário de Itapiranga', 'MUNICIPAL', 'Celebração do aniversário de instalação oficial do município de Itapiranga, ocorrida em 14 de fevereiro de 1954. A cidade, reconhecida como o ''Berço Nacional da Oktoberfest'', teve sua colonização iniciada em 1926 pela Sociedade União Popular (Volksverein), sendo um marco da cultura alemã no extremo oeste catarinense.', 'SC', '4208401');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('14/02/2019', 'Aniversário de Ituporanga', 'MUNICIPAL', 'Comemoração da instalação político-administrativa de Ituporanga, ocorrida em 14 de fevereiro de 1949, após sua criação pela Lei Estadual nº 247/1948. Conhecida como a ''Capital Nacional da Cebola'', a data é considerada feriado municipal conforme estabelecido pela Lei Municipal nº 2.717/2012.', 'SC', '4208500');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('14/02/2019', 'Aniversário de Monte Negro', 'MUNICIPAL', 'Feriado municipal em comemoração à emancipação de Monte Negro. Embora a criação estadual do município (Lei nº 378) tenha ocorrido em 13 de fevereiro de 1992, a data oficial de celebração e o feriado municipal foram fixados no dia 14 de fevereiro pela Lei Municipal nº 63/1995.', 'RO', '1101401');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('14/02/2019', 'Dia do Achado da Imagem', 'MUNICIPAL', 'Feriado municipal em Vigia de Nazaré que celebra o ''Dia do Achado''. A data comemora o retorno da imagem original de Nossa Senhora de Nazaré à cidade em 14 de fevereiro de 1977, após ter sido furtada da Igreja Matriz. A celebração, oficializada pela Lei Municipal nº 02/1977, é um dos eventos religiosos e históricos mais importantes do município.', 'PA', '1508209');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('14/02/2019', 'Dia do Fundador', 'MUNICIPAL', 'Feriado municipal instituído pela Lei nº 280/1963 em homenagem ao fundador de Canápolis, Bernardo de Oliveira. Esta celebração ocorre anualmente em 14 de fevereiro e é juridicamente distinta do aniversário de emancipação política do município, que é comemorado em 14 de julho.', 'MG', '3111804');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('14/02/2019', 'Emancipação Política de Delmiro Gouveia', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação de Delmiro Gouveia, ocorrida em 14 de fevereiro de 1952 via Lei Estadual nº 1.623. O município homenageia o industrial pioneiro que construiu a Usina de Angiquinho, a primeira hidrelétrica do Nordeste, impulsionando o desenvolvimento do sertão alagoano.', 'AL', '2702405');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('14/02/2019', 'Feriado a Confirmar (Cidade Incorreta)', 'MUNICIPAL', 'Não consta feriado municipal em 14 de fevereiro para Antônio Carlos (MG). O município possui feriados em 14 de março (Lei nº 493/1967) e 27 de dezembro (Aniversário da Cidade), o que gera confusão em bases genéricas devido à proximidade de datas com cidades como Caeté (MG) e Ituporanga (SC).', 'MG', '3102902');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/02/2019', 'Aniversário de Canarana', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação político-administrativa de Canarana. A data marca a instalação do município em 15 de fevereiro de 1981, originada pela Lei Estadual nº 4.165/1979. É um momento de celebração da história e do desenvolvimento da cidade no Vale do Araguaia.', 'MT', '5102702');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/02/2019', 'Aniversário de Cornélio Procópio', 'MUNICIPAL', 'Feriado municipal em celebração ao aniversário de emancipação política de Cornélio Procópio. O município foi oficialmente instalado em 15 de fevereiro de 1938, após ser desmembrado de Bandeirantes. A data é resguardada pela Lei Municipal nº 478/1967.', 'PR', '4106407');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/02/2019', 'Aniversário de São João do Triunfo', 'MUNICIPAL', 'Feriado municipal que celebra o aniversário de São João do Triunfo. O município obteve sua emancipação política em 15 de fevereiro de 1890, data em que foi oficialmente instalado após o desmembramento da cidade de Palmeira. A celebração é ratificada pela Lei Municipal nº 439/1980.', 'PR', '4125100');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('16/02/2019', 'Aniversário da Emancipação de Agudo', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação político-administrativa de Agudo, ocorrida em 16 de fevereiro de 1959. A data foi oficialmente estabelecida como feriado pela Lei Municipal nº 587, de 22 de setembro de 1986, celebrando a autonomia do município em relação a Cachoeira do Sul.', 'RS', '4300109');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('16/02/2019', 'Aniversário de Raposos', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de fundação do município de Raposos. Em 2026, a cidade celebra seu 336º ano de história, remetendo ao arraial fundado em 16 de fevereiro de 1690 por bandeirantes, o que a posiciona como um dos núcleos urbanos mais antigos do estado de Minas Gerais.', 'MG', '3153905');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('16/02/2019', 'Dia de Santa Juliana (Padroeira)', 'MUNICIPAL', 'Feriado municipal em Salto Veloso dedicado à sua padroeira, Santa Juliana. A data celebra a fé e a tradição da comunidade velosense com atos religiosos na Paróquia Santa Juliana, sendo um feriado oficial que reforça a identidade histórica do município.', 'SC', '4215406');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('17/02/2019', 'Aniversário de Barra do Ribeiro', 'MUNICIPAL', 'Feriado municipal em comemoração ao Dia do Município de Barra do Ribeiro, instituído pela Lei Municipal nº 271/1973.', 'RS', '4301909');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('17/02/2019', 'Aniversário de Itaguaçu', 'MUNICIPAL', 'Feriado municipal em celebração ao Dia do Município de Itaguaçu, conforme estabelecido pelo Decreto Municipal nº 11.832/2025 e pela Lei Ordinária Estadual nº 11.650/2022, que inclui a data no calendário oficial do Espírito Santo.', 'ES', '3202702');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('17/02/2019', 'Aniversário de São João da Mata', 'MUNICIPAL', 'Feriado municipal em comemoração à Emancipação Político-Administrativa do município de São João da Mata, conforme definido pelo Decreto Municipal nº 05/2021.', 'MG', '3162302');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('17/02/2019', 'Aniversário de São Valentim', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de fundação e emancipação político-administrativa do município de São Valentim (RS), ocorrida em 17 de fevereiro de 1959. A data é celebrada anualmente como feriado civil em todo o território municipal.', 'RS', '4319703');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('17/02/2019', 'Aniversário de Vidal Ramos', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação político-administrativa de Vidal Ramos, conforme a Lei Municipal nº 1.059/1994.', 'SC', '4219200');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('17/02/2019', 'Terça-feira de Carnaval', 'MUNICIPAL', 'Feriado estadual em todo o Rio de Janeiro, incluindo o município de Quissamã, conforme instituído pela Lei Estadual nº 5.243/2008.', 'RJ', '3304151');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('18/02/2019', 'Aniversário de Bady Bassitt', 'MUNICIPAL', 'Feriado municipal celebrando o aniversário de emancipação político-administrativa de Bady Bassitt, ocorrida em 18 de fevereiro de 1959 por meio da Lei Estadual nº 5.285.', 'SP', '3504602');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('18/02/2019', 'Aniversário de Cajamar', 'MUNICIPAL', 'Feriado municipal celebrando o aniversário de emancipação de Cajamar, ocorrida em 18 de fevereiro de 1959 através da Lei Estadual nº 5.285.', 'SP', '3509205');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('18/02/2019', 'Aniversário de Colômbia', 'MUNICIPAL', 'Feriado municipal que celebra o aniversário de fundação de Colômbia, município emancipado em 18 de fevereiro de 1959 conforme a Lei Estadual nº 5.285.', 'SP', '3512100');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('18/02/2019', 'Aniversário de Cássia dos Coqueiros', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação política de Cássia dos Coqueiros, ocorrida em 18 de fevereiro de 1959, conforme a Lei Estadual nº 5.285.', 'SP', '3510906');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('18/02/2019', 'Aniversário de Cândido Rodrigues', 'MUNICIPAL', 'Feriado municipal em comemoração à emancipação político-administrativa do município de Cândido Rodrigues, estabelecida pela Lei Estadual nº 5.285 de 18 de fevereiro de 1959.', 'SP', '3510104');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('18/02/2019', 'Aniversário de Embu das Artes', 'MUNICIPAL', 'Feriado municipal em celebração à emancipação política de Embu das Artes, oficializada em 18 de fevereiro de 1959 pela Lei Estadual nº 5.285, marcando sua autonomia de Itapecerica da Serra.', 'SP', '3515004');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('18/02/2019', 'Aniversário de Itapevi', 'MUNICIPAL', 'Feriado municipal em celebração ao aniversário de emancipação político-administrativa de Itapevi, oficializada em 18 de fevereiro de 1959 pela Lei Estadual nº 5.285.', 'SP', '3522505');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('18/02/2019', 'Aniversário de Nísia Floresta', 'MUNICIPAL', 'Feriado municipal em comemoração à Emancipação Política do município de Nísia Floresta, ocorrida em 18 de fevereiro de 1852, quando se desligou de São José de Mipibu.', 'RN', '2408201');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('18/02/2019', 'Aniversário de Pardinho', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação político-administrativa de Pardinho, ocorrida em 18 de fevereiro de 1959 por meio da Lei Estadual nº 5.285.', 'SP', '3536109');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('18/02/2019', 'Aniversário de Peruíbe', 'MUNICIPAL', 'Celebração do aniversário de emancipação político-administrativa da Estância Balneária de Peruíbe, criada pela Lei Estadual nº 5.285 de 18 de fevereiro de 1959.', 'SP', '3537602');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('18/02/2019', 'Aniversário de Piratuba', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação político-administrativa do município de Piratuba, ocorrida em 18 de fevereiro de 1949.', 'SC', '4213104');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('18/02/2019', 'Aniversário de Sagres', 'MUNICIPAL', 'Feriado municipal em comemoração à fundação e emancipação política de Sagres, estabelecida pela Lei Estadual nº 5.285, de 18 de fevereiro de 1959.', 'SP', '3544707');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('18/02/2019', 'Aniversário de Salto do Lontra', 'MUNICIPAL', 'Comemoração da emancipação político-administrativa do município de Salto do Lontra, estabelecida pela Lei Estadual nº 4.823, de 18 de fevereiro de 1964.', 'PR', '4123006');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('18/02/2019', 'Aniversário de Sarutaiá', 'MUNICIPAL', 'Celebração do aniversário de emancipação político-administrativa de Sarutaiá, oficializada pela Lei Estadual nº 5.285 de 18 de fevereiro de 1959.', 'SP', '3551207');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('18/02/2019', 'Aniversário de Taguaí', 'MUNICIPAL', 'Feriado municipal em celebração à emancipação de Taguaí, ocorrida em 18 de fevereiro de 1959 por força da Lei Estadual nº 5.285.', 'SP', '3553005');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('18/02/2019', 'Aniversário de Três Fronteiras', 'MUNICIPAL', 'Celebração municipal da emancipação de Três Fronteiras, ocorrida em 18 de fevereiro de 1959 pela Lei Estadual nº 5.285.', 'SP', '3554904');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('18/02/2019', 'Aniversário de Vista Alegre do Alto', 'MUNICIPAL', 'Feriado municipal em celebração ao aniversário de emancipação político-administrativa de Vista Alegre do Alto, ocorrida em 18 de fevereiro de 1959.', 'SP', '3556909');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('19/02/2019', 'Aniversário de Severínia', 'MUNICIPAL', 'Feriado municipal celebrando a fundação do município em 19 de fevereiro de 1914, conforme Lei Municipal nº 1.575/2004. Excepcionalmente em 2026, a folga foi transferida para o dia 20 de fevereiro pelo Decreto nº 6.651/2026.', 'SP', '3551900');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('19/02/2019', 'Aniversário de Taboão da Serra', 'MUNICIPAL', 'Feriado municipal em celebração à emancipação político-administrativa de Taboão da Serra. Embora a soberania tenha sido obtida legalmente em 1º de janeiro de 1959, a comemoração oficial foi fixada em 19 de fevereiro pela Lei Municipal nº 300/1967, visando evitar a coincidência com as festividades de ano novo e marcar a instalação efetiva do município.', 'SP', '3552809');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('19/02/2019', 'Aniversário de Tangará', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de fundação e emancipação política de Tangará, Santa Catarina. O município foi oficialmente criado pela Lei Estadual nº 182 em 30 de dezembro de 1948, mas a sua administração foi instalada em 19 de fevereiro de 1949, data que se tornou o marco festivo da cidade.', 'SC', '4217907');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('19/02/2019', 'Aniversário de Tapiraí', 'MUNICIPAL', 'Feriado municipal celebrando o aniversário de Tapiraí, emancipada em 19 de fevereiro de 1959. O município foi desmembrado de Piedade através da Lei Estadual nº 5.285, de 18 de fevereiro de 1959, sendo a data subsequente adotada para as comemorações de instalação e autonomia administrativa.', 'SP', '3553500');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('19/02/2019', 'Dia da Comarca', 'MUNICIPAL', 'Feriado municipal instituído pela Lei Municipal nº 1.552, de 28 de novembro de 1995, que celebra a elevação de Santa Rita de Caldas à categoria de Comarca. A data homenageia a autonomia judiciária e o fortalecimento administrativo do município.', 'MG', '3159209');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('19/02/2019', 'Dia de Padre Ibiapina', 'MUNICIPAL', 'Feriado municipal em memória ao aniversário de falecimento do Padre José Antônio Maria Ibiapina (o ''Apóstolo do Nordeste''), ocorrido em 1883 no Santuário de Santa Fé. Instituído pela Lei Municipal nº 003, de 18 de fevereiro de 1997.', 'PB', '2500908');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('19/02/2019', 'Dia de Padre Ibiapina', 'MUNICIPAL', 'Feriado municipal em memória ao falecimento do Padre José Antônio Maria Ibiapina, conhecido como o ''Apóstolo do Nordeste'', ocorrido em 19 de fevereiro de 1883. Instituído pela Lei Municipal nº 010/2003, o feriado homenageia sua vasta obra missionária e social centrada no Santuário de Santa Fé.', 'PB', '2516003');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('19/02/2019', 'Emancipação de Osasco', 'MUNICIPAL', 'conforme Lei Municipal nº 1.121 de 16/05/1972', 'SP', '3534401');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('20/02/2019', 'Aniversário de Lagoa da Confusão', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de criação do município de Lagoa da Confusão, estabelecido em 20 de fevereiro de 1991, data de sua emancipação política do município de Cristalândia.', 'TO', '1711902');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('20/02/2019', 'Aniversário de Xaxim', 'MUNICIPAL', 'Feriado municipal em celebração à emancipação político-administrativa de Xaxim, ocorrida em 20 de fevereiro de 1954. A data é oficializada como feriado local pela Lei Municipal nº 2.604/2003.', 'SC', '4219705');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('20/02/2019', 'Dia dos Pastorinhos', 'MUNICIPAL', 'Feriado municipal religioso em homenagem aos santos Francisco e Jacinta Marto, os Pastorinhos de Fátima. A data, instituída pela Lei Municipal nº 2.271/2019, celebra a ligação da cidade com o milagre da cura do menino Lucas, ocorrido em Juranda, que serviu de base para a canonização dos santos pela Igreja Católica.', 'PR', '4112959');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('21/02/2019', 'Aniversário de Jaicós (Emancipação Política)', 'MUNICIPAL', 'Comemoração da emancipação política do município de Jaicós, no Piauí, ocorrida em 21 de fevereiro de 1834. Conhecida como a ''Terra do Galo'', Jaicós é uma das cidades mais antigas e históricas do estado. A data é feriado municipal oficial, marcada por eventos cívicos, religiosos e culturais que celebram a identidade jaicoense.', 'PI', '2205201');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('21/02/2019', 'Aniversário de Júlio Mesquita (Emancipação Política)', 'MUNICIPAL', 'Feriado municipal em celebração ao aniversário de emancipação política do município de Júlio Mesquita, São Paulo. A cidade conquistou sua autonomia administrativa em 21 de fevereiro de 1949, data em que se desmembrou dos municípios de Cafelândia e Guaimbê. A comemoração é um marco da história e do desenvolvimento da comunidade local.', 'SP', '3525805');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('21/02/2019', 'Feriado Municipal (Memorial a Francisco Teixeira dos Santos)', 'MUNICIPAL', 'Feriado municipal em Paulo Ramos, Maranhão, instituído pelas leis municipais nº 04/92 e nº 134/2015. A data presta homenagem à memória de Francisco Teixeira dos Santos, figura histórica e pioneira da política local, frequentemente citado como primeiro prefeito ou magistrado da comarca. O feriado é oficialmente reconhecido pelo Tribunal de Justiça do Maranhão para fins de suspensão de expediente forense.', 'MA', '2108108');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('21/02/2019', 'Feriado a Confirmar (Data Incorreta)', 'MUNICIPAL', 'O dia 21 de fevereiro não é reconhecido como feriado oficial no município de Mulungu, Paraíba. A data de emancipação política da cidade é 26 de dezembro e seu padroeiro é São Sebastião (20 de janeiro). Não constam leis municipais ou resoluções do Tribunal de Justiça da Paraíba (TJPB) que instituam feriado local nesta data, tratando-se provavelmente de uma inconsistência na base de dados original.', 'PB', '2509800');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('21/02/2019', 'Feriado a Confirmar (Data Incorreta)', 'MUNICIPAL', 'Não há evidências de feriado municipal oficial em Caetés, Pernambuco, no dia 21 de fevereiro. A emancipação política do município é celebrada em 11 de setembro e o padroeiro, São Caetano, em 7 ou 8 de agosto. Conforme o calendário oficial da prefeitura e órgãos estaduais, esta data (21/02) não possui previsão legal para suspensão de expediente, sendo possivelmente um dado incorreto replicado de outros municípios como Jaicós (PI) ou Paulo Ramos (MA).', 'PE', '2603207');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('21/02/2019', 'Feriado a Confirmar (Data Incorreta)', 'MUNICIPAL', 'Não existe registro de feriado municipal para Pinhão, Sergipe, em 21 de fevereiro. O aniversário de emancipação política do município ocorre em 25 de novembro. Calendários judiciais e municipais não indicam festividades ou homenagens oficiais com status de feriado para esta data específica, sugerindo que a entrada é um erro de replicação de dados de outros municípios brasileiros que celebram aniversários em 21/02.', 'SE', '2805208');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/02/2019', 'Aniversário de Andradas', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação de Andradas, ocorrida em 22 de fevereiro de 1890, após seu desmembramento de Caldas. A data é respaldada pela Lei Municipal nº 929/1989. Em 2026, o município comemora 136 anos de autonomia política com tradicionais eventos cívicos e culturais.', 'MG', '3102605');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/02/2019', 'Aniversário de São Desidério', 'MUNICIPAL', 'Feriado municipal em comemoração à emancipação política de São Desidério, ocorrida em 22 de fevereiro de 1962. A data, oficializada pela Lei Municipal nº 008/1997, marca a autonomia do município e em 2026 celebra-se o 64º aniversário com atos cívicos e festividades que exaltam a história e a identidade da população local.', 'BA', '2928901');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/02/2019', 'Aniversário de São Pedro', 'MUNICIPAL', 'Feriado municipal em comemoração aos 145 anos de emancipação político-administrativa da Estância Turística de São Pedro, ocorrida em 22 de fevereiro de 1881, quando se desmembrou de Piracicaba. A celebração da data é regida pela Lei Municipal nº 2.503/2005 e conta com solenidades, desfiles cívicos e eventos culturais que valorizam a história da cidade.', 'SP', '3550407');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/02/2019', 'Dia do Martírio do Padre Nazareno Lanciotti', 'MUNICIPAL', 'Feriado municipal instituído pela Lei nº 425/2002 em homenagem póstuma ao Padre Nazareno Lanciotti, missionário italiano que dedicou 29 anos de trabalho social e religioso em Jauru. A data recorda seu falecimento em 22 de fevereiro de 2001 e é um marco de reflexão espiritual e reconhecimento ao seu legado para a comunidade.', 'MT', '5105002');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/02/2019', 'Feriado a Confirmar (Data Incorreta)', 'MUNICIPAL', 'Esta data (22/02) não é o feriado oficial de Capelinha. O aniversário de emancipação do município é celebrado anualmente em 24 de fevereiro, data em que a cidade obteve sua autonomia política em 1913. Não há registros na legislação municipal de feriado fixo para o dia 22 de fevereiro.', 'MG', '3112307');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/02/2019', 'Feriado a Confirmar (Data Incorreta)', 'MUNICIPAL', 'Esta data (22/02) não consta como feriado oficial para o município de Rodeiro. O Aniversário do Município é celebrado em 1º de março, data de sua emancipação política ocorrida em 1963. Não há previsão legal para feriado municipal no dia 22 de fevereiro.', 'MG', '3156304');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('23/02/2019', 'Emancipação Política de Bela Cruz', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação político-administrativa do município de Bela Cruz, ocorrida em 23 de fevereiro de 1957. A data foi oficialmente instituída como feriado pela Lei Municipal nº 932/2022.', 'CE', '2302305');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/02/2019', 'Aniversário de Banzaê', 'MUNICIPAL', 'Celebração da criação do município de Banzaê, ocorrida em 24 de fevereiro de 1989 através da Lei Estadual nº 4.485, após desmembramento de Ribeira do Pombal. O feriado municipal é formalmente instituído pela Lei Municipal nº 61/1995.', 'BA', '2902658');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/02/2019', 'Aniversário de Capelinha', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação político-administrativa de Capelinha, ocorrida em 24 de fevereiro de 1913. A data é oficializada pela Lei Municipal nº 2.091/2018.', 'MG', '3112307');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/02/2019', 'Aniversário de Iuiú', 'MUNICIPAL', 'Comemoração do aniversário de emancipação política de Iuiú, ocorrida em 24 de fevereiro de 1989 através da Lei Estadual nº 4.833. O feriado é instituído oficialmente pela Lei Municipal nº 019/1991.', 'BA', '2917334');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/02/2019', 'Aniversário de Ponto Novo', 'MUNICIPAL', 'Feriado municipal em comemoração à emancipação político-administrativa de Ponto Novo, oficializada em 24 de fevereiro de 1989 por meio da Lei Estadual nº 4.837. O município foi criado a partir do desmembramento de terras pertencentes a Caldeirão Grande.', 'BA', '2925253');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/02/2019', 'Aniversário de Sabinópolis', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação político-administrativa de Sabinópolis, ocorrida em 24 de fevereiro de 1924. A data marca o desmembramento do antigo distrito em relação ao município do Serro, consolidando a autonomia histórica e administrativa da cidade mineira.', 'MG', '3156809');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/02/2019', 'Aniversário de Sobradinho', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação política de Sobradinho, ocorrida em 24 de fevereiro de 1989 através da Lei Estadual nº 4.833. A data marca a conquista da autonomia do município, que se originou como acampamento de trabalhadores para a construção da Usina Hidrelétrica, sendo anteriormente distrito de Juazeiro.', 'BA', '2930774');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/02/2019', 'Aniversário de Canudos', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação política de Canudos, oficializada pela Lei Estadual nº 4.405, de 25 de fevereiro de 1985. O atual município, originado no vilarejo de Cocorobó e desmembrado de Euclides da Cunha, carrega o legado histórico da resistência sertaneja e celebra sua consolidação administrativa e cultural.', 'BA', '2906824');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/02/2019', 'Aniversário de Dias d''Ávila', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação política de Dias d''Ávila, conhecida como a "Cidade das Águas". A autonomia administrativa foi conquistada por meio da Lei Estadual nº 4.404, de 25 de fevereiro de 1985, quando o território se desmembrou de Camaçari. A data é um marco histórico para a Estância Hidromineral, celebrando seu desenvolvimento e identidade local.', 'BA', '2910057');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/02/2019', 'Aniversário de Wanderley', 'MUNICIPAL', 'Celebração da emancipação política do município de Wanderley, ocorrida em 25 de fevereiro de 1985. A autonomia administrativa foi estabelecida pela Lei Estadual nº 4.403, desmembrando o antigo povoado de Canabrava do território de Cotegipe. O feriado homenageia a trajetória de desenvolvimento e a identidade cultural da população no Extremo Oeste Baiano.', 'BA', '2933455');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/02/2019', 'Emancipação Política de Várzea Nova', 'MUNICIPAL', 'Comemoração da emancipação política e administrativa de Várzea Nova, ocorrida em 25 de fevereiro de 1985. O município foi desmembrado de Jacobina por meio da Lei Estadual nº 4.406, ato ratificado pelo calendário oficial de eventos (Decreto Municipal nº 04/2008). A data celebra a soberania local e o progresso alcançado pela comunidade varzeanovense.', 'BA', '2933158');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('27/02/2019', 'Aniversário de Xanxerê (Feriado Transferido para 06/03)', 'MUNICIPAL', 'Embora a emancipação político-administrativa de Xanxerê tenha ocorrido em 27 de fevereiro de 1954, o feriado municipal em 2026 foi oficialmente transferido para o dia 06 de março de 2026. A alteração foi formalizada pelo Decreto Municipal nº 271/2025 (Ofício nº 271/2025) para coincidir com a programação da XXI ExpoFemi. Portanto, o dia 27/02/2026 é considerado dia útil, enquanto as festividades e a folga oficial ocorrem na semana seguinte, com destaque para a entrada gratuita na feira e shows nacionais.', 'SC', '4219507');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('27/02/2019', 'Dia do Padre Tiago Cheza', 'MUNICIPAL', 'Feriado municipal em memória ao Padre Tiago Cheza (Giacomo Gheza), líder religioso italiano e benfeitor fundamental para o desenvolvimento de Mirassol d''Oeste, falecido em 27 de fevereiro de 1982. A data homenageia seu legado espiritual e social na Paróquia Nossa Senhora Aparecida. O feriado é oficialmente ratificado pelo calendário administrativo municipal, conforme estabelecido pelo Decreto nº 4.983/2025 e amparado por leis municipais preexistentes (como a Lei nº 1.554/2019).', 'MT', '5105622');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/02/2019', 'Aniversário da Cidade', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação de Paraty, oficializada em 28 de fevereiro de 1667 por meio de Carta do Rei Dom Afonso VI.', 'RJ', '3303807');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/02/2019', 'Aniversário da Cidade', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação de Restinga, ocorrida em 28 de fevereiro de 1964.', 'SP', '3542701');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/02/2019', 'Aniversário da Cidade', 'MUNICIPAL', 'Feriado municipal em celebração ao aniversário de emancipação político-administrativa da Estância Turística de Salesópolis, ocorrida em 28 de fevereiro de 1857.', 'SP', '3545001');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/02/2019', 'Aniversário da Cidade', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de Sebastianópolis do Sul, emancipado conforme a Lei Estadual nº 8.092 de 28 de fevereiro de 1964. Coincide com o dia de São Romano.', 'SP', '3551306');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/02/2019', 'Aniversário da Cidade', 'MUNICIPAL', 'Feriado municipal em celebração ao aniversário de emancipação político-administrativa de Silveiras, ocorrida originalmente em 28 de fevereiro de 1842.', 'SP', '3552007');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/02/2019', 'Aniversário do Município', 'MUNICIPAL', 'Feriado municipal em celebração ao aniversário de Crissiumal, marcando sua instalação oficial ocorrida em 28 de fevereiro de 1955, após a emancipação estabelecida pela Lei Estadual nº 2.553/1954.', 'RS', '4306007');
