INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('01/03/2019', 'Aniversário do Município', 'MUNICIPAL', 'Celebração do aniversário de emancipação político-administrativa do município de Mathias Lobato, instalado em 1º de março de 1963.', 'MG', '3171501');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('01/03/2019', 'Aniversário do Município', 'MUNICIPAL', 'Feriado municipal em comemoração à emancipação político-administrativa de Sengés, ocorrida em 1º de março de 1934, data em que o município foi oficialmente instalado.', 'PR', '4126306');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('01/03/2019', 'Aniversário do Município', 'MUNICIPAL', 'Feriado municipal instituído pela Lei n.º 2.012/2008, em comemoração ao aniversário de emancipação política de Videira, ocorrida em 1º de março de 1944.', 'SC', '4219309');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('01/03/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'PE', '2602407');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('01/03/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'PE', '2615201');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('01/03/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'RS', '4309704');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/03/2019', 'Aniversário de Itacarambi', 'MUNICIPAL', 'Comemoração do aniversário de emancipação político-administrativa de Itacarambi. Embora a instalação oficial tenha ocorrido historicamente em 1º de março de 1963, a legislação municipal e o calendário administrativo (como o Decreto Municipal de feriados) fixam a celebração e o feriado no dia 2 de março.', 'MG', '3132107');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/03/2019', 'Aniversário de Olímpia', 'MUNICIPAL', 'Comemoração do aniversário de fundação da Estância Turística de Olímpia, ocorrida em 2 de março de 1903. A data é feriado municipal oficial, celebrando a história e o desenvolvimento da cidade, conhecida como a Capital Nacional do Folclore.', 'SP', '3533908');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/03/2019', 'Aniversário de Palmitos', 'MUNICIPAL', 'Celebração do aniversário de emancipação político-administrativa do município, ocorrida em 2 de março de 1954. No ano de 2026, a cidade comemora seu septuagésimo segundo aniversário de autonomia e o centenário de sua colonização.', 'SC', '4212106');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/03/2019', 'Aniversário de São Romão', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de fundação/emancipação de São Romão. A data celebra a história de um dos municípios mais antigos da região, instalado originalmente em março, sendo o feriado observado oficialmente em 2 de março conforme calendário administrativo local.', 'MG', '3164209');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/03/2019', 'Dia de Uberaba (Aniversário da Cidade)', 'MUNICIPAL', 'Feriado municipal instituído pela Lei nº 5.545, de 15 de fevereiro de 1995. Celebra o aniversário de fundação da cidade de Uberaba, ocorrida em 2 de março de 1820 pelo Major Eustáquio, marcando a história do ''Sertão da Farinha Podre'' e o desenvolvimento do Triângulo Mineiro.', 'MG', '3170107');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/03/2019', 'Dia do Evangélico', 'MUNICIPAL', 'Feriado municipal instituído para celebrar o Dia do Evangélico em Lajedo do Tabocal. A data é dedicada a eventos culturais e religiosos em reconhecimento à contribuição da comunidade evangélica para o município.', 'BA', '2919058');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/03/2019', 'Emancipação Política de Ibitiara', 'MUNICIPAL', 'Feriado municipal em comemoração à emancipação política de Ibitiara, restaurada e tornada autônoma através do Decreto Estadual nº 8.830, de 2 de março de 1934.', 'BA', '2913002');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/03/2019', 'Emancipação Política de Ipubi', 'MUNICIPAL', 'Celebração da emancipação política do município de Ipubi, ocorrida oficialmente em março de 1962 (Lei Estadual nº 3.340/1958). O feriado de 2 de março é a data magna municipal consagrada para os festejos de aniversário da autonomia da cidade.', 'PE', '2607307');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/03/2019', 'Emancipação Política de Jataúba', 'MUNICIPAL', 'Data magna que celebra a emancipação política do município de Jataúba, ocorrida em 2 de março de 1962, quando se desmembrou do município de Brejo da Madre de Deus.', 'PE', '2608008');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('03/03/2019', 'Aniversário de Crucilândia', 'MUNICIPAL', 'Feriado municipal celebrativo do aniversário de Crucilândia, Minas Gerais. O município obteve sua autonomia política por meio da Lei Estadual nº 2.764, de 30 de dezembro de 1962, desmembrando-se de Itaguara. A comemoração no dia 3 de março é o marco tradicional da fundação e desenvolvimento socioeconômico da cidade, sendo um dia de festividades cívicas e religiosas.', 'MG', '3120607');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('03/03/2019', 'Aniversário de Lagamar', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de Lagamar, Minas Gerais. A data oficial de sua emancipação política é 3 de março, fundamentada na Lei Estadual nº 2.764 de 1962. A celebração recorda o desmembramento do território que anteriormente pertencia a Presidente Olegário e homenageia os pioneiros que iniciaram o povoamento às margens do córrego Carrapato.', 'MG', '3137106');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('03/03/2019', 'Aniversário de Mirabela', 'MUNICIPAL', 'Feriado municipal que celebra o aniversário de emancipação de Mirabela, Minas Gerais. Conhecida como a capital nacional da carne de sol, a cidade comemora sua autonomia política conquistada via Lei Estadual nº 2.764/1962 no dia 3 de março. O feriado é marcado por desfiles cívicos e celebrações que exaltam a cultura do Norte de Minas.', 'MG', '3142007');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('03/03/2019', 'Aniversário de Riacho dos Machados', 'MUNICIPAL', 'Feriado municipal instituído para celebrar o Aniversário de Riacho dos Machados, Minas Gerais. Conforme o Decreto Municipal nº 362/2022 e legislações anteriores, o dia 3 de março é a data oficial da cidade, celebrando sua criação pela Lei Estadual nº 2.764 de 30 de dezembro de 1962. A data homenageia a história da Família Machado e a evolução do antigo distrito de Porteirinha em município autônomo.', 'MG', '3154507');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('03/03/2019', 'Aniversário de Varzelândia', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação política e administrativa de Varzelândia. O município foi criado pela Lei Estadual nº 2.764, de 30 de dezembro de 1962, e sua instalação oficial e celebração de aniversário ocorrem tradicionalmente em 3 de março.', 'MG', '3170909');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('03/03/2019', 'Emancipação Política de Pão de Açúcar', 'MUNICIPAL', 'Feriado municipal que celebra a Emancipação Política de Pão de Açúcar, Alagoas. A data comemora a elevação do município à categoria de cidade, ocorrida em 3 de março de 1854, sendo um marco fundamental na história e autonomia administrativa da região.', 'AL', '2706406');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('04/03/2019', 'Instalação do Município', 'MUNICIPAL', 'Feriado municipal em Bossoroca que celebra a instalação oficial da administração político-administrativa da cidade, ocorrida em 4 de março de 1967. Embora o município tenha sido formalmente criado pela Lei Estadual nº 5.058, de 12 de outubro de 1965 (desmembrado de São Luiz Gonzaga), sua autonomia efetiva e a organização dos primeiros setores públicos iniciaram-se nesta data histórica com a sessão solene de instalação e a posse de João Cândido Dutra como interventor federal. A celebração é ratificada anualmente pelo calendário oficial de feriados do município, conforme previsto em decretos municipais (ex: Decreto nº 6.132/2025).', 'RS', '4302501');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('04/03/2019', 'Segunda de Carnaval', 'MUNICIPAL', 'Segunda-Feira de Carnaval', 'SC', '4202909');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/03/2019', 'Aniversário de Emancipação de Ribeirão Bonito', 'MUNICIPAL', 'Comemoração oficial do aniversário de emancipação política e administrativa do município de Ribeirão Bonito. A data remete a 5 de março de 1890, quando a localidade foi elevada à categoria de município pelo Decreto Estadual nº 21, desmembrando-se de São Carlos do Pinhal. O feriado é regido pela legislação municipal que estabelece as datas magnas do calendário local.', 'SP', '3542909');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/03/2019', 'Carnaval', 'MUNICIPAL', 'Terça feira de carnaval, feriado municipal instituído pela Lei Municipal nº 6.725/2014', 'MG', '3104007');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/03/2019', 'Carnaval', 'MUNICIPAL', 'Feriado Municipal', 'MT', '5108402');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/03/2019', 'Carnaval', 'MUNICIPAL', 'Terça-Feria de Carnaval', 'PE', '2611101');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/03/2019', 'Carnaval', 'MUNICIPAL', 'Terça-Feira de Carnaval, feriado Municipal segundo a Lei 1.990 de 20 de abril de 2011', 'RO', '1100288');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/03/2019', 'Carnaval', 'MUNICIPAL', 'Segundo Decreto nº 8.472', 'SC', '4202008');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/03/2019', 'Carnaval', 'MUNICIPAL', 'Ponto facultativo', 'SP', '3518701');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/03/2019', 'Carnaval', 'MUNICIPAL', 'Feriado de Carnaval, conforme lei nº 1242, de 26 de junho de 2014', 'SP', '3554409');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/03/2019', 'Dia Municipal do Evangélico', 'MUNICIPAL', 'Feriado municipal dedicado à celebração e reflexão da comunidade evangélica no município de Biritinga. A data foi oficialmente integrada ao calendário de feriados locais por meio da legislação municipal, frequentemente referenciada pelo Decreto 061/2009, promovendo o reconhecimento cultural e religioso deste segmento na sociedade biritinguense e assegurando o direito ao culto e à manifestação pública de fé.', 'BA', '2903607');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/03/2019', 'Dia da Instalação do Município de Bom Jardim da Serra', 'MUNICIPAL', 'Celebração da instalação oficial do município de Bom Jardim da Serra, ocorrida em 5 de março de 1967. Embora a criação da unidade administrativa tenha se dado pela Lei Estadual nº 1.052, de 26 de janeiro de 1967, a data magna municipal comemora o ato de instalação político-administrativa, que consolidou a autonomia da cidade em relação ao município de São Joaquim.', 'SC', '4202503');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/03/2019', 'Dia de Patativa do Assaré', 'MUNICIPAL', 'Feriado municipal instituído para celebrar o nascimento de Antônio Gonçalves da Silva, o ''Patativa do Assaré'' (1909-2002). A data, oficializada pela Lei Municipal nº 444/2007, homenageia o legado do poeta, compositor e repentista, considerado um dos maiores expoentes da cultura popular nordestina e da literatura de cordel.', 'CE', '2301604');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/03/2019', 'Emancipação Política de Caraúbas', 'MUNICIPAL', 'Celebração da emancipação política do município de Caraúbas, ocorrida em 5 de março de 1868 através da Lei Provincial nº 601. A data marca o desmembramento da localidade em relação à cidade de Mossoró, elevando-a à categoria de vila. É um feriado municipal estabelecido pela Lei Orgânica do Município e constitui a data magna da cidade.', 'RN', '2402303');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('06/03/2019', 'Aniversário de Itaporanga', 'MUNICIPAL', 'Feriado municipal fundamentado na Lei Municipal nº 1.865/2006, que reconhece oficialmente o dia 06 de março de 1871 como a data de emancipação político-administrativa do município. A festividade celebra o momento histórico em que a localidade conquistou sua autonomia, desvinculando-se de Itapeva (antiga Faxina), sob o nome original de São João Batista do Rio Verde.', 'SP', '3522802');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('06/03/2019', 'Data Magna de Jijoca de Jericoacoara', 'MUNICIPAL', 'Feriado municipal instituído pela Lei Municipal nº 625/2020. A data celebra a emancipação política de Jijoca de Jericoacoara, ocorrida em 06 de março de 1991 através da Lei Estadual nº 11.796, marcando o desmembramento do território do município de Cruz e a autonomia administrativa da cidade.', 'CE', '2307254');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('06/03/2019', 'Dia do Município de Horizonte', 'MUNICIPAL', 'Feriado municipal em comemoração à emancipação política de Horizonte, oficializada em 06 de março de 1987. O processo de autonomia foi resultado de um plebiscito popular e da promulgação de legislação estadual que permitiu o desmembramento de territórios antes pertencentes a Pacajus e Itaitinga, transformando Horizonte em uma unidade administrativa independente.', 'CE', '2305233');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('06/03/2019', 'Dia do Município de Maracanaú', 'MUNICIPAL', 'Feriado municipal estabelecido pelo Artigo 276 da Lei Orgânica do Município de Maracanaú. A data celebra a emancipação política ocorrida em 06 de março de 1983, quando a cidade conquistou autonomia em relação a Fortaleza. É uma data de grande relevância civil, marcando o início da trajetória de Maracanaú como um dos principais centros industriais e administrativos do estado do Ceará.', 'CE', '2307650');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('06/03/2019', 'Quarta-Feira de Cinzas', 'MUNICIPAL', 'Quarta-Feira de Cinzas', 'BA', '2913200');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('06/03/2019', 'Quarta-Feira de Cinzas', 'MUNICIPAL', 'Quarta-Feira de Cinzas, feriado conforme lei nº 603, de 05 de março de 1996', 'MG', '3134707');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('06/03/2019', 'Quarta-feira de cinzas', 'MUNICIPAL', 'Ponto facultativo parcial - até 12 horas', 'SP', '3518701');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('07/03/2019', 'Aniversário de Lábrea', 'MUNICIPAL', 'Feriado municipal instituído para celebrar o aniversário de fundação e a elevação de Lábrea à categoria de cidade, ocorrida em 7 de março de 1886. O município, conhecido como a ''Princesinha do Purus'', teve sua formação ligada ao esforço colonizador do Coronel Antônio Rodrigues Pereira Labre e ao auge do ciclo econômico da borracha na região amazônica. A data é oficialmente reconhecida pela Lei Orgânica do Município e integra o calendário histórico e cultural do estado do Amazonas.', 'AM', '1302405');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('07/03/2019', 'Aniversário de Pirangi', 'MUNICIPAL', 'Feriado municipal em comemoração à emancipação político-administrativa de Pirangi, formalizada em 7 de março de 1935. A celebração marca o desmembramento territorial e administrativo do município em relação à comarca de Jaboticabal, processo que consolidou sua autonomia política sob o respaldo do Decreto Estadual nº 6.983/1935. O feriado é amparado pela legislação municipal e é tradicionalmente observado com atos cívicos e festividades que ressaltam a identidade local.', 'SP', '3539004');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('08/03/2019', 'Aniversário de Tietê', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de fundação do município de Tietê, ocorrida em 08 de março de 1842. A data celebra a história e o desenvolvimento da cidade paulista.', 'SP', '3554508');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('08/03/2019', 'Dia Internacional da Mulher', 'MUNICIPAL', 'Feriado municipal instituído pela Lei Municipal nº 1.063/2013, em reconhecimento à importância social e às lutas das mulheres no município de Inhambupe.', 'BA', '2913705');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('08/03/2019', 'Dia Internacional da Mulher', 'MUNICIPAL', 'Feriado municipal conforme a Lei Municipal nº 156/2011, que oficializa o Dia da Mulher no calendário de feriados de Nordestina.', 'BA', '2922656');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('08/03/2019', 'Dia Internacional da Mulher', 'MUNICIPAL', 'Feriado municipal instituído pela Lei Municipal nº 123/2013, dedicado às comemorações do Dia Internacional da Mulher em Queimadas.', 'BA', '2925808');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('08/03/2019', 'Dia Internacional da Mulher', 'MUNICIPAL', 'Feriado municipal em Retirolândia, conforme a Lei Municipal nº 212/2011, destinado à valorização das mulheres na sociedade local.', 'BA', '2926103');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('08/03/2019', 'Dia Internacional da Mulher', 'MUNICIPAL', 'Feriado municipal instituído pela Lei Municipal nº 337/2011 no município de São Domingos, em homenagem ao Dia Internacional da Mulher.', 'BA', '2928950');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('08/03/2019', 'Dia Internacional da Mulher', 'MUNICIPAL', 'Feriado municipal em Sátiro Dias, estabelecido pela Lei Municipal nº 510/2013, dedicado às celebrações e reflexões sobre os direitos das mulheres.', 'BA', '2929701');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('08/03/2019', 'Dia Internacional da Mulher', 'MUNICIPAL', 'Feriado municipal instituído pela Lei Municipal nº 455/2011 no município de Serra Preta, em reconhecimento ao Dia Internacional da Mulher.', 'BA', '2930402');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('08/03/2019', 'Dia Internacional da Mulher', 'MUNICIPAL', 'Feriado municipal instituído pela Lei Municipal nº 588/2011, que oficializa o dia 8 de março como data de repouso remunerado em homenagem às mulheres de Valente.', 'BA', '2933000');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('08/03/2019', 'Dia Internacional da Mulher', 'MUNICIPAL', 'Feriado municipal estabelecido pela Lei Municipal nº 425/2013 em Wanderley, celebrando as conquistas sociais e políticas das mulheres.', 'BA', '2933455');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('08/03/2019', 'Dia Internacional da Mulher', 'MUNICIPAL', 'Feriado municipal em Santo Antônio do Descoberto, instituído pela Lei Municipal nº 765/2011, em homenagem ao Dia Internacional da Mulher.', 'GO', '5219753');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('08/03/2019', 'Dia Internacional da Mulher', 'MUNICIPAL', 'Feriado municipal em Concórdia do Pará, instituído pela Lei Municipal nº 265/2012, em celebração às conquistas femininas.', 'PA', '1502756');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('08/03/2019', 'Dia Internacional da Mulher', 'MUNICIPAL', 'Feriado municipal em Juruti, instituído pela Lei Municipal nº 1.025/2013, em celebração ao Dia Internacional da Mulher.', 'PA', '1503903');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('08/03/2019', 'Dia Internacional da Mulher', 'MUNICIPAL', 'Feriado municipal instituído pela Lei Municipal nº 498/2011 em Araçagi, em homenagem ao Dia Internacional da Mulher.', 'PB', '2500809');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('08/03/2019', 'Dia Internacional da Mulher', 'MUNICIPAL', 'Feriado municipal instituído pela Lei Municipal nº 386/2011, dedicado à valorização da mulher no município de Duas Estradas.', 'PB', '2505808');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('08/03/2019', 'Dia Internacional da Mulher', 'MUNICIPAL', 'Feriado municipal em Cerro Grande, estabelecido pela Lei Municipal nº 775/2010, em comemoração ao Dia Internacional da Mulher.', 'RS', '4305157');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('08/03/2019', 'Dia Internacional da Mulher', 'MUNICIPAL', 'Feriado municipal instituído pela Lei Municipal nº 1.190/2011, que oficializa o Dia Internacional da Mulher como data festiva e feriado em Dianópolis.', 'TO', '1707009');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('08/03/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'SP', '3529708');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('09/03/2019', 'Aniversário de Altinópolis', 'MUNICIPAL', 'Celebração da fundação e emancipação do município de Altinópolis, ocorrida em 9 de março de 1919. O feriado é observado anualmente conforme o calendário oficial de feriados municipais estabelecido pela prefeitura.', 'SP', '3501004');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('09/03/2019', 'Aniversário de Cachoeira Paulista', 'MUNICIPAL', 'Feriado municipal em celebração ao aniversário de Cachoeira Paulista. Comemora-se a elevação da antiga Freguesia de Santo Antônio da Cachoeira à condição de Vila em 9 de março de 1880, marco inicial da autonomia municipal.', 'SP', '3508603');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('09/03/2019', 'Aniversário de Joinville', 'MUNICIPAL', 'Feriado municipal em celebração à fundação da cidade de Joinville, ocorrida em 9 de março de 1851. A data é oficialmente instituída pela Lei Municipal nº 2.576/1991, que consolidou legislações anteriores, incluindo a Lei nº 733/1965.', 'SC', '4209102');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('09/03/2019', 'Aniversário de São José do Barreiro', 'MUNICIPAL', 'Feriado municipal que celebra a criação da Vila de São José do Barreiro, instituída pela Lei Provincial nº 6, de 9 de março de 1859, data que marca a emancipação político-administrativa do município.', 'SP', '3549607');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('09/03/2019', 'Aniversário de Virginópolis', 'MUNICIPAL', 'Feriado municipal que celebra a instalação e emancipação político-administrativa de Virginópolis, ocorrida em 9 de março de 1924. A data marca a autonomia do município em relação a Guanhães e Peçanha.', 'MG', '3171808');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('09/03/2019', 'Emancipação Política de Espinosa', 'MUNICIPAL', 'Feriado municipal comemorativo à emancipação política do município de Espinosa, ocorrida em 9 de março de 1924. A data é estabelecida pela Lei Municipal nº 991/1995 e ratificada anualmente por decretos do Poder Executivo.', 'MG', '3124302');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('09/03/2019', 'Emancipação Política de São José do Egito', 'MUNICIPAL', 'Feriado municipal em comemoração à emancipação de São José do Egito, ocorrida em 9 de março de 1909. A celebração é fundamentada no Artigo 214 da Lei Orgânica Municipal e reconhecida oficialmente pela administração local.', 'PE', '2613602');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/03/2019', 'Aniversário de Barra do Piraí', 'MUNICIPAL', 'Celebração do aniversário de emancipação político-administrativa de Barra do Piraí. O município foi criado pelo Decreto Estadual nº 30, de 10 de março de 1890, desmembrando-se de terras de Piraí, Vassouras e Valença.', 'RJ', '3300308');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/03/2019', 'Aniversário de Campos Novos Paulista', 'MUNICIPAL', 'Feriado municipal em celebração ao aniversário da cidade. Campos Novos Paulista conquistou sua emancipação política em 10 de março de 1885, consolidando-se como um importante polo histórico no Vale do Paranapanema.', 'SP', '3509809');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/03/2019', 'Aniversário de Eldorado', 'MUNICIPAL', 'Comemoração oficial do aniversário da Estância Turística de Eldorado. A cidade celebra sua emancipação político-administrativa ocorrida em 10 de março de 1842, sendo uma das cidades mais antigas e históricas do Vale do Ribeira.', 'SP', '3514809');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/03/2019', 'Aniversário de Luzilândia', 'MUNICIPAL', 'Feriado municipal que celebra o aniversário de emancipação política de Luzilândia, ocorrida em 10 de março de 1890. A data é um marco cívico para a população local, celebrando a história e o desenvolvimento da região do Baixo Parnaíba.', 'PI', '2205805');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/03/2019', 'Aniversário de Monte Aprazível', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação política e administrativa do município de Monte Aprazível, ocorrida em 10 de março de 1925. A data celebra a autonomia da cidade e sua história no interior paulista.', 'SP', '3531407');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/03/2019', 'Aniversário de Patrocínio Paulista', 'MUNICIPAL', 'Comemoração do aniversário de emancipação política de Patrocínio Paulista, ocorrida em 10 de março de 1885. O feriado exalta a história dos pioneiros e o desenvolvimento do município no nordeste paulista.', 'SP', '3536307');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/03/2019', 'Aniversário de Santana do Matos', 'MUNICIPAL', 'Feriado municipal em Santana do Matos celebrando a sua elevação à categoria de Vila e sede de município pela Resolução nº 121, de 10 de março de 1845. É uma das datas mais importantes do calendário cívico local.', 'RN', '2411403');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/03/2019', 'Emancipação Política de Ituverava', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação político-administrativa de Ituverava, formalizada em 10 de março de 1885. A data é marcada por eventos cívicos e festividades que exaltam a história da ''Cidade das Escolas''.', 'SP', '3524105');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/03/2019', 'Aniversário de Angatuba', 'MUNICIPAL', 'Feriado municipal em celebração ao aniversário de fundação do município de Angatuba, ocorrida em 11 de março de 1872. A data é um marco da identidade local, celebrando a trajetória histórica da cidade desde sua origem como povoado de Ribeirão Grande até sua autonomia administrativa.', 'SP', '3502200');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/03/2019', 'Aniversário de Guaraqueçaba', 'MUNICIPAL', 'Feriado municipal dedicado às festividades do aniversário de Guaraqueçaba. A data de 11 de março é o marco tradicional para celebrar a história secular do município (com raízes em 1545), englobando sua importância histórica como um dos primeiros assentamentos do Paraná e sua posterior emancipação política em 1880.', 'PR', '4109500');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/03/2019', 'Emancipação Política de Governador Eugênio Barros', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação política de Governador Eugênio Barros. O município foi criado pela Lei Estadual nº 2.174, de 26 de dezembro de 1961, e oficialmente instalado em 11 de março de 1962, data em que se comemora a conquista de sua autonomia em relação ao município de Caxias.', 'MA', '2104602');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/03/2019', 'Emancipação Política de Mirandiba', 'MUNICIPAL', 'Comemoração da Emancipação Política de Mirandiba, ocorrida em 11 de março de 1962. Este feriado municipal recorda o desmembramento do município em relação a São José do Belmonte, consolidando sua soberania política e administrativa no estado de Pernambuco.', 'PE', '2609303');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('12/03/2019', 'Aniversário de Olinda', 'MUNICIPAL', 'Feriado municipal celebrando a fundação da cidade de Olinda no ano de 1535 por Duarte Coelho. A data, que coincide com o aniversário da cidade do Recife, é reconhecida como feriado municipal em Olinda nos termos da Lei Municipal nº 4.380 de 10 de outubro de 1983.', 'PE', '2609600');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('12/03/2019', 'Aniversário de São Lourenço da Serra', 'MUNICIPAL', 'Feriado municipal em celebração à Emancipação Político-Administrativa do município, ocorrida em 12 de março de 1991. A data é oficialmente instituída como feriado pelo Artigo 246, incisos I e II, da Lei Orgânica Municipal e pela Lei Municipal nº 704/2007.', 'SP', '3549953');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('12/03/2019', 'Dia da Fundação de Paraíso do Norte', 'MUNICIPAL', 'Feriado municipal que celebra a data da fundação da cidade de Paraíso do Norte. A celebração é legalmente fundamentada no Artigo 142, alínea ''a'', da Lei Municipal nº 08/1969 (Código de Posturas), que estabelece o dia 12 de março como feriado oficial.', 'PR', '4118006');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('12/03/2019', 'Dia do Município de Paraguaçu Paulista', 'MUNICIPAL', 'Feriado municipal em celebração à fundação do município, ocorrida em 12 de março de 1925. A data é instituída conforme o Artigo 5º das Disposições Gerais Transitórias da Lei Orgânica do Município e reiterada por decretos anuais (como o Decreto nº 7.277/2024).', 'SP', '3535507');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('12/03/2019', 'Emancipação Política de Crisópolis', 'MUNICIPAL', 'Feriado municipal comemorativo ao aniversário de emancipação política de Crisópolis, ocorrida em 12 de março de 1962, quando o território foi desmembrado de Itapicuru para tornar-se um município autônomo, conforme registros históricos e legislação local.', 'BA', '2909604');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('12/03/2019', 'Emancipação Política de Moita Bonita', 'MUNICIPAL', 'Feriado municipal em comemoração à emancipação política de Moita Bonita, originada pela Lei Estadual nº 1.165 de 12 de março de 1963. A data foi ratificada como feriado municipal por legislação local recente (Lei de 08/03/2023) para celebrar a autonomia administrativa frente a Itabaiana.', 'SE', '2804102');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('13/03/2019', 'Aniversário da Cidade de Cachoeira', 'MUNICIPAL', 'Comemoração da elevação da antiga Vila de Nossa Senhora do Rosário do Porto da Cachoeira à categoria de cidade, ocorrida em 13 de março de 1837, mediante a Lei Provincial nº 43. A cidade é reconhecida como ''Cidade Heroica'' por sua importância histórica e decisiva na luta pela Independência da Bahia e do Brasil.', 'BA', '2904902');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('13/03/2019', 'Aniversário de Santo Antônio do Içá', 'MUNICIPAL', 'Celebração do aniversário de emancipação e fundação do município de Santo Antônio do Içá, conhecido como a ''Cidade-presépio do Alto Solimões''. A data recorda a instalação definitiva do município ocorrida em 1956, após o desmembramento de São Paulo de Olivença por meio da Lei Estadual nº 96.', 'AM', '1303700');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('13/03/2019', 'Aniversário de Sarapuí', 'MUNICIPAL', 'Comemoração do aniversário de fundação e emancipação política de Sarapuí. A data de 13 de março é marcada por celebrações cívicas e culturais em honra à história do município, que teve sua emancipação definitiva reconhecida e celebrada anualmente nesta data.', 'SP', '3551108');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('13/03/2019', 'Dia da Batalha do Jenipapo', 'MUNICIPAL', 'Feriado municipal em Campo Maior que homenageia os heróis da Batalha do Jenipapo, ocorrida em 13 de março de 1823. O confronto sangrento entre brasileiros e tropas portuguesas foi fundamental para a consolidação da Independência do Brasil no norte do país. O feriado é regulamentado pela Lei Municipal nº 001/2017.', 'PI', '2202208');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('13/03/2019', 'Dia da Emancipação de Carapebus', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação político-administrativa de Carapebus, ocorrida em 13 de março de 1995. A data marca a vitória no plebiscito que resultou no desmembramento do território do município de Macaé, sendo feriado instituído no calendário oficial desde 1997.', 'RJ', '3300936');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('13/03/2019', 'Dia da Emancipação de Seropédica', 'MUNICIPAL', 'Celebração dedicada à data histórica da emancipação de Seropédica através de plebiscito. Instituído como feriado municipal pela Lei nº 207 de 26 de fevereiro de 2003, recorda o segundo plebiscito realizado em 13 de março de 1994, que consolidou a autonomia política e administrativa do município frente a Itaguaí.', 'RJ', '3305554');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('14/03/2019', 'Aniversário de Batatais', 'MUNICIPAL', 'Feriado municipal que comemora a fundação da cidade de Batatais em 14 de março de 1839. Trata-se de uma data magna para a Estância Turística de Batatais, celebrando sua história desde o período colonial e cafeeiro.', 'SP', '3505906');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('14/03/2019', 'Aniversário de Bom Jardim', 'MUNICIPAL', 'Comemoração do aniversário de emancipação político-administrativa do município de Bom Jardim, ocorrida em 14 de março de 1967. O feriado é anualmente ratificado pelo calendário oficial de feriados (ex: Decreto Municipal nº 01/2026).', 'MA', '2102002');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('14/03/2019', 'Aniversário de Dionísio Cerqueira', 'MUNICIPAL', 'Feriado municipal instituído pela Lei nº 4.082/2010 em comemoração à emancipação política de Dionísio Cerqueira, ocorrida em 14 de março de 1954. A data celebra o desenvolvimento administrativo da cidade na fronteira catarinense.', 'SC', '4205001');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('14/03/2019', 'Aniversário de Grandes Rios', 'MUNICIPAL', 'Feriado municipal em celebração ao aniversário de fundação de Grandes Rios, ocorrida em 14 de março de 1964. A data celebra a autonomia do município e é formalizada pela Lei Orgânica e decretos anuais da prefeitura.', 'PR', '4108700');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('14/03/2019', 'Aniversário de Rodeio', 'MUNICIPAL', 'Celebração do aniversário de emancipação político-administrativa do município de Rodeio. A data de 14 de março marca a criação da cidade e é observada como feriado conforme o calendário oficial da prefeitura de Santa Catarina.', 'SC', '4215109');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('14/03/2019', 'Emancipação Política de Governador Mangabeira', 'MUNICIPAL', 'Celebração da emancipação política do município, instituída pela Lei Estadual nº 1.640, de 14 de março de 1962. A data é formalmente reconhecida como feriado municipal pelo Art. 6º, § 4º da Lei Orgânica do Município de Governador Mangabeira.', 'BA', '2911600');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('14/03/2019', 'Emancipação Política de Santa Inês', 'MUNICIPAL', 'Feriado municipal em comemoração à emancipação político-administrativa de Santa Inês, ocorrida em 14 de março de 1967, quando o município foi desmembrado de Pindaré-Mirim. A data é o marco fundamental da autonomia da cidade, conhecida como a ''Princesa do Vale do Pindaré''.', 'MA', '2109908');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('14/03/2019', 'Nascimento do Poeta Castro Alves', 'MUNICIPAL', 'Feriado em homenagem ao nascimento de Antônio Frederico de Castro Alves (1847-1871), o ''Poeta dos Escravos'', nascido na Fazenda Cabaceiras (antiga Vila de Curralinho). A cidade, que hoje leva seu nome, celebra a data como seu principal marco histórico e cultural.', 'BA', '2907301');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/03/2019', 'Aniversário de Monte Alegre', 'MUNICIPAL', 'Celebração da elevação de Monte Alegre à categoria de cidade, ocorrida em 15 de março de 1880. A data é a principal comemoração cívica municipal e feriado local consolidado.', 'PA', '1504802');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/03/2019', 'Aniversário de Nova Londrina', 'MUNICIPAL', 'Feriado municipal que celebra o aniversário da cidade, comemorando a data de sua instalação ocorrida em 15 de março de 1956, conforme instituído pela Lei Municipal nº 661/1976.', 'PR', '4117107');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/03/2019', 'Emancipação Política de Conceição de Macabu', 'MUNICIPAL', 'Celebração da emancipação político-administrativa de Conceição de Macabu, ocorrida em 15 de março de 1952, quando o município conquistou sua autonomia em relação a Macaé após plebiscito popular.', 'RJ', '3301405');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/03/2019', 'Emancipação Política de Gravatá', 'MUNICIPAL', 'Comemoração da emancipação política e constituição do município de Gravatá, ocorrida em 15 de março de 1893. O feriado é regido pelas Leis Municipais nº 592/1980 e nº 3.815/2019.', 'PE', '2606408');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/03/2019', 'Emancipação Política de Miranda do Norte', 'MUNICIPAL', 'Feriado municipal que celebra a criação e emancipação do município de Miranda do Norte, ocorrida em 15 de março de 1988, através da Lei Estadual nº 4.866.', 'MA', '2106755');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/03/2019', 'Emancipação Política de Quijingue', 'MUNICIPAL', 'Comemoração do aniversário de emancipação política do município de Quijingue, ocorrida em 15 de março de 1962, por força da Lei Estadual nº 1.640, quando se desmembrou de Tucano.', 'BA', '2925907');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/03/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'RS', '4312203');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/03/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'SC', '4202453');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/03/2019', 'Instalação Municipal de Chã Grande', 'MUNICIPAL', 'Feriado municipal que comemora a data de instalação oficial do município de Chã Grande, ocorrida em 15 de março de 1964. A data é prevista como feriado pela Lei Municipal nº 558/1979.', 'PE', '2604502');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('16/03/2019', 'Aniversário da Cidade de Ouro Fino', 'MUNICIPAL', 'Feriado municipal instituído pela Lei Municipal nº 2/1981 e corroborado pela Lei nº 991/1976, em celebração ao aniversário da cidade de Ouro Fino, comemorado anualmente em 16 de março em memória da instalação do município.', 'MG', '3146008');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('16/03/2019', 'Aniversário da Fundação de Petrópolis', 'MUNICIPAL', 'Feriado municipal em Petrópolis estabelecido pela Lei nº 4.753/1990, que celebra a fundação da cidade em 16 de março de 1843, data em que o Imperador Dom Pedro II assinou o decreto criando a Povoação de Petrópolis.', 'RJ', '3303906');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('16/03/2019', 'Aniversário de Emancipação Política de Catanduvas', 'MUNICIPAL', 'Feriado municipal celebrando o aniversário de emancipação político-administrativa do município de Catanduvas, ocorrida em 16 de março de 1963. A data é anualmente confirmada nos calendários oficiais da prefeitura.', 'SC', '4204004');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('16/03/2019', 'Aniversário de Guareí', 'MUNICIPAL', 'Feriado municipal que celebra a fundação e a emancipação política do município de Guareí, ocorrida em 16 de março, data em que a cidade comemora sua autonomia e história regional.', 'SP', '3518503');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('16/03/2019', 'Dia da Emancipação Política de Santa Maria do Suaçuí', 'MUNICIPAL', 'Feriado municipal estabelecido pela Lei Municipal nº 1.006, de 21 de maio de 2015, comemorando a emancipação política de Santa Maria do Suaçuí ocorrida em 16 de março.', 'MG', '3158201');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('16/03/2019', 'Dia do Município (Aniversário de Manhumirim)', 'MUNICIPAL', 'Celebração do aniversário de emancipação político-administrativa do município de Manhumirim, formalizada em 16 de março de 1924. A data é feriado local conforme legislação municipal.', 'MG', '3139508');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('16/03/2019', 'Emancipação Política de Pilar', 'MUNICIPAL', 'Feriado municipal instituído pela Lei nº 583/2015, em comemoração à emancipação política do município de Pilar, ocorrida em 16 de março de 1872, conforme a Lei Provincial nº 626.', 'AL', '2706901');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('16/03/2019', 'Emancipação Política de Quebrangulo', 'MUNICIPAL', 'Comemoração oficial da emancipação política do município de Quebrangulo, ocorrida em 16 de março de 1872. Trata-se da data magna da cidade, celebrando sua autonomia administrativa em relação a Palmeira dos Índios.', 'AL', '2707602');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('16/03/2019', 'Emancipação Político-Administrativa de São Sebastião', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação político-administrativa de São Sebastião, ocorrida em 16 de março de 1636. A data marca a fundação e a autonomia da cidade, sendo comemorada anualmente com eventos cívicos e culturais.', 'SP', '3550704');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('17/03/2019', 'Aniversário de Aracaju', 'MUNICIPAL', 'Comemoração do aniversário da capital de Sergipe, fundada em 17 de março de 1855. A data marca a transferência da sede administrativa da província de São Cristóvão para a nova capital planejada, Aracaju, sob o governo de Inácio Joaquim Barbosa.', 'SE', '2800308');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('17/03/2019', 'Aniversário de Indiana', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de fundação do município de Indiana, ocorrida em 17 de março de 1948. A celebração homenageia a história da cidade, conhecida como polo ceramista regional.', 'SP', '3520608');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('17/03/2019', 'Aniversário de Rio das Flores', 'MUNICIPAL', 'Celebração do aniversário de emancipação político-administrativa do município, ocorrida em 17 de março de 1890 por força do Decreto Estadual nº 62. A data é ratificada como feriado municipal (''Dia do Município'') pela Lei Municipal nº 475/1980.', 'RJ', '3304508');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('17/03/2019', 'Dia de São Patrício (Padroeiro)', 'MUNICIPAL', 'Feriado religioso em celebração a São Patrício, padroeiro do município de Ceres e de todo o Vale de São Patrício. A festividade é tradicional na cidade desde 1997, refletindo a herança cultural e a fé da comunidade local.', 'GO', '5205406');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('17/03/2019', 'Dia de São Patrício (Padroeiro)', 'MUNICIPAL', 'Feriado religioso em honra a São Patrício, padroeiro da região do Vale de São Patrício. No município de Rialma, a data é instituída como feriado oficial por meio da Lei Municipal nº 1.010/2005.', 'GO', '5218607');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('17/03/2019', 'Dia de São Patrício (Padroeiro)', 'MUNICIPAL', 'Feriado municipal dedicado a São Patrício, padroeiro da cidade de Itaqui. A data é oficialmente reconhecida como evento municipal e feriado conforme disposto na Lei Municipal nº 2.195/1996 e alteração pela Lei nº 2.288/1997.', 'RS', '4310603');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('17/03/2019', 'Retratação Política de José Manoel da Silva', 'MUNICIPAL', 'Feriado municipal que celebra a ''Retratação Política de José Manoel da Silva'', fato histórico relevante para a pacificação e organização política local. A data é formalmente incluída no calendário de feriados de Toritama por decretos anuais e legislação específica.', 'PE', '2615409');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('18/03/2019', 'Aniversário de Antônio João', 'MUNICIPAL', 'Comemoração do aniversário de emancipação político-administrativa de Antônio João, MS. O município foi criado pela Lei Estadual nº 2.142, de 18 de março de 1964. A data celebra a autonomia do município e sua fundação oficial.', 'MS', '5000906');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('18/03/2019', 'Aniversário de Gaspar', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação política do município de Gaspar, ocorrida em 18 de março de 1934, quando se desmembrou de Blumenau. A data é oficialmente instituída pela Lei Orgânica Municipal e pelo calendário legislativo local.', 'SC', '4205902');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('18/03/2019', 'Aniversário de Jaborandi', 'MUNICIPAL', 'Feriado municipal referente ao aniversário de emancipação de Jaborandi, ocorrida em 18 de março de 1948, através da Lei Estadual nº 233. A celebração marca a conquista da autonomia política e administrativa do município paulista.', 'SP', '3524204');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('18/03/2019', 'Aniversário de Pedregulho', 'MUNICIPAL', 'Feriado municipal em comemoração à fundação e emancipação de Pedregulho, ocorrida em 18 de março de 1897. A data é feriado oficial conforme estabelecido na Lei Orgânica do Município e celebra o desenvolvimento da cidade na região da Alta Mogiana.', 'SP', '3537008');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('18/03/2019', 'Aniversário de Tibagi', 'MUNICIPAL', 'Feriado municipal em celebração à emancipação política de Tibagi, ocorrida em 18 de março de 1872. A data comemora o momento em que a localidade foi elevada à categoria de município, desmembrando-se de Castro, sendo um dos municípios mais tradicionais do Paraná.', 'PR', '4127502');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('18/03/2019', 'Emancipação Política de Mata Grande', 'MUNICIPAL', 'Feriado municipal celebrando a emancipação política de Mata Grande. Embora sua origem date de períodos anteriores, a data de 18 de março é o marco solene adotado pelo município para celebrar sua autonomia e história administrativa perante o estado de Alagoas.', 'AL', '2705002');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('18/03/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'PB', '2511400');
