INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/03/2019', 'Aniversário de Aparecida d''Oeste', 'MUNICIPAL', 'Feriado municipal em celebração à fundação e emancipação de Aparecida d''Oeste, que ocorreu oficialmente em 22 de março de 1965, data em que o município se tornou autônomo.', 'SP', '3502606');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/03/2019', 'Aniversário de Balsas', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação política e fundação da cidade de Balsas, ocorrida em 22 de março de 1918. A data celebra a autonomia administrativa do município, consolidando sua importância econômica e cultural no sul do estado do Maranhão.', 'MA', '2101400');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/03/2019', 'Aniversário de Botuporã', 'MUNICIPAL', 'Feriado municipal destinado à celebração do aniversário de emancipação político-administrativa do município de Botuporã. A cidade conquistou sua autonomia em 22 de março de 1962, desmembrando-se de Macaúbas, conforme registros históricos da Assembleia Legislativa da Bahia.', 'BA', '2904209');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/03/2019', 'Aniversário de Nova Granada', 'MUNICIPAL', 'Feriado municipal celebrando a instalação solene do município de Nova Granada, ocorrida em 22 de março de 1926, após sua criação por lei estadual no final de 1925.', 'SP', '3533007');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/03/2019', 'Aniversário de Onda Verde', 'MUNICIPAL', 'Feriado municipal que celebra o aniversário de instalação do município de Onda Verde, ocorrida em 22 de março de 1965, após o desmembramento do território de Nova Granada.', 'SP', '3534005');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/03/2019', 'Aniversário de Pratânia', 'MUNICIPAL', 'Feriado municipal celebrando a emancipação política de Pratânia, ocorrida em 22 de março de 1997, quando o município conquistou sua autonomia administrativa.', 'SP', '3541059');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/03/2019', 'Aniversário de Santa Adélia', 'MUNICIPAL', 'Feriado municipal em comemoração à emancipação político-administrativa de Santa Adélia, ocorrida em 22 de março de 1916. A data marca a autonomia do município frente a Taquaritinga.', 'SP', '3545605');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/03/2019', 'Aniversário de São Pedro do Sul', 'MUNICIPAL', 'Comemoração da emancipação político-administrativa do município de São Pedro do Sul, ocorrida em 22 de março de 1926. O feriado municipal é amparado pela Lei Ordinária Municipal nº 223/1956.', 'RS', '4319406');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/03/2019', 'Dia do Padroeiro e Aniversário de Santo Ângelo', 'MUNICIPAL', 'Feriado municipal instituído pela Lei nº 1.075/1988, que celebra simultaneamente o Dia do Padroeiro do município, Santo Ângelo Custódio, e o aniversário de emancipação político-administrativa da cidade, ocorrida em 22 de março de 1873.', 'RS', '4317509');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/03/2019', 'Emancipação Política de Canas', 'MUNICIPAL', 'Feriado municipal estabelecido pela Lei Municipal nº 548/2017, celebrando a emancipação política de Canas, ocorrida originalmente em 22 de março de 1993 (com instalação em 1997).', 'SP', '3509957');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('23/03/2019', 'Aniversário de Florianópolis', 'MUNICIPAL', 'Feriado municipal em celebração ao ''Dia do Município de Florianópolis'', conforme estabelecido pela Lei Municipal nº 10.306 de 24/11/2017 e ratificado pela Lei Municipal nº 10.482/2019. A data comemora a fundação e a emancipação política da capital catarinense, sendo um feriado civil consolidado no calendário oficial municipal.', 'SC', '4205407');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('23/03/2019', 'Aniversário de Viradouro', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação e fundação do município de Viradouro. A data de 23 de março celebra a história da cidade, fundada no início do século XX e elevada à categoria de município, sendo feriado civil conforme o calendário oficial da prefeitura e leis municipais vigentes.', 'SP', '3556800');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('23/03/2019', 'Emancipação Política de Apodi', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação política de Apodi, ocorrida em 23 de março de 1835, quando a localidade se desmembrou da Vila de Portalegre. A data é feriado oficial no município, conforme estabelecido pela Lei Complementar nº 018/2023 e pela Lei Orgânica Municipal, sendo o marco mais importante da história administrativa local.', 'RN', '2401008');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/03/2019', 'Aniversário de Arroio Grande', 'MUNICIPAL', 'Feriado municipal comemorativo à emancipação política da cidade, elevada à categoria de vila em 24 de março de 1873. O feriado é regulamentado pelo Decreto Legislativo nº 604, de 26 de outubro de 2015.', 'RS', '4301305');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/03/2019', 'Aniversário de Barra Funda', 'MUNICIPAL', 'Feriado municipal em celebração à emancipação político-administrativa de Barra Funda, oficializada em decorrência da Lei Estadual nº 9.584, de 20 de março de 1992, que culminou na autonomia do município nesta data.', 'RS', '4301958');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/03/2019', 'Aniversário de Cabreúva', 'MUNICIPAL', 'Feriado municipal em comemoração à fundação da cidade de Cabreúva, ocorrida em 24 de março de 1859. Trata-se da principal data cívica do município, celebrando sua história e desenvolvimento no interior paulista.', 'SP', '3508405');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/03/2019', 'Aniversário de Candiota', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação do município, instituído em virtude da Lei Estadual nº 9.596, de 24 de março de 1992. A data marca a autonomia administrativa da ''Capital Nacional do Carvão''.', 'RS', '4304358');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/03/2019', 'Aniversário de Ibiúna', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação político-administrativa do município de Ibiúna, ocorrida em 24 de março de 1857. A celebração é oficializada pela Lei Municipal nº 10, de 06 de maio de 1983, que fixa os feriados locais.', 'SP', '3519709');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/03/2019', 'Aniversário de Sertão Santana', 'MUNICIPAL', 'Feriado municipal que celebra o Dia do Município, em alusão à sua criação oficial pela Lei Estadual nº 9.595, publicada em 24 de março de 1992. A data é fixada como feriado local pela Lei Municipal nº 16/1993.', 'RS', '4320552');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/03/2019', 'Aniversário de Westfália', 'MUNICIPAL', 'Feriado municipal alusivo à emancipação política do município de Westfália, celebrando a vitória no plebiscito ocorrido em 24 de março de 1996, que garantiu sua independência em relação a Teutônia e Imigrante.', 'RS', '4323770');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/03/2019', 'Nascimento do Padre Cícero', 'MUNICIPAL', 'Feriado municipal em homenagem ao nascimento de Cícero Romão Batista, o Padre Cícero (1844-1934), figura central na fundação e na história religiosa de Juazeiro do Norte. Instituído pela Lei Municipal nº 335, de 26 de setembro de 1968.', 'CE', '2307304');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/03/2019', 'Anunciação do Senhor', 'MUNICIPAL', 'Anunciação do Senhor', 'RS', '4315503');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/03/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'GO', '5208806');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/03/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'MG', '3128402');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/03/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'PI', '2210409');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/03/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'PR', '4101606');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/03/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'RJ', '3305307');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/03/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'RN', '2400703');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/03/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'SC', '4203006');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/03/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'SE', '2805208');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/03/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'SP', '3517000');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/03/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'SP', '3523602');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/03/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'SP', '3528304');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/03/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'SP', '3532702');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/03/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'SP', '3556909');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/03/2019', 'Aniversário de Capela do Alto', 'MUNICIPAL', 'Celebração do aniversário de emancipação político-administrativa do município de Capela do Alto, instituída oficialmente pela Lei Municipal nº 80-A/1967.', 'SP', '3510302');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/03/2019', 'Aniversário de Ipuã', 'MUNICIPAL', 'Feriado municipal em celebração ao aniversário de fundação e instalação do município de Ipuã, ocorrida em 26 de março de 1949.', 'SP', '3521309');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/03/2019', 'Aniversário de Itaberaba', 'MUNICIPAL', 'Comemoração do aniversário de emancipação política de Itaberaba, ocorrida em 26 de março de 1877. O feriado é regido pela Lei Orgânica Municipal e pela Lei Municipal nº 1.711/2022.', 'BA', '2914703');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/03/2019', 'Aniversário de Santa Luzia', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de fundação do município de Santa Luzia, Maranhão, ocorrida em 26 de março de 1961.', 'MA', '2110005');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/03/2019', 'Aniversário de Santa Rita de Cássia', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de fundação e emancipação política do município, ocorrida em 26 de março de 1840, conforme disposições da Lei Orgânica Municipal.', 'BA', '2928406');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/03/2019', 'Aniversário de Santo Antônio do Jardim', 'MUNICIPAL', 'Feriado municipal que celebra o aniversário de fundação do município, instituído oficialmente pela Lei Municipal nº 16, de 16 de março de 1956.', 'SP', '3548104');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/03/2019', 'Aniversário de Terra Roxa', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de fundação do município de Terra Roxa, ocorrida em 26 de março de 1947, conforme estabelecido na legislação municipal vigente.', 'SP', '3554409');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/03/2019', 'Aniversário de Virgolândia', 'MUNICIPAL', 'Feriado municipal celebrando o aniversário de emancipação política e instalação do município de Virgolândia, ocorrida em 26 de março de 1953.', 'MG', '3171907');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/03/2019', 'Aniversário de Xangri-lá', 'MUNICIPAL', 'Feriado municipal comemorativo à emancipação político-administrativa do município de Xangri-lá, ocorrida em 26 de março de 1992.', 'RS', '4323804');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/03/2019', 'Aniversário do Município de Reserva', 'MUNICIPAL', 'Feriado municipal que celebra o aniversário de criação do município de Reserva, ocorrida em 26 de março de 1921. A data é ratificada pela Lei Municipal nº 63/1985.', 'PR', '4121703');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/03/2019', 'Dia da Emancipação de Carapicuíba', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação política de Carapicuíba, ocorrida em 1965. A data é fundamentada pelo Artigo 220 da Lei Orgânica do Município e decretos anuais de feriados.', 'SP', '3510609');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/03/2019', 'Dia de São Ludgero (Padroeiro)', 'MUNICIPAL', 'Feriado religioso municipal em honra ao padroeiro São Ludgero, conforme estabelecido pela Lei Municipal nº 50/1966 e ratificado pela Lei Complementar nº 342/2025.', 'SC', '4217006');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/03/2019', 'Dia de São Ludgero e Emancipação de Poá', 'MUNICIPAL', 'Feriado municipal que celebra conjuntamente o dia do padroeiro São Ludgero e o aniversário de Emancipação Político-Administrativa do Município, conforme a Lei Municipal nº 3.078/2005.', 'SP', '3539806');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/03/2019', 'Dia do Município de Uruoca', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação política de Uruoca, instituído em comemoração à criação do município em 26 de março de 1957.', 'CE', '2313906');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/03/2019', 'Emancipação Política de Campo Redondo', 'MUNICIPAL', 'Feriado municipal em celebração à emancipação política do município de Campo Redondo, ocorrida em 26 de março de 1963, desmembrando-se de Currais Novos.', 'RN', '2402105');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/03/2019', 'Emancipação de Riolândia', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação político-administrativa do município de Riolândia, instituído pela Lei Municipal nº 833/1986.', 'SP', '3544202');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('27/03/2019', 'Aniversário de Bento de Abreu', 'MUNICIPAL', 'Feriado municipal em celebração ao aniversário de fundação do município de Bento de Abreu, ocorrida em 27 de março de 1948.', 'SP', '3506201');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('27/03/2019', 'Aniversário de Itaitinga', 'MUNICIPAL', 'Celebração do aniversário de emancipação política de Itaitinga, oficializada em 27 de março de 1992 pela Lei Estadual nº 11.926, tornando-se feriado municipal oficial conforme legislação local.', 'CE', '2306256');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('27/03/2019', 'Aniversário de Itirapuã', 'MUNICIPAL', 'Comemoração do aniversário de emancipação de Itirapuã, ocorrida em 27 de março de 1948, estabelecida pela Lei Estadual nº 233/1948 e ratificada por decreto municipal.', 'SP', '3523701');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('27/03/2019', 'Aniversário de Mairiporã', 'MUNICIPAL', 'Comemoração do aniversário de emancipação político-administrativa do município de Mairiporã, ocorrida em 27 de março de 1889, sendo feriado municipal oficial de acordo com o calendário da prefeitura.', 'SP', '3528502');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('27/03/2019', 'Aniversário de Presidente Epitácio', 'MUNICIPAL', 'Feriado municipal em comemoração aos anos de emancipação política de Presidente Epitácio, ocorrida em 27 de março de 1949, conforme Decreto Municipal anual e legislação fundadora.', 'SP', '3541307');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('27/03/2019', 'Aniversário de São Geraldo', 'MUNICIPAL', 'Feriado municipal em celebração à emancipação político-administrativa de São Geraldo, ocorrida em 27 de março de 1949, conforme tradição histórica e legislação municipal vigente.', 'MG', '3161502');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('27/03/2019', 'Aniversário de União da Vitória', 'MUNICIPAL', 'Feriado municipal em celebração ao aniversário de fundação de União da Vitória (27 de março de 1890). O feriado é ratificado pela Lei Municipal nº 4.272/2013, que dispõe sobre os feriados civis e religiosos locais.', 'PR', '4128203');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('27/03/2019', 'Aniversário do Município', 'MUNICIPAL', 'Comemoração do aniversário de fundação de Caldas, ocorrida em 27 de março de 1813. A data celebra a criação da Freguesia de Nossa Senhora do Patrocínio do Rio Verde das Caldas, sendo um feriado civil e religioso tradicional na cidade.', 'MG', '3110301');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('27/03/2019', 'Emancipação Política de Fortim', 'MUNICIPAL', 'Feriado municipal em comemoração à emancipação política do município de Fortim, ocorrida em 27 de março de 1992, conforme estabelecido pela Lei Estadual nº 11.927.', 'CE', '2304459');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('27/03/2019', 'Emancipação Política de Touros', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação política de Touros, ocorrida em 27 de março de 1835. A data é oficialmente instituída como feriado pelo Artigo 284 da Lei Orgânica do Município de Touros.', 'RN', '2414407');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('27/03/2019', 'Sexta-feira das Dores', 'MUNICIPAL', 'Feriado religioso municipal observado em 2026 no dia 27 de março. Trata-se de um feriado móvel celebrado tradicionalmente na sexta-feira anterior ao Domingo de Ramos, em devoção a Nossa Senhora das Dores, conforme costume regional de Minas Gerais.', 'MG', '3115706');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/03/2019', 'Aniversário de Augusto Corrêa', 'MUNICIPAL', 'Celebração do aniversário de instalação do município, ocorrida em 28 de março de 1962. O município foi criado originalmente pela Lei Estadual nº 2.460/1961, desmembrando-se de Bragança.', 'PA', '1500909');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/03/2019', 'Aniversário de Embu-Guaçu', 'MUNICIPAL', 'Feriado municipal em celebração à emancipação político-administrativa de Embu-Guaçu, ocorrida em 28 de março de 1965, data de sua instalação oficial após o desmembramento de Itapecerica da Serra (Lei Estadual nº 8.092/1964).', 'SP', '3515103');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/03/2019', 'Aniversário de Guzolândia', 'MUNICIPAL', 'Comemora a instalação oficial do município de Guzolândia, ocorrida em 28 de março de 1965. A data marca a posse do primeiro prefeito e a concretização da autonomia política garantida pela Lei Estadual nº 8.092/1964.', 'SP', '3518909');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/03/2019', 'Aniversário de Juquitiba', 'MUNICIPAL', 'Feriado comemorativo da instalação do município de Juquitiba, realizada em 28 de março de 1965, após sua emancipação política de Itapecerica da Serra estabelecida pela Lei Estadual nº 8.092/1964.', 'SP', '3526209');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/03/2019', 'Aniversário de Queiroz', 'MUNICIPAL', 'Comemoração da instalação do município de Queiroz em 28 de março de 1965. A data celebra a autonomia conquistada no ano anterior através da Lei Estadual nº 8.092/1964.', 'SP', '3541802');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/03/2019', 'Aniversário de Uchoa', 'MUNICIPAL', 'Instituído pela Lei Municipal nº 3.909/2019, o feriado celebra a instalação oficial do município ocorrida em 28 de março de 1926, após a elevação do antigo distrito à categoria de cidade pela Lei Estadual nº 2.117/1925.', 'SP', '3555604');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/03/2019', 'Dia do Plebiscito (Emancipação de Charqueadas)', 'MUNICIPAL', 'Instituído pela Lei Municipal nº 010/1983, este feriado celebra o plebiscito realizado em 28 de março de 1982, no qual a população votou pela emancipação do município em relação a São Jerônimo, culminando na criação da cidade pela Lei Estadual nº 7.644.', 'RS', '4305355');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/03/2019', 'Dia do Plebiscito de Parobé', 'MUNICIPAL', 'Feriado municipal que recorda a realização do plebiscito de emancipação em 28 de março de 1982. A vitória nas urnas nesta data permitiu o desmembramento de Parobé do município de Taquara, processo consolidado pela Lei Estadual nº 7.646.', 'RS', '4314050');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/03/2019', 'Emancipação Política de Alto do Rodrigues', 'MUNICIPAL', 'Feriado municipal em comemoração à emancipação política de Alto do Rodrigues, ocorrida em 28 de março de 1963. A data celebra o desmembramento do município de Pendências, oficializado pela Lei Estadual nº 2.853/1963.', 'RN', '2400703');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/03/2019', 'Emancipação Política de Itaporanga d''Ajuda', 'MUNICIPAL', 'Data magna que celebra a elevação da antiga Vila de Itaporanga à categoria de Cidade em 28 de março de 1854, marco fundamental para a história e soberania administrativa do município sergipano.', 'SE', '2803203');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/03/2019', 'Emancipação Política de Muribeca', 'MUNICIPAL', 'Celebração da autonomia administrativa de Muribeca, elevada à categoria de cidade através do Decreto-Lei Estadual nº 69, de 28 de março de 1938.', 'SE', '2804300');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/03/2019', 'Emancipação Política de Rondinha', 'MUNICIPAL', 'Feriado municipal que celebra a autonomia política de Rondinha, conquistada em 28 de março de 1964, conforme os termos da Lei Estadual nº 4.700, marcando o desmembramento de Sarandi.', 'RS', '4316204');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/03/2019', 'Emancipação Política de Vila Valério', 'MUNICIPAL', 'Comemoração da emancipação político-administrativa do município, instituída pela Lei Municipal nº 065/1997. A data remete à Lei Estadual nº 4.892, de 28 de março de 1994, que criou oficialmente o município capixaba.', 'ES', '3205176');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('29/03/2019', 'Aniversário de Araioses', 'MUNICIPAL', 'Celebração solene da emancipação política de Araioses. O município foi elevado à categoria de cidade em 29 de março de 1938, por força do Decreto-Lei Estadual nº 45, marco histórico fundamental para a autonomia administrativa da localidade.', 'MA', '2100907');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('29/03/2019', 'Aniversário de Barão de Grajaú', 'MUNICIPAL', 'Celebração da emancipação política e administrativa do município de Barão de Grajaú. A localidade foi elevada à categoria de cidade em 29 de março de 1938 pelo Decreto-Lei nº 45, sendo esta a data oficial de seu aniversário, celebrada com feriado em todo o território municipal.', 'MA', '2101509');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('29/03/2019', 'Aniversário de Chapadinha', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação política e administrativa do município de Chapadinha, ocorrida em 29 de março de 1938. A data é oficialmente instituída pela Lei Municipal nº 1.319, de 23 de outubro de 2019, que consolida os feriados civis e religiosos locais.', 'MA', '2103208');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('29/03/2019', 'Aniversário de Loreto', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de Loreto. A cidade obteve sua emancipação política definitiva em 29 de março de 1938, sob a égide da Lei Estadual nº 45, que reorganizou a divisão territorial do Maranhão na época.', 'MA', '2106102');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('29/03/2019', 'Aniversário de Mirador', 'MUNICIPAL', 'Feriado municipal em celebração aos anos de emancipação política de Mirador. O status de cidade foi conferido em 29 de março de 1938 através do Decreto-Lei Estadual nº 45, consolidando sua trajetória como unidade administrativa autônoma no estado do Maranhão.', 'MA', '2106706');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('29/03/2019', 'Aniversário de Monte Sião', 'MUNICIPAL', 'Feriado municipal em celebração ao aniversário de fundação do município de Monte Sião, ocorrida em 29 de março de 1849. A data é reconhecida oficialmente pelo Tribunal de Justiça de Minas Gerais (TJMG) e pela legislação municipal como dia festivo para a comunidade local.', 'MG', '3143401');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('29/03/2019', 'Aniversário de Pirajuí', 'MUNICIPAL', 'Feriado municipal em celebração ao aniversário de Pirajuí. A data marca a emancipação política e administrativa do município, ocorrida em 29 de março de 1914, sendo um dia de comemorações cívicas estabelecido pela legislação local.', 'SP', '3538907');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('29/03/2019', 'Aniversário de Soledade', 'MUNICIPAL', 'Comemoração da emancipação política e administrativa do município de Soledade, ocorrida em 29 de março de 1875. O feriado municipal celebra a história e a autonomia do município, conhecido como a capital das pedras preciosas.', 'RS', '4320800');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('29/03/2019', 'Aniversário de São Bernardo', 'MUNICIPAL', 'Celebração do aniversário de emancipação político-administrativa do município de São Bernardo, ocorrida em 29 de março de 1938 (Decreto-Lei nº 45). O feriado é amparado por legislação municipal que resguarda a tradição cívica da data.', 'MA', '2110609');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('29/03/2019', 'Aniversário de Tutóia', 'MUNICIPAL', 'Feriado municipal instituído para celebrar a emancipação política de Tutóia, oficializada em 29 de março de 1938 por meio do Decreto-Lei Estadual nº 45. A data homenageia o desenvolvimento e a história da cidade como polo importante do litoral maranhense.', 'MA', '2112506');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('29/03/2019', 'Aniversário de Vargem Grande', 'MUNICIPAL', 'Comemoração do aniversário de emancipação política do município de Vargem Grande, ocorrida em 29 de março de 1938. A data consta no calendário oficial de feriados municipais, frequentemente ratificada por decretos anuais (como o Decreto nº 001/2024), celebrando a elevação do antigo distrito à categoria de cidade.', 'MA', '2112704');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('30/03/2019', 'Aniversário de Barreirinhas', 'MUNICIPAL', 'Comemora a elevação de Barreirinhas à categoria de cidade em 30 de março de 1938. É um feriado tradicional no município, frequentemente objeto de decretos de ponto facultativo ou feriado local.', 'MA', '2101707');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('30/03/2019', 'Aniversário de Campos Novos', 'MUNICIPAL', 'Feriado municipal que celebra a fundação e emancipação de Campos Novos em 30 de março de 1881. O feriado é fundamentado no Art. 211 da Lei Orgânica do Município.', 'SC', '4203600');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('30/03/2019', 'Aniversário de Capivari de Baixo', 'MUNICIPAL', 'Celebra a criação do município pela Lei Estadual nº 8.556 de 30 de março de 1992. O feriado municipal está previsto na Lei Ordinária nº 1.009/2005.', 'SC', '4203956');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('30/03/2019', 'Aniversário de Correntina', 'MUNICIPAL', 'Celebração do aniversário de emancipação política de Correntina. O feriado é ratificado por decretos anuais (como o Decreto nº 05/2023) e comemora a elevação do município ocorrida em 30 de março de 1938.', 'BA', '2909307');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('30/03/2019', 'Aniversário de Emancipação de Barrocas', 'MUNICIPAL', 'Celebra a criação definitiva do município de Barrocas pela Lei Estadual nº 7.620, de 30 de março de 2000. O feriado municipal é reiterado por decretos do executivo (como o Decreto nº 005/2021).', 'BA', '2903276');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('30/03/2019', 'Aniversário de Jambeiro', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário da cidade e Dia de Santo Amadeu. A data é regida pela Lei Municipal nº 615/1981, alterada pela Lei nº 1.496/2010.', 'SP', '3524907');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('30/03/2019', 'Aniversário de Orlândia', 'MUNICIPAL', 'Feriado municipal celebrando o aniversário de fundação de Orlândia e o dia de São Zózimo, conforme instituído pela Lei Municipal nº 3.588/2008. Celebra a instalação do município em 1910.', 'SP', '3534302');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('30/03/2019', 'Aniversário de Plácido de Castro', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação política do município de Plácido de Castro, estabelecido pela Lei Municipal nº 358/2008. A data celebra a autonomia administrativa conquistada em 1963.', 'AC', '1200385');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('30/03/2019', 'Aniversário de São Bento', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de fundação e emancipação política da cidade de São Bento, no Maranhão. A data é confirmada por decretos municipais de feriados anuais.', 'MA', '2110500');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('30/03/2019', 'Aniversário de São Martinho', 'MUNICIPAL', 'Feriado municipal comemorativo da emancipação política do município de São Martinho (RS), ocorrida em 30 de março de 1963. A data é celebrada anualmente pela comunidade local.', 'RS', '4319109');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('30/03/2019', 'Aniversário de Vargem Bonita', 'MUNICIPAL', 'Feriado municipal instituído pela Lei nº 628/2005 para celebrar a autonomia política de Vargem Bonita, ocorrida em 30 de março de 1992, data de sua instalação administrativa.', 'SC', '4219176');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('30/03/2019', 'Emancipação Política de Ipojuca', 'MUNICIPAL', 'Data festiva que celebra a emancipação política e administrativa do município de Ipojuca, ocorrida em 1846. O feriado é consolidado por legislações como a Lei Municipal nº 1.095/1995.', 'PE', '2607208');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('30/03/2019', 'Emancipação Política de São Domingos do Norte', 'MUNICIPAL', 'Feriado municipal que celebra a autonomia administrativa do município, estabelecida pela Lei Municipal nº 775/2014. A data marca o desmembramento ocorrido em 30 de março de 1990.', 'ES', '3204658');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('30/03/2019', 'Emancipação de Luís Eduardo Magalhães', 'MUNICIPAL', 'Comemora a emancipação política e administrativa do município, criado pela Lei Estadual nº 7.619 de 30 de março de 2000. O feriado municipal é regido pela Lei Municipal nº 113/2003.', 'BA', '2919553');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('30/03/2019', 'Libertação dos Escravizados em Benevides', 'MUNICIPAL', 'Feriado municipal instituído pela Lei nº 194/1968 em homenagem à libertação pioneira dos escravizados no município, ocorrida em 30 de março de 1884 (quatro anos antes da Lei Áurea).', 'PA', '1501501');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('31/03/2019', 'Aniversário de Borá', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de Borá. A data celebra a emancipação político-administrativa do município, estabelecida em 31 de março de 1965.', 'SP', '3507209');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('31/03/2019', 'Aniversário de Codajás', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de Codajás, celebrando sua emancipação política e administrativa ocorrida em 31 de março de 1938, através do Decreto-Lei Estadual nº 68.', 'AM', '1301308');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('31/03/2019', 'Aniversário de Fartura', 'MUNICIPAL', 'Feriado municipal celebrando o aniversário de emancipação de Fartura, conforme ratificado pelo Decreto Municipal nº 4.359/2025. A data marca a elevação do povoado à categoria de município em 31 de março de 1891.', 'SP', '3515400');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('31/03/2019', 'Aniversário de Fonte Boa', 'MUNICIPAL', 'Celebração do aniversário de fundação do município de Fonte Boa, ocorrida em 31 de março de 1938, quando foi elevado à categoria de cidade. É um feriado tradicional no calendário local.', 'AM', '1301605');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('31/03/2019', 'Aniversário de Japorã', 'MUNICIPAL', 'Celebração da emancipação política do município de Japorã, criado pela Lei Estadual nº 1.261, de 31 de março de 1992. Embora algumas listas omitam, a data de fundação é tradicionalmente celebrada como feriado de aniversário.', 'MS', '5004809');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('31/03/2019', 'Aniversário de Rio Preto da Eva', 'MUNICIPAL', 'Feriado municipal que celebra o aniversário de Rio Preto da Eva. O município foi criado pela Emenda Constitucional nº 12, de 31 de março de 1981, desmembrado de Manaus e Itacoatiara.', 'AM', '1303569');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('31/03/2019', 'Emancipação Política de Remígio', 'MUNICIPAL', 'Feriado municipal que celebra o aniversário de emancipação política de Remígio, ocorrida em 31 de março de 1957, quando o município foi desmembrado de Alagoa Grande pela Lei Estadual nº 1.633.', 'PB', '2512705');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('31/03/2019', 'Emancipação Política de Sooretama', 'MUNICIPAL', 'Feriado municipal em comemoração à emancipação político-administrativa de Sooretama, instituído pela Lei Municipal nº 412/2005. A data remete à criação do município pela Lei Estadual nº 4.892, de 31 de março de 1994.', 'ES', '3205010');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('01/04/2019', 'Aniversário de São Miguel Arcanjo', 'MUNICIPAL', 'Feriado municipal em celebração à emancipação política de São Miguel Arcanjo, ocorrida em 1º de abril de 1889. A data é confirmada pelo calendário oficial do município (Portaria nº 7/2026) como dia de celebração da fundação da cidade.', 'SP', '3550209');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('01/04/2019', 'Emancipação Política de Arealva', 'MUNICIPAL', 'Feriado municipal que celebra o aniversário de emancipação político-administrativa de Arealva, instalada oficialmente em 1º de abril de 1949, conforme previsto na Lei Estadual nº 233 de 1948.', 'SP', '3503406');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('01/04/2019', 'Emancipação Política de Caatiba', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação política de Caatiba, ocorrida em 1º de abril de 1961, conforme a Lei Estadual nº 1.401. A data celebra o desmembramento do território em relação a Vitória da Conquista.', 'BA', '2904803');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('01/04/2019', 'Emancipação Política de Fátima', 'MUNICIPAL', 'Comemoração da emancipação política e administrativa do município de Fátima, instituída pela Lei Estadual nº 4.414 de 1º de abril de 1985, marcando a conquista de sua autonomia em relação a Cícero Dantas.', 'BA', '2910750');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('01/04/2019', 'Emancipação Política de Sumé', 'MUNICIPAL', 'Celebração do aniversário de emancipação política do município de Sumé, ocorrida em 1º de abril de 1951. É um feriado civil local tradicional que comemora a autonomia administrativa conquistada pela municipalidade.', 'PB', '2516300');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('01/04/2019', 'Emancipação Política de São Lourenço', 'MUNICIPAL', 'Feriado municipal em comemoração à emancipação político-administrativa de São Lourenço, ocorrida em 1º de abril de 1927, quando o município conquistou sua autonomia em relação a Pouso Alto.', 'MG', '3163706');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/04/2019', 'Aniversário de Alumínio', 'MUNICIPAL', 'Feriado municipal celebrando a emancipação político-administrativa de Alumínio, ocorrida em 2 de abril de 1993, quando o município se desmembrou de Mairinque.', 'SP', '3501152');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/04/2019', 'Aniversário de Capão Bonito', 'MUNICIPAL', 'Feriado municipal celebrando a fundação de Capão Bonito, ocorrida em 2 de abril de 1857. A data é marco histórico da formação da identidade do município.', 'SP', '3510203');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/04/2019', 'Aniversário de Carlópolis', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de fundação de Carlópolis, ocorrida em 2 de abril de 1907. Data dedicada às celebrações cívicas da cidade.', 'PR', '4104709');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/04/2019', 'Aniversário de Cotia', 'MUNICIPAL', 'Feriado municipal em celebração à elevação de Cotia à categoria de cidade, ocorrida em 2 de abril de 1856. A data é o marco oficial do aniversário do município.', 'SP', '3513009');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/04/2019', 'Aniversário de Dobrada', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação político-administrativa de Dobrada, ocorrida em 2 de abril.', 'SP', '3514007');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/04/2019', 'Aniversário de Jacarezinho', 'MUNICIPAL', 'Feriado municipal em comemoração à emancipação política do município de Jacarezinho, ocorrida em 2 de abril de 1900. A data celebra a fundação e o desenvolvimento histórico da cidade.', 'PR', '4111803');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/04/2019', 'Aniversário de Macaubal', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de fundação e emancipação de Macaubal, celebrado anualmente em 2 de abril.', 'SP', '3528106');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/04/2019', 'Aniversário de Narandiba', 'MUNICIPAL', 'Feriado municipal celebrando a fundação e emancipação política de Narandiba, ocorrida em 2 de abril.', 'SP', '3532207');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/04/2019', 'Aniversário de Pacaembu', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação do município de Pacaembu, fundado em 2 de abril de 1949.', 'SP', '3534906');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/04/2019', 'Aniversário de Pongaí', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de fundação e emancipação de Pongaí, celebrado anualmente no dia 2 de abril.', 'SP', '3540101');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/04/2019', 'Aniversário de Poço Fundo', 'MUNICIPAL', 'Feriado municipal em celebração à emancipação política de Poço Fundo, ocorrida em 2 de abril de 1870. A data homenageia a história e autonomia do município.', 'MG', '3151701');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/04/2019', 'Aniversário de Vinhedo', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação político-administrativa de Vinhedo, ocorrida em 2 de abril de 1949. A data recorda o momento em que o então distrito de Rocinha tornou-se município.', 'SP', '3556701');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/04/2019', 'Dia de Adoração', 'MUNICIPAL', 'Feriado municipal instituído pela Lei nº 2.378/2003, celebrado anualmente na Quinta-feira Santa. Trata-se de uma data de tradição religiosa dedicada à adoração e reflexão que antecede a Sexta-feira da Paixão.', 'RJ', '3302007');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/04/2019', 'Dia de Adoração', 'MUNICIPAL', 'Feriado municipal estabelecido pela Lei Municipal nº 151/2001 (Art. 1º, inciso IV), celebrado na Quinta-feira Santa. É uma data destinada a atividades religiosas de adoração no calendário oficial do município.', 'RJ', '3305554');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/04/2019', 'Dia de São Francisco de Paula', 'MUNICIPAL', 'Feriado religioso em honra ao padroeiro do município, São Francisco de Paula. A celebração litúrgica do santo ocorre em 2 de abril, conforme tradição local e legislação municipal de feriados religiosos.', 'RJ', '3304755');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/04/2019', 'Dia de São Francisco de Paula', 'MUNICIPAL', 'Feriado municipal dedicado ao padroeiro da cidade, São Francisco de Paula. A data é celebrada com eventos religiosos e cívicos em homenagem ao santo que dá nome ao município.', 'RS', '4318200');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/04/2019', 'Emancipação Político-Administrativa de Suzano', 'MUNICIPAL', 'conforme Lei Municipal nº 782 de 25/05/1967', 'SP', '3552502');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('03/04/2019', 'Emancipação Política de Belford Roxo', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação do município de Belford Roxo, ocorrida em 3 de abril de 1990. A data celebra a autonomia administrativa da cidade, desmembrada de Nova Iguaçu, conforme previsto na Lei Orgânica Municipal.', 'RJ', '3300456');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('03/04/2019', 'Emancipação Política de Entre Rios', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação política da cidade de Entre Rios, Bahia, ocorrida em 3 de abril de 1872. A data comemora a transição da antiga Vila de Nossa Senhora de Entre Rios para a categoria de cidade, marco fundamental da história local.', 'BA', '2910503');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('03/04/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'BA', '2919702');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('03/04/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'RS', '4314209');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('03/04/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'SC', '4201406');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('03/04/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'SC', '4217501');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('03/04/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'SP', '3511508');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('03/04/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'SP', '3539608');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('03/04/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'SP', '3549508');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('03/04/2019', 'Sexta-feira da Paixão', 'MUNICIPAL', 'Feriado religioso municipal móvel em observância à Paixão de Cristo. Jacareí estabelece seus feriados religiosos em conformidade com a Lei Federal nº 9.093/1995 e a Lei Municipal nº 6.068/2017, que consolida a legislação sobre feriados e datas comemorativas no município.', 'SP', '3524402');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('04/04/2019', 'Aniversário de Alfredo Marcondes', 'MUNICIPAL', 'Celebração do aniversário de fundação e emancipação de Alfredo Marcondes, ocorrida em 4 de abril de 1944. Data de grande relevância cívica para o município.', 'SP', '3500808');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('04/04/2019', 'Aniversário de Aquidabã', 'MUNICIPAL', 'Feriado em celebração à elevação do município de Aquidabã à categoria de cidade, fato ocorrido em 4 de abril de 1882 pela Lei nº 11.', 'SE', '2800209');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('04/04/2019', 'Aniversário de Aramina', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação político-administrativa de Aramina, ocorrida em 4 de abril de 1964, conforme a Lei Estadual nº 8.092.', 'SP', '3503000');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('04/04/2019', 'Aniversário de Coremas', 'MUNICIPAL', 'Celebração da emancipação política do município de Coremas, oficializada pela Lei nº 1.018 em 4 de abril de 1954.', 'PB', '2504801');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('04/04/2019', 'Aniversário de Cruzália', 'MUNICIPAL', 'Comemoração do aniversário de emancipação do município de Cruzália, oficializada em 4 de abril de 1965, marcando a autonomia administrativa da cidade.', 'SP', '3513306');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('04/04/2019', 'Aniversário de Governador Dix-Sept Rosado', 'MUNICIPAL', 'Feriado destinado à comemoração da emancipação política e fundação do município, estabelecida pela Lei nº 2.854 de 4 de abril de 1963.', 'RN', '2404309');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('04/04/2019', 'Aniversário de Inocência', 'MUNICIPAL', 'Feriado municipal que celebra a criação do município de Inocência, ocorrida em 4 de abril de 1959, através da Lei Estadual nº 1.201.', 'MS', '5004403');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('04/04/2019', 'Aniversário de Itajobi', 'MUNICIPAL', 'Celebração do aniversário do município de Itajobi, criado pela Lei Estadual nº 1.585 de 4 de abril de 1918.', 'SP', '3521903');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('04/04/2019', 'Aniversário de Jaci', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário da emancipação política e administrativa de Jaci, ocorrida em 4 de abril de 1959, conforme estabelecido pela Lei Estadual nº 5.285.', 'SP', '3524501');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('04/04/2019', 'Aniversário de Marília', 'MUNICIPAL', 'Feriado em celebração ao aniversário de fundação do município de Marília, estabelecido em 4 de abril de 1929. A data é um marco histórico para a ''Cidade Menina'', sendo regulamentada por legislação municipal.', 'SP', '3529005');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('04/04/2019', 'Aniversário de Presidente Kennedy', 'MUNICIPAL', 'Comemoração da emancipação política de Presidente Kennedy, ocorrida em 4 de abril de 1964, conforme a Lei Estadual nº 1.918. É a principal data cívica do município.', 'ES', '3204302');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('04/04/2019', 'Aniversário de Santo Antônio do Tauá', 'MUNICIPAL', 'Feriado municipal em honra ao aniversário da cidade de Santo Antônio do Tauá, emancipada em 4 de abril de 1955 por intermédio da Lei Estadual nº 1.127.', 'PA', '1507003');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('04/04/2019', 'Aniversário de São Gabriel', 'MUNICIPAL', 'Celebração solene do aniversário do município de São Gabriel, conhecido como ''Terra dos Marechais''. A data marca a elevação da localidade à categoria de cidade em 4 de abril de 1846.', 'RS', '4318309');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('04/04/2019', 'Aniversário de Viradouro', 'MUNICIPAL', 'Feriado municipal comemorativo ao aniversário de Viradouro, fundado em 4 de abril de 1916, conforme a Lei Estadual nº 1.496.', 'SP', '3556800');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('04/04/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'GO', '5200134');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/04/2019', 'Aniversário de Araquari', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação política de Araquari, ocorrida em 5 de abril de 1876, conforme a Lei Provincial nº 801.', 'SC', '4201307');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/04/2019', 'Aniversário de Caetité', 'MUNICIPAL', 'Celebração do aniversário de Caetité, remetendo ao dia 5 de abril de 1810, data em que o povoado foi elevado à categoria de Vila (Vila Nova do Príncipe e Santana de Caetité) por decreto real.', 'BA', '2905206');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/04/2019', 'Aniversário de Camboriú', 'MUNICIPAL', 'Comemoração do aniversário de emancipação político-administrativa de Camboriú, ocorrida em 5 de abril de 1884, através da Lei Provincial nº 1.076.', 'SC', '4203204');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/04/2019', 'Aniversário de Coração de Jesus', 'MUNICIPAL', 'Comemoração da emancipação política do município de Coração de Jesus, ocorrida em 5 de abril de 1912, data em que conquistou sua autonomia administrativa.', 'MG', '3118809');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/04/2019', 'Aniversário de Coronel Macedo', 'MUNICIPAL', 'Celebração do aniversário de emancipação político-administrativa de Coronel Macedo, ocorrida em 5 de abril de 1964, quando se tornou município autônomo.', 'SP', '3512605');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/04/2019', 'Aniversário de Godoy Moreira', 'MUNICIPAL', 'Comemoração da criação do município de Godoy Moreira, estabelecida pela Lei Estadual nº 9.231 de 5 de abril de 1990, desmembrando-se de São João do Ivaí.', 'PR', '4108551');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/04/2019', 'Aniversário de Marabá', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de fundação de Marabá. O município foi oficialmente criado pela Lei Estadual nº 1.116, de 5 de abril de 1913.', 'PA', '1504208');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/04/2019', 'Aniversário de Mococa', 'MUNICIPAL', 'Comemoração da fundação do município de Mococa, ocorrida em 5 de abril de 1856. A data é um tradicional feriado municipal que celebra as raízes históricas da cidade.', 'SP', '3530508');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/04/2019', 'Aniversário de Rio Pardo de Minas', 'MUNICIPAL', 'Celebração do aniversário do município de Rio Pardo de Minas, que foi elevado à categoria de cidade em 5 de abril de 1871.', 'MG', '3155603');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/04/2019', 'Aniversário de Timbiras', 'MUNICIPAL', 'Celebração da emancipação política do município de Timbiras, elevada à categoria de cidade em 5 de abril de 1920, por força da Lei Estadual nº 876.', 'MA', '2112100');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/04/2019', 'Dia de São Vicente Ferrer', 'MUNICIPAL', 'Feriado municipal em honra a São Vicente Ferrer, padroeiro da cidade de Potengi. A data celebra a festa litúrgica do santo, figura central da religiosidade local.', 'CE', '2311207');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/04/2019', 'Dia de São Vicente Ferrer', 'MUNICIPAL', 'Feriado municipal dedicado ao padroeiro da cidade, São Vicente Ferrer. A data é celebrada anualmente em 5 de abril, dia da festa litúrgica do santo na Igreja Católica.', 'PE', '2613800');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/04/2019', 'Dia de São Vicente Ferrer', 'MUNICIPAL', 'Feriado religioso em homenagem ao padroeiro do município de São Vicente do Sul, São Vicente Ferrer, celebrado no dia 5 de abril conforme o calendário litúrgico.', 'RS', '4319802');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/04/2019', 'Emancipação Política de Adustina', 'MUNICIPAL', 'Celebração da emancipação política de Adustina, ocorrida em 5 de abril de 1989, conforme estabelecido pela Lei Estadual nº 5.005, quando se desmembrou de Paripiranga.', 'BA', '2900355');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/04/2019', 'Emancipação Política de Anagé', 'MUNICIPAL', 'Comemoração da emancipação política do município de Anagé, que ocorreu em 5 de abril de 1962, após desmembramento do município de Vitória da Conquista, conforme a Lei Estadual nº 1.657.', 'BA', '2901205');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/04/2019', 'Emancipação Política de Planalto', 'MUNICIPAL', 'Celebração da emancipação política de Planalto, ocorrida em 5 de abril de 1962. O município foi criado através da Lei Estadual nº 1.656, desmembrando-se de Vitória da Conquista.', 'BA', '2925006');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('05/04/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'RS', '4313409');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('06/04/2019', 'Aniversário de Emancipação Política', 'MUNICIPAL', 'Feriado em celebração à emancipação política de Boquira, que ocorreu em 6 de abril de 1962 através da Lei Estadual nº 1.663, resultando no desmembramento do território do município de Macaúbas.', 'BA', '2904100');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('06/04/2019', 'Aniversário de Ibiraci', 'MUNICIPAL', 'Comemoração da instalação oficial do município de Ibiraci, ocorrida em 6 de abril de 1924. A criação do município foi autorizada pela Lei Estadual de Minas Gerais nº 843, de 7 de setembro de 1923.', 'MG', '3129707');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('06/04/2019', 'Aniversário de Rosário', 'MUNICIPAL', 'Feriado municipal em celebração à fundação do município de Rosário, ocorrida em 6 de abril de 1915. A data comemorativa e o reconhecimento da fundação são amparados pela Lei Municipal nº 191/2015.', 'MA', '2109601');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('06/04/2019', 'Aniversário do Município', 'MUNICIPAL', 'Aniversário da Cidade de Pedra Bela, conforme lei Nº 03, de 15 de abril de 1983', 'SP', '3536802');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('06/04/2019', 'Dia da Criação da Paróquia de Cruz', 'MUNICIPAL', 'Feriado religioso que comemora a data de criação da Paróquia de Nossa Senhora da Conceição de Cruz. A data foi estabelecida como feriado municipal por meio da Lei Municipal nº 20, de 10 de março de 1987.', 'CE', '2304251');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('07/04/2019', 'Aniversário de Araçoiaba da Serra', 'MUNICIPAL', 'Comemoração do aniversário de Araçoiaba da Serra, celebrando a data de 7 de abril de 1857, quando a localidade conquistou sua emancipação política e administrativa.', 'SP', '3502903');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('07/04/2019', 'Aniversário de Ascurra', 'MUNICIPAL', 'Celebração do aniversário do município de Ascurra. A data de 7 de abril marca a instalação oficial do município em 1963, criado pela Lei Estadual nº 887. O feriado municipal é ratificado pela Lei Municipal nº 915/2002.', 'SC', '4201703');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('07/04/2019', 'Aniversário de Dores do Rio Preto', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação política de Dores do Rio Preto. O município foi criado pela Lei Estadual nº 1.914, de 30 de dezembro de 1963, e oficialmente instalado em 7 de abril de 1964.', 'ES', '3202009');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('07/04/2019', 'Aniversário de Jeriquara', 'MUNICIPAL', 'Feriado municipal comemorativo ao aniversário de Jeriquara. A data celebra a emancipação política e administrativa do município, cuja instalação oficial ocorreu em 7 de abril de 1964.', 'SP', '3525409');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('07/04/2019', 'Aniversário de José de Freitas', 'MUNICIPAL', 'Feriado que celebra o aniversário da cidade de José de Freitas. A data remete a 7 de abril de 1878, quando a antiga Vila do Livramento foi elevada à categoria de cidade.', 'PI', '2205508');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('07/04/2019', 'Aniversário de Palmeira', 'MUNICIPAL', 'Comemoração do aniversário de fundação do município de Palmeira. A data celebra a elevação da localidade à categoria de Freguesia em 7 de abril de 1819, marco inicial de sua autonomia administrativa.', 'PR', '4117701');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('07/04/2019', 'Aniversário de Patrocínio', 'MUNICIPAL', 'Feriado municipal celebrando o aniversário de Patrocínio. A data remete à elevação do arraial à categoria de Vila e Município pela Lei Provincial nº 211, de 7 de abril de 1842, desmembrando-se de Araxá.', 'MG', '3148103');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('07/04/2019', 'Aniversário de Ribeirão Corrente', 'MUNICIPAL', 'Celebração do aniversário de Ribeirão Corrente. O município foi instalado oficialmente em 7 de abril de 1965, após sua criação ter sido autorizada pela Lei Estadual nº 8.092, de 28 de fevereiro de 1964.', 'SP', '3543105');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('07/04/2019', 'Aniversário de Torrinha', 'MUNICIPAL', 'Comemoração do aniversário do município de Torrinha. A cidade obteve sua emancipação política em 7 de abril de 1922, através da Lei Estadual nº 1.841, desmembrando-se de Brotas.', 'SP', '3554706');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('07/04/2019', 'Aniversário de Óleo', 'MUNICIPAL', 'Feriado municipal celebrando o aniversário de Óleo. A data marca a emancipação política do município ocorrida em 7 de abril de 1917, quando foi desmembrado de Santa Cruz do Rio Pardo.', 'SP', '3533809');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('07/04/2019', 'Emancipação Política de Araci', 'MUNICIPAL', 'Feriado que celebra a emancipação de Araci. Embora tenha tido várias etapas de autonomia, a data de 7 de abril é tradicionalmente celebrada em memória à sua emancipação política definitiva em relação a Serrinha.', 'BA', '2902104');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('07/04/2019', 'Emancipação Política de Cafarnaum', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação política de Cafarnaum, ocorrida em 7 de abril de 1963. O município foi criado pela Lei Estadual nº 1.637, de 16 de julho de 1962, desmembrando-se de Morro do Chapéu.', 'BA', '2905305');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('07/04/2019', 'Emancipação Política de Dom Basílio', 'MUNICIPAL', 'Comemoração da emancipação política e administrativa do município de Dom Basílio. A cidade foi oficialmente instalada em 7 de abril de 1963, após ser desmembrada de Livramento de Nossa Senhora pela Lei Estadual nº 1.657/1962.', 'BA', '2910107');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('07/04/2019', 'Emancipação Política de Galvão', 'MUNICIPAL', 'Feriado municipal referente ao aniversário de emancipação de Galvão. O município foi criado pela Lei Estadual nº 877, de 26 de março de 1963, e instalado oficialmente em 7 de abril de 1963.', 'SC', '4205605');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('07/04/2019', 'Emancipação Política de Malhada', 'MUNICIPAL', 'Celebração da emancipação política e administrativa do município de Malhada, instalado em 7 de abril de 1963. A autonomia foi garantida pela Lei Estadual nº 1.642, de 16 de março de 1962, desmembrando-se de Carinhanha.', 'BA', '2920205');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('07/04/2019', 'Emancipação Política de Pindaí', 'MUNICIPAL', 'Feriado municipal em celebração à instalação oficial do município de Pindaí, ocorrida em 7 de abril de 1963. O território foi emancipado do município de Urandi através da Lei Estadual nº 1.624, de 14 de maio de 1962.', 'BA', '2924504');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('07/04/2019', 'Emancipação Política de Sebastião Laranjeiras', 'MUNICIPAL', 'Feriado municipal que marca a instalação oficial de Sebastião Laranjeiras em 7 de abril de 1963. O município foi criado pela Lei Estadual nº 1.616 de 1962, com território desmembrado de Palmas de Monte Alto.', 'BA', '2930006');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('07/04/2019', 'Emancipação Política de São Domingos', 'MUNICIPAL', 'Feriado municipal em São Domingos (SC) celebrando a emancipação política e administrativa. O município foi criado pela Lei Estadual nº 875 de 1963 e instalado oficialmente em 7 de abril do mesmo ano.', 'SC', '4216107');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('07/04/2019', 'Emancipação Política de São Domingos', 'MUNICIPAL', 'Feriado em comemoração à emancipação política de São Domingos (SE), ocorrida em 7 de abril de 1963, data em que o município conquistou autonomia em relação a Campo do Brito.', 'SE', '2806800');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('08/04/2019', 'Aniversário de Amparo', 'MUNICIPAL', 'Comemoração da fundação do município de Amparo, cuja data oficial de 8 de abril de 1829 remete à elevação do povoado à condição de Capela Curada. Feriado estabelecido pela Lei Municipal nº 612 de 1968.', 'SP', '3501905');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('08/04/2019', 'Aniversário de Caém', 'MUNICIPAL', 'Feriado municipal em comemoração à emancipação política de Caém, ocorrida em 8 de abril de 1963. A data integra o calendário oficial de feriados do município (Decreto Municipal nº 01/2026).', 'BA', '2905107');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('08/04/2019', 'Aniversário de Coroatá', 'MUNICIPAL', 'Comemoração da emancipação política de Coroatá, elevada à categoria de cidade pela Lei Estadual nº 924 de 8 de abril de 1920. É a data magna municipal.', 'MA', '2103604');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('08/04/2019', 'Aniversário de Cuiabá', 'MUNICIPAL', 'conforme Lei Municipal nº 1.077 de 02 de abril de 1968', 'MT', '5103403');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('08/04/2019', 'Aniversário de Nioaque', 'MUNICIPAL', 'Feriado municipal que celebra a fundação e emancipação política de Nioaque, ocorrida em 8 de abril de 1848. É uma das cidades mais antigas de Mato Grosso do Sul.', 'MS', '5005806');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('08/04/2019', 'Aniversário de Quaraí', 'MUNICIPAL', 'Comemoração do aniversário de emancipação política e administrativa do município de Quaraí, ocorrida em 8 de abril de 1875, quando foi desmembrado de Alegrete.', 'RS', '4315305');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('08/04/2019', 'Aniversário de Santo André', 'MUNICIPAL', 'Feriado municipal que celebra o aniversário de fundação da Vila de Santo André da Borda do Campo, ocorrida em 8 de abril de 1553 por João Ramalho. A data é oficializada como feriado pela Lei Municipal nº 4.148 de 11 de maio de 1973.', 'SP', '3547809');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('08/04/2019', 'Dia de Padre Paolino Maria Baldassari', 'MUNICIPAL', 'Feriado municipal instituído pela Lei Municipal nº 581/2017 (e anteriormente pela Lei nº 575/2017) em homenagem à memória de Padre Paolino Maria Baldassari, missionário que dedicou décadas à saúde e assistência social na região, falecido nesta data em 2016.', 'AC', '1200500');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('08/04/2019', 'Emancipação Política de Timbaúba', 'MUNICIPAL', 'Feriado municipal comemorativo da emancipação política e administrativa de Timbaúba, ocorrida em 8 de abril de 1879, quando se desmembrou do município de Nazaré da Mata.', 'PE', '2615300');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('09/04/2019', 'Aniversário de Conchal', 'MUNICIPAL', 'Feriado municipal em comemoração à emancipação político-administrativa do município de Conchal, ocorrida em 9 de abril de 1949. A autonomia foi estabelecida pela Lei Estadual nº 233, de 24 de dezembro de 1948.', 'SP', '3512209');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('09/04/2019', 'Aniversário de Cubatão', 'MUNICIPAL', 'Feriado municipal que marca a emancipação política de Cubatão, ocorrida em 9 de abril de 1949, após a promulgação da Lei Estadual nº 233 de 1948, que elevou o antigo distrito à categoria de município.', 'SP', '3513504');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('09/04/2019', 'Aniversário de Ecoporanga', 'MUNICIPAL', 'Comemoração da emancipação político-administrativa do município de Ecoporanga, ocorrida em 9 de abril de 1944. A data é feriado municipal conforme a legislação local.', 'ES', '3202108');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('09/04/2019', 'Aniversário de Itariri', 'MUNICIPAL', 'Feriado municipal em celebração à emancipação de Itariri em 9 de abril de 1949. O município foi criado pela Lei Estadual nº 233, de 24 de dezembro de 1948, desmembrando-se de Itanhaém.', 'SP', '3523305');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('09/04/2019', 'Aniversário de Juruti', 'MUNICIPAL', 'Feriado municipal que celebra a fundação e elevação de Juruti à categoria de Vila em 9 de abril de 1883, através da Lei Provincial nº 1.104. É o principal marco histórico e político do município.', 'PA', '1503903');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('09/04/2019', 'Aniversário de Pedro de Toledo', 'MUNICIPAL', 'Celebração da emancipação político-administrativa de Pedro de Toledo em 9 de abril de 1949. O feriado é instituído em virtude da Lei Estadual nº 233/1948 que oficializou a criação do município.', 'SP', '3537206');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('09/04/2019', 'Aniversário de Pirapozinho', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação do município de Pirapozinho, ocorrida em 9 de abril de 1949, desmembrando-se de Presidente Prudente com base na Lei Estadual nº 233/1948.', 'SP', '3539202');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('09/04/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'MG', '3114600');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('09/04/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'MG', '3155801');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/04/2019', 'Aniversário de Areal', 'MUNICIPAL', 'Comemoração da emancipação política do município de Areal, oficializada pela Lei Estadual nº 1.988 em 10 de abril de 1992, marcando sua independência administrativa de Três Rios.', 'RJ', '3300225');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/04/2019', 'Aniversário de Ariranha', 'MUNICIPAL', 'Feriado municipal em comemoração à instalação do município de Ariranha em 10 de abril de 1919, após ter sido criado pela Lei Estadual nº 1.617 de 30 de dezembro de 1918.', 'SP', '3503703');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/04/2019', 'Aniversário de Artur Nogueira', 'MUNICIPAL', 'Feriado municipal em celebração ao aniversário de Artur Nogueira. A cidade teve sua emancipação político-administrativa oficializada com a instalação da prefeitura em 10 de abril de 1949, amparada pela Lei Estadual nº 233/1948.', 'SP', '3503802');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/04/2019', 'Aniversário de Atílio Vivacqua', 'MUNICIPAL', 'Comemoração da emancipação política do município de Atílio Vivacqua. A instalação oficial da nova unidade administrativa ocorreu em 10 de abril de 1964, após o desmembramento de Cachoeiro de Itapemirim via Lei Estadual nº 1.918 de 30 de dezembro de 1963.', 'ES', '3200706');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/04/2019', 'Aniversário de Baixo Guandu', 'MUNICIPAL', 'Celebração da autonomia política e administrativa do município de Baixo Guandu, estabelecida pelo Decreto Estadual nº 5.951 de 10 de abril de 1935, que oficializou sua emancipação do território de Colatina.', 'ES', '3200805');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/04/2019', 'Aniversário de Colinas', 'MUNICIPAL', 'Feriado municipal que celebra a elevação da antiga Vila de Picos à categoria de cidade com a denominação de Colinas, fato ocorrido em 10 de abril de 1891 por ato solene do governo estadual.', 'MA', '2103505');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/04/2019', 'Aniversário de Gameleira', 'MUNICIPAL', 'Feriado municipal em comemoração à data de fundação de Gameleira, que remonta à elevação da povoação à categoria de Vila e sede de distrito em 10 de abril de 1872.', 'PE', '2605905');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/04/2019', 'Aniversário de Guajará-Mirim', 'MUNICIPAL', 'Comemoração da fundação do município de Guajará-Mirim, criado pelo Decreto nº 1.656 de 10 de abril de 1929, assinado pelo então Governador do Estado do Amazonas, Ephigênio de Salles.', 'RO', '1100106');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/04/2019', 'Aniversário de Itatiba do Sul', 'MUNICIPAL', 'Feriado municipal que celebra a instalação administrativa de Itatiba do Sul em 10 de abril de 1954, após sua criação oficial pela Lei Estadual nº 2.354 de 31 de março de 1954.', 'RS', '4310702');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/04/2019', 'Aniversário de Juquiá', 'MUNICIPAL', 'Feriado municipal em celebração à emancipação político-administrativa de Juquiá. O município foi oficialmente instalado em 10 de abril de 1949, após ser desmembrado de Iguape nos termos da Lei Estadual nº 233 de 24 de dezembro de 1948.', 'SP', '3526100');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/04/2019', 'Aniversário de Parnarama', 'MUNICIPAL', 'Feriado em comemoração à instalação do município de Parnarama, ocorrida em 10 de abril de 1949, consolidando a autonomia prevista na Lei Estadual nº 269 de 31 de dezembro de 1948.', 'MA', '2107803');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/04/2019', 'Aniversário de Pontes Gestal', 'MUNICIPAL', 'Feriado em celebração à instalação do município de Pontes Gestal, ocorrida em 10 de abril de 1949, após sua criação pela Lei Estadual nº 233 de 1948 que desmembrou o território de Cardoso.', 'SP', '3540309');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/04/2019', 'Aniversário de Rio das Ostras', 'MUNICIPAL', 'Celebração da emancipação político-administrativa de Rio das Ostras, ocorrida em 10 de abril de 1992 através da Lei Estadual nº 1.984, data em que o município se desmembrou de Casimiro de Abreu.', 'RJ', '3304524');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/04/2019', 'Aniversário de Serrana', 'MUNICIPAL', 'Celebração da emancipação político-administrativa de Serrana. A instalação solene do município ocorreu em 10 de abril de 1949, conforme autorização legal da Lei Estadual nº 233 de 1948.', 'SP', '3551504');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/04/2019', 'Aniversário de São Félix do Xingu', 'MUNICIPAL', 'Celebração da instalação político-administrativa de São Félix do Xingu, ocorrida em 10 de abril de 1962. O município havia sido criado pela Lei Estadual nº 2.460 em 29 de dezembro de 1961.', 'PA', '1507300');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('10/04/2019', 'Aniversário de Álvares Florence', 'MUNICIPAL', 'Celebração do aniversário de Álvares Florence, marcando a data de instalação do município em 10 de abril de 1949, fundamentada pela Lei Estadual nº 233 de 24 de dezembro de 1948.', 'SP', '3501202');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/04/2019', 'Aniversário de Cafelândia', 'MUNICIPAL', 'Feriado municipal que celebra a instalação oficial do município de Cafelândia, ocorrida em 11 de abril de 1925, após sua criação pela Lei Estadual nº 2.033 de 1924.', 'SP', '3508801');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/04/2019', 'Aniversário de Coxim', 'MUNICIPAL', 'Feriado municipal em celebração ao aniversário de fundação e emancipação político-administrativa de Coxim. O município foi elevado à categoria de cidade em 11 de abril de 1898.', 'MS', '5003306');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/04/2019', 'Aniversário de Erebango', 'MUNICIPAL', 'Celebração da emancipação político-administrativa de Erebango. O município foi criado através da Lei Estadual nº 8.561, de 11 de abril de 1988, desmembrando-se de Getúlio Vargas.', 'RS', '4306973');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/04/2019', 'Aniversário de Guaraí', 'MUNICIPAL', 'Comemoração da emancipação política do município de Guaraí, ocorrida em 11 de abril de 1968, através da Lei Estadual nº 7.177 (do estado de Goiás, antes da criação do Tocantins).', 'TO', '1709302');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/04/2019', 'Aniversário de Papanduva', 'MUNICIPAL', 'Feriado municipal destinado à celebração da emancipação político-administrativa do município de Papanduva, ocorrida em 11 de abril de 1954, por força da Lei Estadual nº 133.', 'SC', '4212205');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/04/2019', 'Emancipação Política de Acari', 'MUNICIPAL', 'Comemoração oficial da emancipação política do município de Acari, ocorrida em 11 de abril de 1833, quando se desmembrou de Caicó. A data é celebrada anualmente como feriado municipal conforme a Lei Orgânica do Município.', 'RN', '2400109');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/04/2019', 'Emancipação Política de Tuparetama', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação política de Tuparetama, oficializada pela Lei Estadual nº 4.945, de 11 de abril de 1962, quando o município conquistou sua autonomia em relação a São José do Egito.', 'PE', '2615904');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/04/2019', 'Emancipação de Ernestina', 'MUNICIPAL', 'Data festiva que celebra a emancipação política de Ernestina. O município foi criado pela Lei Estadual nº 8.555, de 11 de abril de 1988, data em que se celebra o feriado municipal.', 'RS', '4307054');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('11/04/2019', 'Emancipação de Nova Bréscia', 'MUNICIPAL', 'Feriado municipal em comemoração à emancipação política de Nova Bréscia, instituída pela Lei Estadual nº 4.734, de 11 de abril de 1964.', 'RS', '4313003');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('12/04/2019', 'Aniversário de Erval Seco', 'MUNICIPAL', 'Feriado municipal que comemora a emancipação política de Erval Seco, oficializada pela Lei Estadual nº 4.475 em 12 de abril de 1963. A data celebra a autonomia administrativa do município perante o estado do Rio Grande do Sul.', 'RS', '4307302');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('12/04/2019', 'Aniversário de Porto Calvo', 'MUNICIPAL', 'Comemoração do aniversário de fundação e elevação política de Porto Calvo, um dos municípios mais históricos de Alagoas. A data remete a 12 de abril de 1636, quando a localidade foi elevada à categoria de vila com o nome de Bom Sucesso, sendo um marco fundamental da colonização da região norte do estado.', 'AL', '2707305');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('12/04/2019', 'Aniversário de São José do Piauí', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação política de São José do Piauí. A data celebra a autonomia do município e sua história de desenvolvimento social e administrativo desde sua criação oficial em 12 de abril de 1964.', 'PI', '2210201');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('12/04/2019', 'Elevação de Penedo à Categoria de Cidade', 'MUNICIPAL', 'Celebração do aniversário da cidade de Penedo, um dos núcleos urbanos mais antigos e históricos do estado de Alagoas. A data recorda a elevação do povoado à categoria de vila em 1636 e, posteriormente, à condição de cidade. O feriado é oficialmente instituído pela Lei Municipal nº 1.016/1995.', 'AL', '2706703');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('12/04/2019', 'Emancipação Política de Bocaiúva do Sul', 'MUNICIPAL', 'Celebração da emancipação política e instalação do município de Bocaiúva do Sul, ocorrida em 12 de abril de 1871. A data é um marco histórico que celebra a elevação da antiga freguesia à categoria de vila, desmembrando-se administrativamente de Curitiba.', 'PR', '4103107');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('12/04/2019', 'Emancipação Política de Dário Meira', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação política e administrativa de Dário Meira, ocorrida em 12 de abril de 1962. A autonomia do município foi estabelecida através da Lei Estadual nº 1.667, sancionada pelo então governador Juracy Magalhães, marcando o desmembramento do território de Boa Nova.', 'BA', '2910008');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('12/04/2019', 'Emancipação Política de Licínio de Almeida', 'MUNICIPAL', 'Feriado que celebra a emancipação política de Licínio de Almeida, oficializada em 12 de abril de 1962 por meio da Lei Estadual nº 1.670. O município, que leva o nome de um ilustre engenheiro da ferrovia Leste Brasileiro, foi desmembrado dos territórios de Urandi e Jacaraci.', 'BA', '2919405');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('12/04/2019', 'Emancipação Política de Serra Dourada', 'MUNICIPAL', 'Celebração do aniversário de emancipação do município de Serra Dourada, ocorrida em 12 de abril de 1962. A data marca a conquista da autonomia político-administrativa e o desmembramento do território original, consolidando-se como um importante polo regional no extremo oeste baiano.', 'BA', '2930303');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('12/04/2019', 'Emancipação de Capão da Canoa', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação político-administrativa de Capão da Canoa, ocorrida em 12 de abril de 1982. O feriado é regido pela Lei Municipal nº 015/1983, celebrando o momento em que o município se tornou independente de Osório.', 'RS', '4304630');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('12/04/2019', 'Emancipação de Nova Araçá', 'MUNICIPAL', 'Celebração da emancipação política e administrativa de Nova Araçá, ocorrida em 12 de abril de 1964. A data marca o início da trajetória independente do município, que teve suas raízes no núcleo colonial de imigrantes italianos da região.', 'RS', '4312807');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('12/04/2019', 'Emancipação de Redentora', 'MUNICIPAL', 'Feriado municipal instituído pela Lei Municipal nº 2.296/2016, celebrando a emancipação político-administrativa de Redentora, ocorrida em 12 de abril de 1964. A data homenageia a história de fundação e a soberania do município gaúcho.', 'RS', '4315404');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('13/04/2019', 'Aniversário de Fortaleza', 'MUNICIPAL', 'conforme Lei Municipal nº 7.535 de 16/06/1994', 'CE', '2304400');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('13/04/2019', 'Aniversário de Harmonia', 'MUNICIPAL', 'Comemoração da emancipação política do município de Harmonia, criado pela Lei Estadual nº 8.562, de 13 de abril de 1988. É feriado municipal em celebração à instalação da autonomia administrativa da cidade.', 'RS', '4309555');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('13/04/2019', 'Aniversário de Paverama', 'MUNICIPAL', 'Feriado instituído no município de Paverama para comemorar seu aniversário de criação. A data remete à Lei Estadual nº 8.561, de 13 de abril de 1988, e é ratificada pela Lei Municipal nº 2.116, de 4 de dezembro de 2009.', 'RS', '4314159');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('13/04/2019', 'Dia da Emancipação de Alpestre', 'MUNICIPAL', 'Comemora a emancipação político-administrativa do município de Alpestre, ocorrida em 13 de abril de 1964. O feriado municipal é fixado pela Lei Municipal nº 258, de 22 de agosto de 1985.', 'RS', '4300505');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('13/04/2019', 'Dia da Emancipação de Entre-Ijuís', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação político-administrativa de Entre-Ijuís, ocorrida em 13 de abril de 1988. A data consta no calendário oficial de feriados do município conforme estabelecido pela Lei Municipal nº 3.309, de 19 de fevereiro de 2020.', 'RS', '4306932');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('13/04/2019', 'Dia de Nossa Senhora da Penha', 'MUNICIPAL', 'Feriado religioso em honra à Padroeira do Estado do Espírito Santo. Trata-se de um feriado móvel celebrado na segunda-feira, oito dias após o domingo de Páscoa (oitava de Páscoa). Em Cariacica, é regido pela Lei Municipal nº 317, de 10 de julho de 1967, em consonância com a Lei Estadual nº 11.010/2019.', 'ES', '3201308');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('13/04/2019', 'Dia do Município de Nova Esperança do Sul', 'MUNICIPAL', 'Feriado em comemoração à emancipação de Nova Esperança do Sul, ocorrida em 13 de abril de 1988 pela Lei Estadual nº 8.559. A data celebra o aniversário da cidade e a conquista de sua autonomia política.', 'RS', '4313037');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('13/04/2019', 'Dia do Município de Planalto', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de emancipação político-administrativa do município de Planalto, ocorrida em 13 de abril de 1964. A data é oficializada como feriado pela Lei Municipal nº 705, de 13 de dezembro de 1983.', 'RS', '4314704');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('13/04/2019', 'Emancipação Política de Itambacuri', 'MUNICIPAL', 'Celebração da elevação de Itambacuri à categoria de cidade e sua emancipação política, ocorrida historicamente em 13 de abril de 1887. O feriado é reconhecido para marcar o aniversário da autonomia administrativa do município.', 'MG', '3132701');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('13/04/2019', 'Emancipação de Terra de Areia', 'MUNICIPAL', 'Feriado municipal que celebra o aniversário de emancipação político-administrativa de Terra de Areia, estabelecida pela Lei Estadual nº 8.555 de 13 de abril de 1988. Marca a independência do município frente ao território de origem.', 'RS', '4321436');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('14/04/2019', 'Aniversário de Botucatu', 'MUNICIPAL', 'Celebração do aniversário de Botucatu, que comemora sua elevação à categoria de cidade pela Lei Provincial nº 394, de 14 de abril de 1855. É um feriado municipal tradicional que celebra a autonomia política do município.', 'SP', '3507506');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('14/04/2019', 'Aniversário de Catanduva', 'MUNICIPAL', 'Feriado municipal em celebração à emancipação político-administrativa de Catanduva, ocorrida em 14 de abril de 1918. A data marca a instalação oficial do município, após o desmembramento de São José do Rio Preto, instituído originalmente pela Lei Estadual nº 1.546 de 1917.', 'SP', '3511102');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('14/04/2019', 'Aniversário de Caçapava', 'MUNICIPAL', 'Feriado municipal que celebra o aniversário de fundação e emancipação de Caçapava, elevada à categoria de cidade em 14 de abril de 1875. A data é instituída oficialmente como feriado pela Lei Municipal nº 4.125, de 31 de março de 2003.', 'SP', '3508504');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('14/04/2019', 'Aniversário de Constantina', 'MUNICIPAL', 'Celebração do aniversário de emancipação político-administrativa de Constantina, oficializada em 14 de abril de 1959 através da Lei Estadual nº 3.716. O feriado homenageia os pioneiros e o desenvolvimento econômico e social do município.', 'RS', '4305801');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('14/04/2019', 'Aniversário de Coronel Bicaco', 'MUNICIPAL', 'Feriado municipal em comemoração à emancipação de Coronel Bicaco, instituída pela Lei Estadual nº 4.733, de 14 de abril de 1964. A data celebra a autonomia do município frente a Santo Augusto e sua trajetória como polo na região Celeiro.', 'RS', '4305900');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('14/04/2019', 'Aniversário de Dom Aquino', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação político-administrativa de Dom Aquino, estabelecida pela Lei Estadual nº 1.195, de 14 de abril de 1958. A celebração é reafirmada anualmente por decretos municipais que regulamentam o calendário de feriados locais.', 'MT', '5103601');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('14/04/2019', 'Aniversário de Gália', 'MUNICIPAL', 'Comemoração da emancipação político-administrativa do município de Gália, ocorrida em 14 de abril de 1928, conforme instituído pela Lei Estadual nº 2.256. A data é celebrada anualmente como o aniversário oficial da ''Princesinha da Seda''.', 'SP', '3516606');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('14/04/2019', 'Aniversário de Nova Xavantina', 'MUNICIPAL', 'Feriado municipal instituído para celebrar a emancipação política de Nova Xavantina, oficializada pela Lei Estadual nº 4.175, de 14 de abril de 1980. A data é um marco para a soberania administrativa do município no estado do Mato Grosso.', 'MT', '5106257');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('14/04/2019', 'Aniversário de Palmas', 'MUNICIPAL', 'Comemoração do aniversário de fundação e emancipação política de Palmas, ocorrida em 14 de abril de 1879. O município, um dos mais antigos do Paraná, celebra nesta data sua trajetória histórica desde o povoamento inicial nos Campos de Palmas.', 'PR', '4117602');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/04/2019', 'Aniversário de Anhembi', 'MUNICIPAL', 'Celebração do aniversário de emancipação política do município de Anhembi, fundado em 15 de abril de 1891. A data é feriado municipal oficial destinado às festividades cívicas da cidade.', 'SP', '3502309');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/04/2019', 'Aniversário de Emancipação de Graça', 'MUNICIPAL', 'Celebração do aniversário de emancipação política do município de Graça, oficializada em 15 de abril de 1988 após desmembramento do território de Mucambo e Viçosa do Ceará, conforme os marcos da Lei Estadual nº 11.428.', 'CE', '2304657');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/04/2019', 'Aniversário de Iacanga', 'MUNICIPAL', 'Feriado municipal que celebra o aniversário de fundação da cidade de Iacanga, ocorrida em 15 de abril de 1925. A data é ratificada pelo calendário oficial de feriados municipais (ex: Decreto nº 1.322/2023).', 'SP', '3519105');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/04/2019', 'Aniversário de Jales e Dia de Santo Expedito', 'MUNICIPAL', 'Feriado municipal que celebra a fundação da cidade de Jales, ocorrida em 15 de abril de 1941 por Euphly Jalles. A data também é consagrada a Santo Expedito, conforme estabelecido no calendário oficial de feriados do município e ratificado por decretos anuais (como o Decreto nº 10.395/2024).', 'SP', '3524808');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/04/2019', 'Aniversário de Rio do Sul', 'MUNICIPAL', 'Comemora a emancipação político-administrativa do município de Rio do Sul, ocorrida em 15 de abril de 1931. A data é feriado municipal oficial, embora a prefeitura costume publicar decretos específicos para eventuais antecipações ou pontos facultativos adjacentes.', 'SC', '4214805');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/04/2019', 'Aniversário de São Francisco do Sul', 'MUNICIPAL', 'Feriado municipal que celebra a elevação de São Francisco do Sul à categoria de cidade, ocorrida em 15 de abril de 1847. Sendo uma das cidades mais antigas do país, a data é um marco cívico fundamental para o estado de Santa Catarina.', 'SC', '4216206');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/04/2019', 'Dia do Evangélico', 'MUNICIPAL', 'Dia do Evangélico', 'CE', '2311405');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/04/2019', 'Dia do Município de Rodeio Bonito', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de Rodeio Bonito, celebrando sua instalação e emancipação política ocorrida em 15 de abril de 1964. O feriado é fixado pela Lei Municipal nº 3.245/2011.', 'RS', '4315909');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/04/2019', 'Emancipação Política de Mata de São João', 'MUNICIPAL', 'Comemoração da emancipação política e administrativa do município de Mata de São João, ocorrida em 15 de abril de 1847. É um feriado civil oficial instituído pela Lei Orgânica e reforçado por decretos municipais de feriados (como o Decreto nº 571/2025).', 'BA', '2921005');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('16/04/2019', 'Aniversário da Cidade', 'MUNICIPAL', 'Comemoração oficial do aniversário e da emancipação política de Canguaretama. Embora a resolução histórica de criação date de 1858, a municipalidade celebra o dia 16 de abril como a data magna da cidade conforme o calendário administrativo local.', 'RN', '2402204');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('16/04/2019', 'Aniversário de Aceguá', 'MUNICIPAL', 'Feriado municipal instituído pela Lei nº 023/2001 do Município de Aceguá, em alusão ao dia 16 de abril, data que assinala a criação oficial do município no ano de 1996.', 'RS', '4300034');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('16/04/2019', 'Aniversário de Codó', 'MUNICIPAL', 'Feriado municipal instituído pela Lei Municipal nº 1.094, de 07 de abril de 1998, em comemoração à emancipação política, administrativa e social do município de Codó, ocorrida originalmente em 16 de abril de 1896.', 'MA', '2103307');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('16/04/2019', 'Aniversário de Montanha', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação político-administrativa da cidade de Montanha, ocorrida em 16 de abril de 1963, conforme estabelecido no calendário oficial de feriados do Poder Executivo Municipal.', 'ES', '3203502');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('16/04/2019', 'Aniversário do Município', 'MUNICIPAL', 'Feriado municipal instituído pela Lei Municipal nº 234, de 29 de abril de 2003, celebrando o aniversário de criação do município de Paulo Bento, cuja emancipação política ocorreu em 16 de abril de 1996.', 'RS', '4314134');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('17/04/2019', 'Aniversário de Bacabal', 'MUNICIPAL', 'Celebração do aniversário do município de Bacabal, que foi elevado à categoria de cidade em 17 de abril de 1920, conforme os termos da Lei Estadual nº 932. A data marca o desmembramento do território de São Luís Gonzaga.', 'MA', '2101202');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('17/04/2019', 'Aniversário de Jarinu', 'MUNICIPAL', 'Celebração do aniversário de fundação e emancipação de Jarinu, ocorrida em 17 de abril de 1949. A data é o feriado municipal mais importante da cidade, celebrando sua autonomia política e história.', 'SP', '3525201');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('17/04/2019', 'Aniversário de Maripá', 'MUNICIPAL', 'Feriado municipal em celebração ao aniversário de emancipação político-administrativa de Maripá, ocorrida em 17 de abril de 1990. A data homenageia a autonomia conquistada pelo município perante a cidade de Palotina.', 'PR', '4115358');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('17/04/2019', 'Aniversário de São José das Palmeiras', 'MUNICIPAL', 'Celebração do aniversário de emancipação do município de São José das Palmeiras, ocorrida em 17 de abril de 1985. A data marca a independência administrativa da localidade, anteriormente vinculada a Santa Helena.', 'PR', '4125456');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('17/04/2019', 'Aniversário de Taquara', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação política de Taquara. Em 17 de abril de 1886, foi assinado o decreto que elevou a então Freguesia da Taquara do Mundo Novo à condição de vila, permitindo sua independência administrativa.', 'RS', '4321204');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('17/04/2019', 'Conquista da Fazenda Araupel', 'MUNICIPAL', 'Feriado municipal estabelecido pela Lei Municipal nº 581/2006. A data recorda a conquista da Fazenda Araupel em 17 de abril de 1996, um marco histórico para o município que originou os assentamentos Ireno Alves dos Santos e Marcos Freire.', 'PR', '4122156');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('17/04/2019', 'Emancipação Política de Santa Leopoldina', 'MUNICIPAL', 'Comemora a emancipação política do município de Santa Leopoldina, ocorrida em 17 de abril de 1887. O feriado é oficialmente instituído pelo Decreto Municipal nº 41, de 16 de abril de 1947.', 'ES', '3204500');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('17/04/2019', 'Fundação de Capela do Alto Alegre', 'MUNICIPAL', 'Feriado municipal em comemoração à fundação da cidade, ocorrida em 17 de abril de 1912. O marco histórico da fundação foi a celebração da primeira missa no local pelo Padre Manoel Maria, então pároco de Mairi.', 'BA', '2906857');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('18/04/2019', 'Aniversário de Bilac', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de fundação da cidade de Bilac, ocorrida em 18 de abril de 1925. A data celebra o início da colonização por famílias de imigrantes italianos e espanhóis e é oficialmente instituída como feriado pela Lei Municipal nº 452, de 9 de abril de 1969.', 'SP', '3506409');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('18/04/2019', 'Dia da Emancipação Política de Itarana', 'MUNICIPAL', 'Celebração da emancipação político-administrativa do município de Itarana, ocorrida em 18 de abril de 1964. O feriado municipal remete à criação do município através da Lei Estadual nº 1.910, de 30 de dezembro de 1963, que determinou seu desmembramento do território de Itaguaçu.', 'ES', '3202900');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('19/04/2019', 'Aniversário de Barra do Bugres', 'MUNICIPAL', 'Comemoração da emancipação político-administrativa do município, ocorrida em 19 de abril de 1944. A data é feriado municipal oficial, conforme estabelecido na legislação local e reafirmado anualmente por decretos do executivo (Ex: Decreto nº 044/2025).', 'MT', '5101704');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('19/04/2019', 'Aniversário de Maracás', 'MUNICIPAL', 'Feriado municipal em celebração ao aniversário de fundação da ''Cidade das Flores''. Maracás foi emancipada em 19 de abril de 1855, sendo uma das datas mais importantes do calendário cívico local.', 'BA', '2920502');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('19/04/2019', 'Aniversário de Pau Brasil', 'MUNICIPAL', 'Feriado municipal instituído pela Lei Estadual nº 1.667 de 19 de abril de 1962, que criou o município de Pau Brasil ao desmembrá-lo de Camacan. A data celebra a soberania política da cidade.', 'BA', '2923902');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('19/04/2019', 'Aniversário de Rosário do Sul', 'MUNICIPAL', 'Feriado municipal celebrando a emancipação política de Rosário do Sul, ocorrida em 19 de abril de 1876 através da Lei Provincial nº 1.020. A data marca o desmembramento dos municípios de Alegrete e São Gabriel.', 'RS', '4316402');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('19/04/2019', 'Aniversário de Vitória do Mearim', 'MUNICIPAL', 'Feriado municipal que celebra a fundação e emancipação política da cidade de Vitória do Mearim, ocorrida em 19 de abril de 1833. É a principal data cívica do município.', 'MA', '2112902');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('19/04/2019', 'Dia da Criação da Colônia de Floresta do Araguaia', 'MUNICIPAL', 'Feriado municipal que celebra a publicação no Diário Oficial do Estado do Pará, em 19 de abril de 1973, da criação da colônia agrícola que deu origem ao município. A data homenageia a fundação do núcleo populacional idealizado pelo Monsenhor Augusto Dias de Brito.', 'PA', '1503044');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('19/04/2019', 'Dia de Santo Expedito (Padroeiro)', 'MUNICIPAL', 'Feriado municipal religioso em honra ao santo das causas justas e urgentes, que dá nome ao município. A cidade é um importante polo de turismo religioso e celebra seu padroeiro com grandes festividades e feriado local legislado.', 'SP', '3548302');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('19/04/2019', 'Dia dos Povos Indígenas', 'MUNICIPAL', 'Feriado municipal instituído para homenagear os povos originários, de profunda relevância histórica em Santa Cruz Cabrália, local do primeiro contato europeu no Brasil e território do povo Pataxó. O feriado é ratificado por normas locais como o Decreto Municipal nº 117/2010.', 'BA', '2927705');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('19/04/2019', 'Dia dos Povos Indígenas', 'MUNICIPAL', 'Feriado municipal em Amarante do Maranhão, cidade que abriga vastos territórios indígenas como a TI Arariboia. A data é oficialmente reconhecida no calendário da prefeitura para valorização da cultura dos povos originários, distinguindo-se do aniversário da cidade (21 de outubro).', 'MA', '2100600');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('19/04/2019', 'Dia dos Povos Indígenas', 'MUNICIPAL', 'Feriado municipal estabelecido pela Lei Municipal nº 1.140, de 31 de março de 2008. O município de Miranda, um dos maiores polos indígenas de Mato Grosso do Sul, oficializou a data para celebrar as tradições e a luta dos povos originários.', 'MS', '5005608');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('19/04/2019', 'Dia dos Povos Indígenas', 'MUNICIPAL', 'Feriado municipal sancionado pelo Executivo para honrar a herança e os direitos das comunidades indígenas da região. Nioaque possui forte vínculo histórico com os povos Terena, e a data é celebrada com eventos culturais e reconhecimento oficial.', 'MS', '5005806');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('19/04/2019', 'Dia dos Povos Indígenas', 'MUNICIPAL', 'Feriado municipal oficializado pela Lei Municipal nº 1.868/2012. Redentora abriga a maior parte da Terra Indígena Guarita, e a data integra a ''Semana do Índio'' no município, focando em programações culturais e combate ao racismo.', 'RS', '4315404');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('19/04/2019', 'Paixão de Cristo', 'MUNICIPAL', 'Paixão de Cristo', 'BA', '2919207');
