INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('20/04/2019', 'Aniversário de Caraguatatuba', 'MUNICIPAL', 'Feriado municipal em celebração à emancipação político-administrativa de Caraguatatuba, ocorrida em 20 de abril de 1857. A cidade comemora sua fundação histórica nesta data, com festividades civis previstas no calendário oficial da prefeitura.', 'SP', '3510500');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('20/04/2019', 'Aniversário de Cunha', 'MUNICIPAL', 'Feriado municipal que celebra a elevação da Vila de Nossa Senhora da Conceição de Cunha à categoria de cidade, ocorrida em 20 de abril de 1858. A data é o principal marco cívico do município de Cunha.', 'SP', '3513603');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('20/04/2019', 'Aniversário de Figueira', 'MUNICIPAL', 'Feriado municipal em comemoração à emancipação política do município de Figueira, desmembrado de Curiúva e oficialmente criado em 20 de abril de 1982 pela Lei Estadual nº 8.245.', 'PR', '4107751');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('20/04/2019', 'Aniversário de Lagarto', 'MUNICIPAL', 'Celebração da elevação da antiga Vila de Nossa Senhora da Piedade à condição de cidade em 20 de abril de 1880. A data de aniversário do município foi consolidada pela Lei Municipal nº 640/2015, que corrigiu equívocos históricos sobre a natureza da emancipação local.', 'SE', '2803500');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('20/04/2019', 'Aniversário de Paranapanema', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de fundação e emancipação política da Estância Turística de Paranapanema, ocorrida em 20 de abril de 1859. A data é oficialmente reconhecida no calendário legislativo, conforme estabelecido pelo Decreto Municipal nº 3.758/2025.', 'SP', '3535804');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('20/04/2019', 'Aniversário de Pesqueira', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação política e a elevação de Pesqueira à categoria de cidade, ocorrida em 20 de abril de 1880. A data integra o calendário oficial de feriados do município, conforme reiterado pelo Decreto Municipal nº 064/2024.', 'PE', '2610905');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('20/04/2019', 'Aniversário de Águas de Santa Bárbara', 'MUNICIPAL', 'Feriado municipal instituído pela Lei Municipal de 16 de outubro de 1967, em comemoração ao aniversário de fundação da Estância Hidromineral de Águas de Santa Bárbara, ocorrida em 20 de abril de 1876.', 'SP', '3500550');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('20/04/2019', 'Emancipação de Lagoão', 'MUNICIPAL', 'Celebração do aniversário de emancipação política e administrativa do município de Lagoão, ocorrida em 20 de abril de 1988. A data marca a autonomia do município e é tradicionalmente celebrada com eventos cívicos locais.', 'RS', '4311254');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/04/2019', 'Aniversário de Itanhaém', 'MUNICIPAL', 'Feriado municipal que comemora a fundação de Itanhaém, a segunda cidade mais antiga do Brasil, fundada em 22 de abril de 1532. O feriado é regido pela Lei Municipal nº 825, de 12 de março de 1968, que estabelece as datas magnas da cidade.', 'SP', '3522109');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/04/2019', 'Aniversário de Laguna Carapã', 'MUNICIPAL', 'Comemoração do aniversário de emancipação político-administrativa do município de Laguna Carapã, criado pela Lei Estadual nº 1.261 em 22 de abril de 1992, após desmembramento de Ponta Porã. É o feriado municipal mais importante da cidade, frequentemente acompanhado por festividades locais como o Concurso do Pé de Soja Solteiro.', 'MS', '5005251');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/04/2019', 'Aniversário de Montalvânia', 'MUNICIPAL', 'Celebração do aniversário de fundação do município de Montalvânia, ocorrida em 22 de abril de 1952 por Antônio Lopo Montalvão. O feriado é oficialmente instituído e confirmado pelo Decreto Municipal nº 48/2025, que fixa o calendário administrativo para o exercício de 2026.', 'MG', '3142700');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/04/2019', 'Aniversário de Pinheiros', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação político-administrativa de Pinheiros, ocorrida em 22 de abril de 1964. A data é formalmente instituída como feriado pela Lei Municipal nº 1.426/2019, consolidando a tradição sociocultural do aniversário da cidade no calendário oficial.', 'ES', '3204104');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/04/2019', 'Descobrimento do Brasil', 'MUNICIPAL', 'Feriado municipal em comemoração ao Descobrimento do Brasil, ocorrido em 22 de abril de 1500 na região de Porto Seguro. A data é ratificada anualmente pelo calendário oficial de feriados do município (Decreto nº 16.844/25) em virtude de sua relevância histórica e fundacional para a localidade.', 'BA', '2925303');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/04/2019', 'Dia da Geminação', 'MUNICIPAL', 'Feriado municipal em Cantanhede (MA) celebrando o ''Dia da Geminação''. A data comemora os laços históricos e o processo de irmandade entre a cidade brasileira e a cidade de Cantanhede, em Portugal, fortalecendo a herança cultural luso-brasileira da região.', 'MA', '2102705');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/04/2019', 'Emancipação Política de Carvalhos', 'MUNICIPAL', 'Feriado municipal alusivo à emancipação política e administrativa do município de Carvalhos, oficializada em 22 de abril de 1941. A data é celebrada conforme a tradição local e fundamentada no histórico de autonomia municipal reconhecido pelo estado de Minas Gerais.', 'MG', '3114808');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/04/2019', 'Homenagem ao Pioneiro e Fundador do Município', 'MUNICIPAL', 'Feriado municipal instituído em homenagem ao pioneiro, fundador e primeiro prefeito de Sapezal, André Antônio Maggi. A data de 22 de abril é oficialmente reconhecida como feriado municipal no calendário da prefeitura para o ano de 2026, conforme legislação local que preserva a memória da colonização da região.', 'MT', '5107875');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/04/2019', 'Segunda após Páscoa', 'MUNICIPAL', 'Segunda-Feira após Páscoa', 'SC', '4205159');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/04/2019', 'Segundo dia de Páscoa', 'MUNICIPAL', 'Segundo dia de Páscoa, conforme lei 636, de 24 de novembro de 1997', 'PR', '4106803');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/04/2019', 'São Benedito', 'MUNICIPAL', 'Dia de São Benedito', 'SP', '3538006');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('22/04/2019', 'São Benedito', 'MUNICIPAL', 'Dia de São Benedito', 'SP', '3550001');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('23/04/2019', 'Aniversário de Capivari do Sul', 'MUNICIPAL', 'Feriado municipal comemorativo à emancipação de Capivari do Sul, ocorrida em 23 de abril de 1996 (Lei Estadual nº 10.741).', 'RS', '4304671');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('23/04/2019', 'Aniversário de Caravelas', 'MUNICIPAL', 'Feriado municipal em celebração à data em que Caravelas foi elevada à categoria de cidade em 23 de abril de 1855, embora sua fundação date do século XVI.', 'BA', '2906907');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('23/04/2019', 'Aniversário de Matos Costa', 'MUNICIPAL', 'Feriado municipal celebrando a emancipação política de Matos Costa, ocorrida em 23 de abril de 1962.', 'SC', '4210704');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('23/04/2019', 'Aniversário de Piraí do Sul', 'MUNICIPAL', 'Feriado municipal em celebração à data de fundação/emancipação de Piraí do Sul, ocorrida em 23 de abril de 1881.', 'PR', '4119400');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('23/04/2019', 'Dia de São Jorge', 'MUNICIPAL', 'Feriado municipal em celebração a São Jorge, Padroeiro da cidade de Ilhéus, conforme estabelecido pela Lei Municipal nº 3.444 de 10 de junho de 2009 e tradição religiosa local.', 'BA', '2913606');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('23/04/2019', 'Dia de São Jorge (Padroeiro)', 'MUNICIPAL', 'Feriado municipal religioso em homenagem a São Jorge, Padroeiro do município de Nova Módica.', 'MG', '3144904');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('23/04/2019', 'Dia de São Jorge (Padroeiro)', 'MUNICIPAL', 'Feriado municipal religioso dedicado a São Jorge, padroeiro que dá nome à cidade de São Jorge d''Oeste.', 'PR', '4125209');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('23/04/2019', 'Dia de São Jorge (Padroeiro)', 'MUNICIPAL', 'Feriado municipal em honra a São Jorge, Padroeiro do município de São Jorge do Ivaí.', 'PR', '4125308');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('23/04/2019', 'Dia de São Jorge (Padroeiro)', 'MUNICIPAL', 'Feriado municipal em honra ao padroeiro São Jorge, conforme tradição e legislação local.', 'RS', '4318440');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('23/04/2019', 'Emancipação Política de Biritinga', 'MUNICIPAL', 'Feriado municipal que celebra a emancipação político-administrativa de Biritinga, ocorrida em 23 de abril de 1962, através da Lei Estadual nº 1.681.', 'BA', '2903607');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('23/04/2019', 'Emancipação Política de Boninal', 'MUNICIPAL', 'Feriado municipal em comemoração à emancipação política de Boninal, estabelecida em 23 de abril de 1962.', 'BA', '2904001');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('23/04/2019', 'Emancipação Política de Craíbas', 'MUNICIPAL', 'Feriado municipal que celebra a autonomia política de Craíbas, desmembrada de Arapiraca em 23 de abril de 1992.', 'AL', '2702355');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('23/04/2019', 'Emancipação Política de Floresta Azul', 'MUNICIPAL', 'Celebração da emancipação do município de Floresta Azul, ocorrida em 23 de abril de 1962 pela Lei Estadual nº 1.681.', 'BA', '2911006');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('23/04/2019', 'Emancipação Política de Itagimirim', 'MUNICIPAL', 'Comemoração da emancipação política do município de Itagimirim, fundado em 23 de abril de 1962 pela Lei Estadual nº 1.681.', 'BA', '2915304');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('23/04/2019', 'Emancipação Política de Teofilândia', 'MUNICIPAL', 'Feriado municipal celebrando a emancipação política de Teofilândia, ocorrida em 23 de abril de 1962.', 'BA', '2931509');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('23/04/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'PB', '2506400');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('23/04/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'SC', '4212270');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/04/2019', 'Aniversário de Nascimento de José Sarney', 'MUNICIPAL', 'Feriado municipal instituído pela Lei Municipal nº 706/1985 em homenagem ao aniversário de nascimento do ex-presidente da República José Sarney, figura política de relevância histórica na região de Pinheiro.', 'MA', '2108603');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/04/2019', 'Aniversário de Oscar Bressane', 'MUNICIPAL', 'Feriado municipal que celebra a fundação e emancipação de Oscar Bressane, ocorrida oficialmente em 24 de abril de 1948. A data é celebrada anualmente com eventos cívicos na cidade.', 'SP', '3534500');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/04/2019', 'Aniversário de Palhoça', 'MUNICIPAL', 'Feriado municipal que comemora a emancipação política e administrativa do município de Palhoça, ocorrida em 24 de abril de 1894. A celebração é oficialmente disciplinada pela Lei Municipal nº 008/1973, com redação atualizada pela Lei nº 127/1974.', 'SC', '4211900');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/04/2019', 'Aniversário de Rio Negrinho', 'MUNICIPAL', 'Feriado que celebra a emancipação político-administrativa de Rio Negrinho, ocorrida em 24 de abril de 1880. A data é o principal marco histórico civil do município catarinense.', 'SC', '4215000');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/04/2019', 'Aniversário de Tarauacá', 'MUNICIPAL', 'Celebra a fundação do município de Tarauacá, ocorrida em 24 de abril de 1913. O feriado é regido pela Lei Municipal nº 152/1979, sendo uma das datas mais tradicionais do calendário acreano.', 'AC', '1200609');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/04/2019', 'Dia de São Fidélis de Sigmaringa (Padroeiro)', 'MUNICIPAL', 'Feriado municipal religioso em honra ao padroeiro da cidade, São Fidélis de Sigmaringa. A data coincide com o dia litúrgico do santo e é celebrada com festividades religiosas e culturais locais.', 'RJ', '3304805');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/04/2019', 'Emancipação Política de Alhandra', 'MUNICIPAL', 'Celebra a emancipação política do município de Alhandra, garantida pela Lei Estadual nº 2.063 de 24 de abril de 1959, que marcou o desmembramento definitivo do território em relação à capital João Pessoa.', 'PB', '2500601');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/04/2019', 'Emancipação Política de Cristinápolis', 'MUNICIPAL', 'Comemora a emancipação política de Cristinápolis, ocorrida em 24 de abril de 1882. O feriado municipal exalta a autonomia administrativa conquistada pelo município junto ao estado de Sergipe.', 'SE', '2801702');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/04/2019', 'Emancipação Política de Maragogi', 'MUNICIPAL', 'Celebração da emancipação política de Maragogi, ocorrida em 24 de abril de 1875, quando a localidade foi elevada à categoria de vila. A data é feriado municipal conforme a Lei Orgânica do Município e decretos anuais de feriados.', 'AL', '2704500');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/04/2019', 'Emancipação Política de Matriz de Camaragibe', 'MUNICIPAL', 'Feriado municipal em comemoração à emancipação política do município de Matriz de Camaragibe, oficializada em 24 de abril de 1958, quando se desmembrou de Passo de Camaragibe.', 'AL', '2705101');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/04/2019', 'Emancipação Política de Santana do Ipanema', 'MUNICIPAL', 'Comemora a data em que Santana do Ipanema foi elevada à categoria de cidade, em 24 de abril de 1875. O feriado é ratificado por decretos anuais (como o Decreto nº 01/2026) fundamentados na tradição histórica local.', 'AL', '2708006');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('24/04/2019', 'Emancipação Política de Água Branca', 'MUNICIPAL', 'Comemora a emancipação política do município de Água Branca, ocorrida em 24 de abril de 1875. A data é oficializada como feriado municipal por decretos executivos anuais e pela Lei Orgânica.', 'AL', '2700102');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/04/2019', 'Aniversário de Arroio do Sal', 'MUNICIPAL', 'Feriado municipal em comemoração ao aniversário de Arroio do Sal, celebrando sua emancipação política ocorrida no ano de 1988.', 'RS', '4301057');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/04/2019', 'Aniversário de Brasilândia', 'MUNICIPAL', 'Comemoração do aniversário de emancipação política e administrativa do município, fundado em 1965. A data foi ratificada como feriado municipal pela Lei nº 2.906/2021.', 'MS', '5002308');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/04/2019', 'Aniversário de Instalação de Tejupá', 'MUNICIPAL', 'Celebração do aniversário de instalação do município de Tejupá, conforme fixado pela Lei Municipal nº 1.032/2011. A data marca a emancipação político-administrativa da cidade.', 'SP', '3554201');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/04/2019', 'Aniversário de Itaberá', 'MUNICIPAL', 'Feriado em comemoração ao aniversário de Itaberá, celebrando sua emancipação política ocorrida em 25 de abril de 1891, quando foi elevada à categoria de município.', 'SP', '3521705');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/04/2019', 'Aniversário de Itacoatiara', 'MUNICIPAL', 'Celebração da elevação de Itacoatiara à categoria de cidade em 25 de abril de 1874. Embora a data de fundação histórica tenha sido revista para setembro, o dia 25 de abril permanece como o feriado tradicional de emancipação política.', 'AM', '1301902');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/04/2019', 'Dia de São Marcos (Padroeiro Municipal)', 'MUNICIPAL', 'Feriado dedicado ao padroeiro do município, São Marcos, conforme estabelecido pela Lei Municipal nº 3.110/2011. A data da emancipação política da cidade é comemorada em 26 de janeiro.', 'ES', '3203908');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/04/2019', 'Dia de São Marcos (Padroeiro Municipal)', 'MUNICIPAL', 'Feriado religioso em homenagem a São Marcos, padroeiro da cidade de Rio Fortuna. A data é distinta da emancipação do município, celebrada em 21 de junho.', 'SC', '4214904');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/04/2019', 'Dia de São Marcos (Padroeiro)', 'MUNICIPAL', 'Feriado religioso em honra a São Marcos, o evangelista e padroeiro da cidade. A data é oficializada pela Lei Municipal nº 751, de 1990.', 'RS', '4319000');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/04/2019', 'Emancipação Política de Feira Grande', 'MUNICIPAL', 'Comemoração da emancipação política do município de Feira Grande, ocorrida em 25 de abril de 1954, por meio da Lei Estadual nº 1.785, quando se desmembrou do território de Traipu.', 'AL', '2702603');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('25/04/2019', 'Emancipação Político-Administrativa de Trajano de Moraes', 'MUNICIPAL', 'Feriado municipal que celebra a autonomia política e administrativa de Trajano de Moraes. A data faz referência ao aniversário de sua instalação como município independente.', 'RJ', '3305901');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/04/2019', 'Aniversário da Cidade', 'MUNICIPAL', 'Feriado que celebra a emancipação político-administrativa de Monteiro Lobato, ocorrida em 26 de abril de 1949 através da Lei Estadual de São Paulo nº 233.', 'SP', '3531704');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/04/2019', 'Aniversário do Município', 'MUNICIPAL', 'Comemoração da emancipação político-administrativa de Abdon Batista. O município foi instituído pela Lei Estadual de Santa Catarina nº 7.581, datada de 26 de abril de 1989.', 'SC', '4200051');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/04/2019', 'Aniversário do Município', 'MUNICIPAL', 'Feriado municipal em comemoração à emancipação político-administrativa de Forquilhinha. O município foi oficialmente criado pela Lei Estadual de Santa Catarina nº 7.584, de 26 de abril de 1989.', 'SC', '4205456');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/04/2019', 'Aniversário do Município', 'MUNICIPAL', 'Feriado municipal alusivo à criação do município de Iraceminha, fundamentada na Lei Estadual de Santa Catarina nº 7.586, promulgada em 26 de abril de 1989.', 'SC', '4207759');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/04/2019', 'Aniversário do Município', 'MUNICIPAL', 'Comemoração oficial do aniversário de Marema, celebrando sua emancipação política ocorrida por meio da Lei Estadual de Santa Catarina nº 7.587, de 26 de abril de 1989.', 'SC', '4210555');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/04/2019', 'Aniversário do Município', 'MUNICIPAL', 'Celebração do aniversário de fundação e emancipação política de Timbó Grande, estabelecida pela Lei Estadual de Santa Catarina nº 7.582, de 26 de abril de 1989.', 'SC', '4218251');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/04/2019', 'Aniversário do Município', 'MUNICIPAL', 'Feriado que marca a emancipação política de Tunápolis, conforme determinado pela Lei Estadual de Santa Catarina nº 7.583, de 26 de abril de 1989.', 'SC', '4218756');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/04/2019', 'Aniversário do Município', 'MUNICIPAL', 'Feriado municipal celebrativo da emancipação política de Vitor Meireles, criado pela Lei Estadual de Santa Catarina nº 7.585, de 26 de abril de 1989.', 'SC', '4219358');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/04/2019', 'Celebração da Primeira Missa no Brasil', 'MUNICIPAL', 'Feriado municipal que celebra o marco histórico da realização da primeira missa em solo brasileiro, ocorrida em 26 de abril de 1500 na Praia de Coroa Vermelha, território do atual município de Santa Cruz Cabrália. A data possui relevância histórica e religiosa nacional.', 'BA', '2927705');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/04/2019', 'Dia de Nossa Senhora do Bom Conselho', 'MUNICIPAL', 'Feriado municipal dedicado à Nossa Senhora do Bom Conselho, padroeira da cidade de Amargosa. A celebração é uma das datas religiosas mais importantes do calendário municipal.', 'BA', '2901007');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/04/2019', 'Dia de Nossa Senhora do Bom Conselho', 'MUNICIPAL', 'Feriado municipal em celebração à padroeira da cidade, Nossa Senhora do Bom Conselho. A data é marcada por eventos religiosos e faz parte do calendário oficial de feriados do município.', 'BA', '2930402');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/04/2019', 'Dia de Nossa Senhora do Bom Conselho', 'MUNICIPAL', 'Data magna municipal dedicada à Nossa Senhora do Bom Conselho, padroeira de Esperança. O feriado é observado anualmente em 26 de abril, conforme tradição religiosa e amparo legal municipal.', 'PB', '2506004');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/04/2019', 'Dia de Nossa Senhora do Bom Conselho', 'MUNICIPAL', 'Feriado em homenagem à padroeira de Princesa Isabel, Nossa Senhora do Bom Conselho. A data é protegida por legislação municipal e reflete a forte devoção religiosa da comunidade local.', 'PB', '2512309');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/04/2019', 'Dia de Nossa Senhora do Bom Conselho', 'MUNICIPAL', 'Feriado religioso em honra à padroeira do município, Nossa Senhora do Bom Conselho. A data é celebrada com festividades litúrgicas e culturais, sendo feriado municipal consolidado pela tradição e legislação local.', 'PE', '2602100');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('27/04/2019', 'Aniversário de Altamira do Paraná', 'MUNICIPAL', 'Celebração do aniversário de emancipação política de Altamira do Paraná, município criado pela Lei Estadual nº 7.571, de 27 de abril de 1982. É um feriado oficial para comemoração da fundação e autonomia local.', 'PR', '4100459');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('27/04/2019', 'Aniversário de Araporã', 'MUNICIPAL', 'Comemoração da emancipação política de Araporã, formalizada pela Lei Estadual nº 10.703, de 27 de abril de 1992. O município celebra anualmente sua autonomia administrativa nesta data.', 'MG', '3103751');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('27/04/2019', 'Aniversário de Entre Folhas', 'MUNICIPAL', 'Feriado que marca o aniversário de emancipação política do município de Entre Folhas, criado pela Lei Estadual nº 10.703, de 27 de abril de 1992, data que consolidou sua separação do município de Caratinga.', 'MG', '3123858');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('27/04/2019', 'Aniversário de Icaraí de Minas', 'MUNICIPAL', 'Feriado municipal referente ao aniversário de emancipação política de Icaraí de Minas, criada pela Lei Estadual nº 12.030, de 27 de dezembro de 1995, mas com comemoração estabelecida em 27 de abril, data em que se consolidou o movimento emancipatório local.', 'MG', '3130051');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('27/04/2019', 'Aniversário de Ipaba', 'MUNICIPAL', 'Comemoração da emancipação política de Ipaba, fundamentada na Lei Estadual nº 10.703, de 27 de abril de 1992. A data celebra a autonomia do município e o desenvolvimento da comunidade local.', 'MG', '3131158');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('27/04/2019', 'Aniversário de Jaíba', 'MUNICIPAL', 'Feriado alusivo ao aniversário de emancipação do município de Jaíba, ocorrida em 27 de abril de 1992, sob a vigência da Lei Estadual nº 10.703. Celebra-se o crescimento e a autonomia administrativa da região.', 'MG', '3135050');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('27/04/2019', 'Aniversário de Juatuba', 'MUNICIPAL', 'Feriado municipal em celebração ao aniversário de emancipação político-administrativa de Juatuba. O município foi criado pela Lei Estadual nº 10.703, de 27 de abril de 1992, desmembrando-se de Mateus Leme.', 'MG', '3136652');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('27/04/2019', 'Aniversário de Leopoldina', 'MUNICIPAL', 'Celebração do aniversário de elevação de Leopoldina à categoria de cidade, ocorrida em 27 de abril de 1854. Trata-se da principal data festiva do município, instituída para preservar a memória histórica de sua autonomia urbana.', 'MG', '3138401');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('27/04/2019', 'Aniversário de Palmópolis', 'MUNICIPAL', 'Feriado municipal em honra ao aniversário de emancipação de Palmópolis, instituída no bojo da Lei Estadual nº 12.030, cujas festividades de criação e autonomia administrativa são celebradas anualmente em 27 de abril.', 'MG', '3146750');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('27/04/2019', 'Aniversário de Pedreiras', 'MUNICIPAL', 'Comemoração da emancipação política e administrativa do município de Pedreiras, ocorrida em 27 de abril de 1920, conforme a Lei Estadual nº 922. A data celebra a autonomia do município em relação a Coroatá.', 'MA', '2108207');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('27/04/2019', 'Aniversário de Ranieri Mazzilli', 'MUNICIPAL', 'Homenagem ao nascimento de Paschoal Ranieri Mazzilli, político cacondense que foi presidente do Brasil. Instituído pela Lei Municipal nº 2.255 de 2005, o feriado celebra o legado do cidadão mais ilustre do município.', 'SP', '3508702');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('27/04/2019', 'Aniversário de Sapeaçu', 'MUNICIPAL', 'Feriado em comemoração ao aniversário de emancipação de Sapeaçu. O município conquistou sua autonomia política através da Lei Estadual nº 508, de 27 de abril de 1953, ao desvincular-se de Cruz das Almas.', 'BA', '2929602');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('27/04/2019', 'Aniversário de Serra Branca', 'MUNICIPAL', 'Feriado municipal em celebração à emancipação política de Serra Branca, ocorrida em 27 de abril de 1960 através da Lei Estadual nº 2.328. A data marca a data solene de instalação do município na Paraíba.', 'PB', '2515500');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('27/04/2019', 'Aniversário de São José da Lapa', 'MUNICIPAL', 'Feriado municipal em celebração ao Aniversário da Cidade, marcando sua emancipação através da Lei Estadual nº 10.703 de 1992 e ratificada pela Lei Municipal nº 003 de 08 de fevereiro de 1993, que fixou as datas comemorativas.', 'MG', '3162955');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('27/04/2019', 'Aniversário de Utinga', 'MUNICIPAL', 'Celebração da emancipação política do município de Utinga, ocorrida em 27 de abril de 1953 sob a Lei Estadual nº 539. A data marca o aniversário da cidade e é feriado municipal oficial.', 'BA', '2932804');
