INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('29/04/2019', 'Aniversário da Cidade', 'MUNICIPAL', 'conforme Lei Municipal nº 431 de 11/04/1973', 'MG', '3131307');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('29/04/2019', 'Aniversário da Cidade', 'MUNICIPAL', 'Emancipação política do Município', 'PB', '2508554');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('29/04/2019', 'Aniversário de Guaratuba', 'MUNICIPAL', 'Feriado em celebração à fundação do município de Guaratuba, ocorrida em 29 de abril de 1771 por ordem real para garantir a ocupação do litoral sul brasileiro.', 'PR', '4109609');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('29/04/2019', 'Aniversário de João Monlevade', 'MUNICIPAL', 'Feriado municipal em comemoração ao ''Dia da Cidade'' e aniversário de emancipação político-administrativa de João Monlevade, instituído pela Lei Municipal nº 749/1986.', 'MG', '3136207');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('29/04/2019', 'Aniversário de Timóteo', 'MUNICIPAL', 'Feriado em celebração ao aniversário de emancipação político-administrativa do município, conforme estabelecido pela Lei Municipal nº 1.833 de 29 de dezembro de 1997.', 'MG', '3168705');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('29/04/2019', 'Criação do Município', 'MUNICIPAL', '', 'PR', '4118857');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('29/04/2019', 'Emancipação Política de Barra de Santana', 'MUNICIPAL', 'Comemoração do aniversário de emancipação política do município, ocorrida em 29 de abril de 1994 e oficializada como feriado pela Lei Municipal nº 034/1998.', 'PB', '2501575');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('29/04/2019', 'Emancipação Política de Filadélfia', 'MUNICIPAL', 'Celebração da emancipação política do município de Filadélfia, ocorrida em 29 de abril de 1985, quando se desmembrou do território de Pindobaçu.', 'BA', '2910859');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('29/04/2019', 'Emancipação Política de São Miguel das Missões', 'MUNICIPAL', 'Comemoração da emancipação política e administrativa do município de São Miguel das Missões, ocorrida em 29 de abril de 1988, ao desmembrar-se de Santo Ângelo.', 'RS', '4319158');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('29/04/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'GO', '5204557');
