INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('29/04/2019', 'Nossa Senhora da Penha', 'MUNICIPAL', 'Sempre comemorado oito dias após o domingo de Páscoa, de acordo com o Decreto nº 16.896', 'ES', '3205309');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('29/04/2019', 'Padroeira de Prazeres', 'MUNICIPAL', 'Dia de N. Sra. dos Prazeres, padroeira de Prazeres', 'PE', '2607901');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('30/04/2019', 'Aniversário de Instalação de Nova Andradina', 'MUNICIPAL', 'Feriado instituído pela Lei Municipal nº 670, de 18 de outubro de 2007, que fixa o dia 30 de abril como feriado oficial para comemorar a instalação do município de Nova Andradina, ocorrida em 1959. Diferencia-se da data de criação (20 de dezembro), sendo o dia 30 de abril a data magna de celebração pública.', 'MS', '5006200');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('30/04/2019', 'Aniversário de Japorã', 'MUNICIPAL', 'Feriado municipal estabelecido pela Lei Municipal nº 012/1993, que institui o dia 30 de abril como feriado em comemoração ao aniversário de criação do município de Japorã, ocorrido em 1992 por meio da Lei Estadual nº 1.266.', 'MS', '5004809');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('30/04/2019', 'Aniversário de Miraselva', 'MUNICIPAL', 'Feriado municipal alusivo ao aniversário de Miraselva, celebrando sua emancipação política e administrativa ocorrida em 30 de abril de 1961. A data é o principal marco cívico do calendário oficial do município paranaense.', 'PR', '4116000');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('30/04/2019', 'Aniversário de Novo Horizonte do Sul', 'MUNICIPAL', 'Feriado municipal comemorativo ao aniversário de Novo Horizonte do Sul, celebrando sua emancipação político-administrativa ocorrida em 30 de abril de 1992, conforme estabelecido na legislação estadual e municipal que criou a unidade administrativa.', 'MS', '5006259');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('30/04/2019', 'Aniversário de Ponta de Pedras', 'MUNICIPAL', 'Feriado municipal em celebração à Emancipação Política de Ponta de Pedras. A data de 30 de abril remete à autonomia do município no contexto histórico do estado do Pará, sendo um dia de comemorações cívicas locais.', 'PA', '1505700');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('30/04/2019', 'Dia de Santa Catarina de Sena (Padroeira)', 'MUNICIPAL', 'Feriado municipal em honra a Santa Catarina de Sena, padroeira de Damianópolis. A celebração religiosa é tradicional no município e é ratificada por decretos executivos anuais (como o Decreto nº 463/2018), que suspendem o expediente nas repartições públicas para as festividades da padroeira.', 'GO', '5206701');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('30/04/2019', 'Dia de São João Bosco (Padroeiro)', 'MUNICIPAL', 'Feriado municipal dedicado a São João Bosco, padroeiro da cidade de Torixoréu. Conforme estabelecido na legislação municipal e reiterado por decretos como o Decreto nº 001/2023, a data é feriado oficial no município para celebrações religiosas e culturais em homenagem ao santo.', 'MT', '5108204');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('30/04/2019', 'Emancipação Política de Boqueirão', 'MUNICIPAL', 'Feriado municipal que celebra a Emancipação Política de Boqueirão, ocorrida em 30 de abril de 1959. A data marca a conquista da autonomia administrativa do município, conhecido como a ''Cidade das Águas'', sendo feriado oficial para as festividades comemorativas.', 'PB', '2502508');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('30/04/2019', 'Emancipação Política de Nilo Peçanha', 'MUNICIPAL', 'Feriado municipal em comemoração à Emancipação Política de Nilo Peçanha, ocorrida em 30 de abril de 1873. A data celebra a autonomia administrativa do município, sendo um marco histórico e cívico fundamental para a identidade local, comemorado anualmente com atos solenes e festividades.', 'BA', '2922607');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('30/04/2019', 'Emancipação Política de São Bento do Una', 'MUNICIPAL', 'Feriado municipal que celebra o aniversário de Emancipação Política de São Bento do Una, ocorrida em 30 de abril de 1860. A data marca a elevação da localidade à categoria de vila e sua autonomia política, sendo a principal celebração cívica do calendário municipal.', 'PE', '2613008');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('30/04/2019', 'Emancipação Política de Tacima', 'MUNICIPAL', 'Feriado municipal em comemoração à Emancipação Política de Tacima, instituída pela Lei nº 2.138 de 30 de abril de 1959. A data celebra a independência administrativa do município, anteriormente distrito de Araruna, e é feriado cívico obrigatório.', 'PB', '2516409');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('30/04/2019', 'Feriado Municipal', 'MUNICIPAL', '', 'PE', '2612208');
